'Custom_SMS_Payload_Hint' => 'Legen Sie die Felder des Anfragetexts fest. Verwenden Sie {phone}, {message} und {sender} als Platzhalter; sie werden beim Senden ersetzt.',
'Custom_SMS_Guide_Title' => 'Konfiguration',
'Custom_SMS_Guide_Intro' => 'Jeder SMS-Anbieter mit HTTP-API kann angebunden werden. Öffnen Sie die API-Dokumentation Ihres Anbieters, kopieren Sie Endpunkt, Methode und Feldnamen und ordnen Sie sie unten mithilfe der Platzhalter zu.',
'Custom_SMS_Guide_Placeholder_Phone' => 'die Telefonnummer des Empfängers',
'Custom_SMS_Guide_Placeholder_Message' => 'der SMS-Text',
'Custom_SMS_Guide_Placeholder_Sender' => 'die oben eingegebene Absenderkennung',
'Custom_SMS_Guide_Api_Url' => 'Die vollständige Endpunkt-URL aus der Dokumentation Ihres Anbieters, z. B. https://api.provider.com/sms/send. Platzhalter sind auch direkt in der URL erlaubt, z. B. ...?to={phone}&text={message}.',
'Custom_SMS_Guide_Method' => 'POST ist am gebräuchlichsten. Wählen Sie GET nur, wenn Ihr Anbieter alles in der URL erwartet – die Payload-Felder werden dann als Query-Parameter gesendet.',
'Custom_SMS_Guide_Content_Type' => '"json" sendet die Payload als JSON-Body (application/json). "form" sendet sie als klassisches HTML-Formular (application/x-www-form-urlencoded). Prüfen Sie, welches Format Ihr Anbieter erwartet; bei GET wird diese Einstellung ignoriert.',
'Custom_SMS_Guide_Sender' => 'Ihre freigegebene Absenderkennung oder sendende Telefonnummer. Sie füllt nur den Platzhalter {sender} – damit sie übertragen wird, muss sie in der Payload, den Headern oder der URL verwendet werden.',
'Custom_SMS_Guide_Success_Keyword' => 'Optional, aber empfohlen. Manche Anbieter antworten mit „200 OK“, auch wenn der Versand fehlschlägt. Geben Sie ein Wort oder einen Textteil ein, der nur in einer erfolgreichen Antwort vorkommt (z. B. success). Enthält die Antwort ihn nicht, gilt die SMS als fehlgeschlagen.',
'Custom_SMS_Guide_Headers' => 'Von Ihrem Anbieter verlangte Authentifizierungs-Header, z. B. Authorization = Bearer YOUR_API_KEY oder Api-Key = YOUR_API_KEY. Fügen Sie keinen Content-Type hinzu – er wird automatisch gesetzt.',
'Custom_SMS_Guide_Payload' => 'Die Felder des Anfragetexts, exakt so benannt wie in der Dokumentation Ihres Anbieters. Verwenden Sie die Platzhalter als Werte, z. B. to = {phone}, message = {message}, from = {sender}.',
'Custom_SMS_Guide_Example' => 'Vollständiges Beispiel',
