'Optimize_pricing_strategy_based_on_margin_analysis' => 'Optimieren Sie Ihre Preisstrategie auf Basis der Margenanalyse',
'Ord_Guide_Lifecycle_Cancelled' => 'Die Bestellung wurde vor der Bestätigung verworfen; es wurde also kein Verkauf angelegt und kein Bestand abgebucht.',
'Ord_Guide_Lifecycle_Confirmed' => 'Sie haben die Bestellung angenommen. Stocky legt im gewählten Lager einen Verkauf an und bucht den Bestand ab — dieser Verkauf ist der Datensatz, auf dem Ihre Bestands-, Zahlungs- und Gewinnberichte basieren.',
'Ord_Guide_Lifecycle_Delivered' => 'Der Kunde hat die Bestellung erhalten. Damit beginnt die Rückgabefrist.',
'Ord_Guide_Lifecycle_Pending' => 'Eine neue Bestellung, die auf Ihre Prüfung wartet. Nur eine ausstehende Bestellung kann bestätigt oder storniert werden.',
'Ord_Guide_Lifecycle_Shipped' => 'Sie haben die Bestellung versendet. Nur Fulfillment: Der Bestand wurde bereits bei der Bestätigung abgebucht.',
'Ord_Guide_MarkPaid_Step1' => 'Bestätigen Sie die Bestellung zuerst hier — erst die Bestätigung legt den Verkauf an.',
'Ord_Guide_MarkPaid_Step2' => 'Öffnen Sie Verkäufe > Alle Verkäufe und suchen Sie diesen Verkauf (gleicher Kunde; die Detailseite zeigt die Online-Bestellung, aus der er stammt).',
'Ord_Guide_MarkPaid_Step3' => 'Öffnen Sie das Aktionsmenü der Zeile und wählen Sie „Zahlung erstellen“.',
'Ord_Guide_MarkPaid_Step4' => 'Geben Sie Betrag, Zahlungsmethode und Datum ein und speichern Sie. Der Verkauf wechselt je nach Betrag automatisch auf „Teilweise“ oder „Bezahlt“.',
'Ord_Guide_Note_Cancel' => 'Stornieren ist nur möglich, solange die Bestellung noch aussteht. Nach der Bestätigung machen Sie sie stattdessen über den Verkauf oder eine Kundenrückgabe rückgängig.',
'Ord_Guide_Note_Flagged' => 'Ein „Markiert“-Tag bedeutet, dass die Bestellung beim Checkout eine Betrugsprüfung ausgelöst hat. Fahren Sie mit der Maus über den Tag, um den Grund zu sehen, und prüfen Sie die Bestellung, bevor Sie sie bestätigen.',
'Ord_Guide_Note_Preorder' => 'Vorbestellartikel überspringen die Bestandsprüfung, daher kann eine Bestellung mit solchen Artikeln auch bestätigt werden, wenn die Menge noch nicht vorrätig ist.',
