'Cr_Guide_Your_Setup' => 'Ihre Einrichtung',
'Cr_Guide_Your_Setup_Help' => 'Der Stand dieses Arbeitsbereichs. Jeder Schritt verlinkt auf die Seite, auf der er erledigt wird.',
'Cr_Guide_Optional' => 'Optional',
'Cr_Guide_Step_Account' => 'Kurierkonto hinzufügen',
'Cr_Guide_Step_Account_Help' => 'Wählen Sie Ihren Kurier und fügen Sie die API-Schlüssel aus dessen Dashboard ein. Mehrere Konten sind möglich, zum Beispiel eines pro Lager.',
'Cr_Guide_Step_Test' => 'Verbindung testen',
'Cr_Guide_Step_Test_Help' => '„Verbindung testen“ prüft die Schlüssel und listet oft die Codes auf, die in den Kurieroptionen abgefragt werden.',
'Cr_Guide_Step_Webhook' => 'Webhook-URL registrieren',
'Cr_Guide_Step_Webhook_Help' => 'Kuriere, die Aktualisierungen senden, benötigen die Webhook-URL des Kontos (unten aufgeführt), damit sich Status sofort ändern. Die übrigen werden nach Zeitplan abgefragt.',
'Cr_Guide_Step_Cod' => 'Ziel für Nachnahme-Auszahlungen wählen',
'Cr_Guide_Step_Cod_Help' => 'Wählen Sie in den Kurier-Einstellungen das Konto, auf dem Nachnahme-Auszahlungen erfasst werden, und wie zurückgesendete Pakete und Kuriergebühren behandelt werden.',
'Cr_Guide_Step_Notify' => 'Kunden informieren',
'Cr_Guide_Step_Notify_Help' => 'SMS, E-Mail oder WhatsApp bei den von Ihnen gewählten Status, mit einem Link zur Sendungsverfolgungsseite.',
'Cr_Guide_Step_Book' => 'Erste Bestellung buchen',
'Cr_Guide_Step_Book_Help' => 'Öffnen Sie in der Verkaufsliste das Menü eines Verkaufs und wählen Sie „An Kurier senden“, oder markieren Sie mehrere Verkäufe und senden Sie sie gemeinsam.',
'Cr_Guide_Step_Errors' => 'Fehler im Blick behalten',
'Cr_Guide_Step_Errors_Help' => 'Keine Kurierfehler in den letzten 24 Stunden.',
'Cr_Guide_Courier_Setup' => 'Kurier-Einrichtung',
'Cr_Guide_Pick_Courier' => 'Wählen Sie einen Kurier, um zu sehen, was er benötigt',
'Cr_Guide_Add_This' => 'Diesen Kurier hinzufügen',
'Cr_Guide_You_Need' => 'Sie benötigen',
'Cr_Guide_No_Keys' => 'Keine API-Schlüssel: Es muss nichts verbunden werden.',
'Cr_Guide_Good_To_Know' => 'Gut zu wissen',
'Cr_Guide_Webhooks' => 'Webhook-Adressen',
'Cr_Guide_How' => 'So registrieren Sie sie',
'Cr_Guide_How_It_Works' => 'So funktioniert es',
'Cr_Guide_Meaning' => 'Bedeutung',
'Cr_Guide_T_Statuses' => 'Status',
'Cr_Guide_Statuses_Note' => 'Status bewegen sich nur vorwärts, sodass eine verspätete Aktualisierung ein Paket nie zurückwirft. Ein zugestelltes Paket kann dennoch als „Rücksendung unterwegs“ oder „Zurückgesendet“ gemeldet werden.',
'Cr_Guide_S_booked' => 'Der Kurier hat die Bestellung; abgeholt wurde sie noch nicht. Nur jetzt kann eine Buchung storniert werden.',
'Cr_Guide_S_picked_up' => 'Der Kurier hat das Paket abgeholt.',
'Cr_Guide_S_in_transit' => 'Unterwegs zwischen Verteilzentren, beim Zoll oder zurückgehalten.',
'Cr_Guide_S_out_for_delivery' => 'Heute beim Zusteller.',
'Cr_Guide_S_failed_attempt' => 'Nicht zu Hause, Annahme verweigert oder falsche Adresse. Der Kurier versucht es erneut oder sendet es zurück.',
'Cr_Guide_S_delivered' => 'An den Kunden übergeben. Ein Nachnahmebetrag gilt als vom Kurier kassiert.',
'Cr_Guide_S_returning' => 'Auf dem Rückweg zu Ihnen.',
'Cr_Guide_S_returned' => 'Wieder bei Ihnen: Es wartet unter „Zu prüfende Rücksendungen“ oder wird automatisch wieder eingelagert.',
'Cr_Guide_S_cancelled' => 'Die Buchung wurde storniert.',
'Cr_Guide_T_Booking' => 'Bestellungen buchen',
'Cr_Guide_B_Booking' => '„An Kurier senden“ füllt das Formular aus dem Verkauf: Empfänger, Adresse, den noch offenen Betrag als Nachnahme und das Gewicht der Produkte. Kuriere mit eigenen Ortslisten zeigen eine Auswahl an, und Ihre Wahl wird für diesen Ort gespeichert. Aggregatoren, DHL, FedEx, UPS und Lalamove bieten „Tarife vergleichen“: Wählen Sie einen Preis, und „Buchen“ kauft ihn. Mehrere Verkäufe können gemeinsam aus der Verkaufsliste gebucht werden.',
'Cr_Guide_T_Cod' => 'Nachnahme',
'Cr_Guide_B_Cod' => 'Ein Nachnahmepaket wechselt von „Nicht kassiert“ über „Vom Kurier kassiert“ (bei Zustellung) zu „An Sie ausgezahlt“. Kuriere, die Auszahlungen melden, setzen den letzten Schritt selbst; für die anderen verwenden Sie „Nachnahme aktualisieren“. Ist in den Kurier-Einstellungen ein Konto gewählt, wird eine Auszahlung als Zahlung beim Verkauf erfasst. Kuriergebühren können als Ausgabe gespeichert werden, sobald ein Paket abgeschlossen ist.',
'Cr_Guide_T_Returns' => 'Zurückgesendete Pakete',
'Cr_Guide_B_Returns' => 'Standardmäßig wartet ein zurückgesendetes Paket unter „Kuriersendungen“ im Bereich „Zu prüfende Rücksendungen“. „Wieder einlagern“ erstellt eine Verkaufsrückgabe für die gesamte Bestellung und bucht die Artikel wieder in den Bestand; „Verwerfen“ lagert nichts ein, für beschädigte oder verlorene Pakete. Alternativ können die Kurier-Einstellungen automatisch wieder einlagern.',
'Cr_Guide_T_Customers' => 'Kundennachrichten und Sendungsverfolgungsseite',
'Cr_Guide_B_Customers' => 'Die Kundenbenachrichtigungen in den Kurier-Einstellungen senden SMS, E-Mail oder WhatsApp bei den von Ihnen markierten Status, jeweils einmal pro Paket und mit Ihrem eigenen Text. Über die Sendungsverfolgungsseite in Ihrem Online-Shop können Kunden ein Paket per Sendungsnummer oder per Bestellnummer und Telefonnummer verfolgen. Kunden, die häufig Pakete zurücksenden, erhalten beim Buchen ein Rücksendungsrisiko-Kennzeichen.',
'Cr_Guide_T_Labels' => 'Etiketten',
'Cr_Guide_B_Labels' => '„Etikett drucken“ liefert das eigene Etikett des Kuriers, sofern er eines ausstellt (PDF, Link oder Bild), andernfalls ein Stocky-Etikett mit dem Sendungsbarcode und dem zu kassierenden Betrag. Erlauben Sie Pop-ups für diese Website, um zu drucken. DHL, FedEx und UPS stellen ihr Etikett nur einmal bei der Buchung bereit; Stocky speichert es für Nachdrucke.',
'Cr_Guide_T_Faq' => 'Fehlerbehebung',
'Cr_Guide_Q_Test' => '„Verbindung testen“ schlägt fehl',
'Cr_Guide_A_Test' => 'Testschlüssel gehören zum Testmodus und Live-Schlüssel zum Live-Modus; sie sind unterschiedlich. Öffnen Sie die Kurier-Protokolle und lesen Sie die Antwort des Kuriers, um den genauen Grund zu erfahren.',
'Cr_Guide_Q_City' => 'Der Kurier lehnt den Ort oder die Adresse ab',
'Cr_Guide_A_City' => 'Wählen Sie den Ort im Buchungsformular aus der Ortsliste des Kuriers; Kuriere akzeptieren nur ihre eigenen Bezeichnungen. Kuriere, die mit Postanschriften arbeiten, benötigen außerdem Bundesland, Postleitzahl und den zweistelligen Ländercode.',
'Cr_Guide_Q_Webhook' => 'Status ändern sich nicht von selbst',
'Cr_Guide_A_Webhook' => 'Prüfen Sie bei Kurieren, die Aktualisierungen senden, ob die Webhook-URL beim Kurier registriert ist: Die Kurier-Protokolle zeigen jede empfangene Aktualisierung oder warum eine abgelehnt wurde (zum Beispiel ein falsches Secret). Andere Kuriere werden nach dem Zeitplan in den Kurier-Einstellungen abgefragt, und „Status jetzt prüfen“ fragt sofort nach.',
'Cr_Guide_Q_Stuck' => 'Eine Sendung zeigt einen Fehler bei der Statusprüfung',
'Cr_Guide_A_Stuck' => 'Der Kurier hat die letzten Abfragen abgelehnt; der Grund steht bei der Sendung und in den Kurier-Protokollen. Nach wiederholten Fehlern wird eine Sendung nicht mehr automatisch geprüft: Beheben Sie die Ursache und verwenden Sie dann „Status jetzt prüfen“.',
'Cr_Guide_Q_Label' => 'Beim Drucken eines Etiketts öffnet sich nichts',
'Cr_Guide_A_Label' => 'Ihr Browser hat das Pop-up blockiert. Erlauben Sie Pop-ups für diese Website und versuchen Sie es erneut.',
'Cr_Guide_Q_Cod' => 'Eine Nachnahme-Auszahlung wurde nicht beim Verkauf erfasst',
'Cr_Guide_A_Cod' => 'In den Kurier-Einstellungen muss die Nachnahme eingeschaltet und ein Konto gewählt sein. Ohne Konto werden Auszahlungen nur als ausgezahlt markiert.',
