'Restrict_Master_Data_By_Warehouse' => 'Stammdaten nach Lager einschränken',
'Restrict_Master_Data_By_Warehouse_Help' => 'Wenn aktiviert, sieht ein Benutzer, der bestimmten Lagern zugewiesen ist, nur die Produkte, Kunden, Lieferanten, Marken und Kategorien, die mit diesen Lagern verknüpft sind. Datensätze, die noch nirgends verwendet wurden, bleiben sichtbar, sodass neu angelegte nie ausgeblendet werden. Verkäufe, Einkäufe und Rückgaben sind immer eingeschränkt und von diesem Schalter nicht betroffen.',
'Restrict_Products_By_Warehouse' => 'Produkte nach Lager einschränken',
'Restrict_Products_By_Warehouse_Help' => 'Jedes Produkt erhält ein Stammlager – die Filiale, für die es angelegt wurde. Wenn aktiviert, sieht, verkauft und bearbeitet ein Benutzer, der bestimmten Lagern zugewiesen ist, nur die Produkte, deren Stammlager zu seinen gehört, sowie Produkte mit tatsächlichem Bestand in einem seiner Lager (umgelagert oder eingekauft). Benutzer mit Zugriff auf alle Lager sehen immer alles. Der Online-Shop folgt derselben Regel: Er listet nur die Produkte der in den Shop-Einstellungen ausgewählten Lager.',
'Virtual_Combo_Stock' => 'Virtueller Kombi-Bestand',
'Virtual_Combo_Stock_Help' => 'Wenn aktiviert, hat ein Kombiprodukt keinen eigenen Bestand: Seine Verfügbarkeit ist die Anzahl der Kombis, die seine Komponenten noch ergeben, und der Verkauf eines Kombis entnimmt den Bestand aus den Komponenten. Wenn deaktiviert, werden Kombis zuerst mit einer Bestandskorrektur in den Bestand aufgenommen.',
'Virtual_Combo_Stock_Warning' => 'Am besten vor dem Verkauf von Kombis festlegen. Wurden bereits Kombis verkauft oder zurückgegeben, führt ein Umschalten dazu, dass spätere Änderungen, Löschungen und Rückgaben dieser Belege den Bestand falsch zurückbuchen.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'Virtuellen Kombi-Bestand aktivieren?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'Kombis werden direkt aus ihren Komponenten verkauft, und ihr eigener Bestand wird nicht mehr verwendet.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'Virtuellen Kombi-Bestand deaktivieren?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'Kombis verwenden wieder ihren eigenen Bestand, der vor dem Verkauf mit einer Bestandskorrektur aus den Komponenten aufgebaut werden muss.',
'Home_Warehouse' => 'Stammlager',
'Home_Warehouse_Hint' => 'Die Filiale, zu der dieses Produkt gehört. Benutzer, die auf andere Lager beschränkt sind, sehen es nicht, es sei denn, Bestand wird zu ihnen umgelagert.',
'Home_Warehouse_Required' => 'Wählen Sie das Lager, zu dem dieses Produkt gehört.',
'Combo_products_required' => 'Fügen Sie dem Kombi mindestens ein Produkt hinzu.',
'Customer_Performance_Help' => 'Zeigt auf der Kundenseite eine Performance-Punktzahl und Bewertung an, basierend auf Zahlungszuverlässigkeit, letztem Kaufzeitpunkt und Rückgabequote.',
'Product_Supplier' => 'Lieferant bei Produkten',
'Product_Supplier_Help' => 'Fügt dem Produktformular ein Feld für den Standardlieferanten hinzu, zeigt ihn als Spalte in der Produktliste an und ermöglicht das Filtern von Produkten nach Lieferant, um eine Nachbestellliste zu erstellen.',
'Default_Supplier_Hint' => 'Bei wem Sie dieses Produkt normalerweise nachbestellen. Filtern Sie die Produktliste nach Lieferant, um alles zu sehen, was Sie dort bestellen müssen.',
