'Closing_Balance' => 'Endsaldo',
'Recon_Intro' => 'Vergleicht den operativen Saldo jedes Kassen- und Bankkontos mit dem Hauptbuchsaldo des verknüpften Sachkontos. Diese Seite ist schreibgeschützt: Sie ändert keinen der beiden Salden.',
'Recon_Auto_Off' => 'Automatische Buchungen sind ausgeschaltet, daher werden neue Transaktionen nicht ins Hauptbuch gebucht und erscheinen als fehlende Buchungen. Schalten Sie sie unter Einstellungen → Funktionsschalter ein.',
