'Tg_Cron_Line_Copied' => 'Cron-Zeile kopiert',
'Tg_Guide_Lead' => 'So erhalten Sie die Benachrichtigungen von Stocky in einem Telegram-Chat, einer Gruppe oder einem Kanal.',
'Tg_Guide_Lead_Cron' => 'Die Cron-Zeile unten ist für diesen Server erstellt und kann direkt dort übernommen werden.',
'Tg_Guide_Set_It_Up' => 'Einrichtung',
'Tg_Guide_Step1_Title' => 'Bot erstellen',
'Tg_Guide_Step1_Body' => 'Öffnen Sie in Telegram einen Chat mit {botfather}, senden Sie {newbot} und wählen Sie einen Namen und einen Benutzernamen für den Bot. BotFather antwortet mit einem {botToken} wie {example} – kopieren Sie es.',
'Tg_Guide_Bot_Token_Lower' => 'Bot-Token',
'Tg_Guide_Step2_Title' => 'Chat-ID ermitteln',
'Tg_Guide_Step2_Intro' => 'Welche ID Sie benötigen, hängt davon ab, wohin die Nachrichten gehen sollen:',
'Tg_Guide_Own_Chat' => 'Ihr eigener Chat',
'Tg_Guide_Own_Chat_Item' => '{label} – senden Sie zuerst eine beliebige Nachricht an Ihren neuen Bot (ein Bot kann keine Unterhaltung beginnen) und schreiben Sie dann {userinfobot} an: Er antwortet mit Ihrer Benutzer-ID.',
'Tg_Guide_Group' => 'Eine Gruppe',
'Tg_Guide_Group_Item' => '{label} – fügen Sie den Bot der Gruppe hinzu und posten Sie dort eine Nachricht.',
'Tg_Guide_Channel' => 'Ein Kanal',
'Tg_Guide_Channel_Item' => '{label} – fügen Sie den Bot als {admin} des Kanals hinzu und posten Sie dort eine Nachricht.',
'Tg_Guide_Administrator' => 'Administrator',
'Tg_Guide_GetUpdates_Intro' => 'Öffnen Sie für eine Gruppe oder einen Kanal diese Adresse mit Ihrem eigenen Token im Browser und laden Sie sie nach dem Posten neu:',
'Tg_Guide_GetUpdates_Note' => 'Suchen Sie nach {chatId}. Die ID einer Gruppe oder eines Kanals ist negativ, z. B. {example} – kopieren Sie sie vollständig, einschließlich Minuszeichen.',
'Tg_Guide_Step3_Title' => 'Hier verbinden',
'Tg_Guide_Step3_Body' => 'Fügen Sie auf dem Tab {settings} das Bot-Token und die Chat-ID ein, wählen Sie {allEvents} oder nur die gewünschten Ereignisse ({events}…), schalten Sie {enable} ein und speichern Sie. Klicken Sie dann auf {sendTest}.',
'Tg_Guide_State_Enabled' => 'aktiviert',
'Tg_Guide_State_Saved_Off' => 'gespeichert, aber ausgeschaltet',
'Tg_Guide_State_Not_Configured' => 'noch nicht konfiguriert',
'Tg_Guide_Chat_Id' => 'Chat {id}',
'Tg_Guide_How_Sent' => 'So werden Nachrichten gesendet',
'Tg_Guide_A_Title' => 'Sofort – nichts zu installieren',
'Tg_Guide_A_Body' => 'Ein in Stocky gespeicherter Verkauf, Einkauf, eine Zahlung oder Ausgabe – an der Kasse oder in der Verwaltung – wird {rightAfter} dem Speichern im selben Request an Telegram gesendet. Kein Cron-Eintrag, kein Queue-Worker, und der Kassierer wartet nie auf Telegram: Der Verkauf ist bereits abgeschlossen, wenn die Nachricht verschickt wird.',
'Tg_Guide_Right_After' => 'unmittelbar nach',
'Tg_Guide_B_Title' => 'Der Cron-Eintrag – für Wiederholungen und Hintergrundereignisse',
'Tg_Guide_B_Body' => 'Zwei Arten von Nachrichten warten stattdessen in einer eigenen Telegram-Warteschlange: ein fehlgeschlagener Versand (Telegram kurzzeitig nicht erreichbar), der in den nächsten Minuten bis zu dreimal wiederholt wird, und Ereignisse, die außerhalb der Verwaltung ausgelöst werden – aus WooCommerce oder Shopify importierte Bestellungen, Artisan-Befehle. Dieser Cron-Eintrag versendet diese und sonst nichts:',
'Tg_Guide_B_Note' => 'Jede Minute ist richtig: Ein Lauf ohne wartende Nachrichten endet sofort. In cPanel gehört dies unter {cronJobs} – verwenden Sie den vollständigen Pfad zu PHP 8.2+, falls {php} älter ist. Verwenden Sie unter Windows die Aufgabenplanung mit dem Programm {php2}, den Argumenten {args} und dem Startverzeichnis {path}.',
'Tg_Guide_N_Waiting' => '{n} warten auf den Versand',
'Tg_Guide_Nothing_Waiting' => 'nichts ausstehend',
'Tg_Guide_N_Gave_Up' => '{n} nach Wiederholungen aufgegeben',
'Tg_Guide_Growing_Hint' => '– wenn diese Zahl weiter wächst, läuft der Cron-Eintrag nicht.',
'Tg_Guide_Without_Cron' => 'Auch ohne Cron-Eintrag kommt alles, was in Stocky gespeichert wird, sofort an; Sie verlieren nur die Wiederholungen und die importierten Bestellungen.',
'Tg_Guide_Else_Title' => 'Alles andere',
'Tg_Guide_Else_Body' => 'Nachrichten zu Ereignissen, die im Hintergrund ausgelöst werden, stellt die Plattform zu – Sie müssen nichts einrichten.',
'Tg_Guide_Not_Arrive' => 'Wenn nichts ankommt',
'Tg_Guide_Err_401' => '{code} – das Bot-Token ist falsch. Fügen Sie es erneut aus BotFather ein.',
'Tg_Guide_Err_400' => '{code} – falsche Chat-ID oder der Bot ist nicht in der Gruppe. Schreiben Sie bei einem persönlichen Chat zuerst den Bot an.',
'Tg_Guide_Err_403' => '{code} – fügen Sie den Bot wieder der Gruppe hinzu bzw. als Administrator des Kanals.',
'Tg_Guide_Test_Works' => 'Der Test funktioniert, Verkäufe aber nicht',
'Tg_Guide_Test_Works_Item' => '{label} – prüfen Sie, ob das Ereignis angehakt (oder {allEvents} gewählt) und der Schalter eingeschaltet ist.',
'Tg_Guide_Imported_Never' => 'Importierte Bestellungen kommen nie an',
'Tg_Guide_Imported_Never_Item' => '{label} – der oben genannte Cron-Eintrag läuft nicht.',
'Jumia_Hero_Title' => 'Jumia-Marktplatz-Synchronisierung',
'Jumia_Hero_Desc' => 'Übertragen Sie Preise und Bestände an Ihre Angebote im Jumia Seller Center und importieren Sie Marktplatzbestellungen als Verkäufe.',
'Jumia_Api_Url_Label' => 'API-URL (Seller-Center-Endpunkt Ihres Landes)',
'Jumia_Account_Email' => 'Konto-E-Mail (User ID)',
'Jumia_Prices_Stock' => 'Preise & Bestand',
'Jumia_Push_Card_Title' => 'Preise & Bestand an Jumia übertragen',
'Jumia_Push_Desc' => 'Sendet den aktuellen Preis und die Menge für jedes Produkt (und jede Variante), dessen SKU mit der {sellerSku} des Jumia-Angebots übereinstimmt. Aktualisierungen werden als Seller-Center-Feeds übermittelt und asynchron verarbeitet – die Feed-ID wird im Tab „Protokolle“ erfasst, und Ablehnungen einzelner Artikel erscheinen in der Feed-Statusansicht des Seller Centers.',
'Jumia_Push_Prices_Stock' => 'Preise & Bestand übertragen',
'Jumia_Orders_Desc' => 'Importiert Marktplatzbestellungen als Verkäufe (Referenzen wie {ref}), zugeordnet zu Ihren Produkten über die Seller SKU. Bereits importierte und stornierte Bestellungen werden übersprungen, regelmäßiges Abrufen ist also unbedenklich. Zahlungen werden nur bei zugestellten Bestellungen als bezahlt markiert (bei Jumia überwiegt Nachnahme).',
'Jumia_Guide_1' => 'Öffnen Sie im Jumia {sellerCenter} Settings → {integrationMgmt} und generieren Sie einen API-Schlüssel.',
'Jumia_Guide_2' => 'Geben Sie die API-URL Ihres Landes ein (z. B. {ng} für Nigeria, {ke} für Kenia, {eg} für Ägypten), die E-Mail-Adresse Ihres Seller-Center-Kontos und den Schlüssel – führen Sie dann {test} aus.',
'Jumia_Guide_3' => 'Stellen Sie sicher, dass die {sellerSku} jedes Jumia-Angebots dem Stocky-Produktcode entspricht – darüber werden sowohl Bestandsübertragungen als auch Bestellzuordnungen abgeglichen.',
'Jumia_Guide_4' => 'Übertragen Sie Preise & Bestand nach Bestandsänderungen; rufen Sie Bestellungen regelmäßig ab (diese Jumia-API bietet keine Webhooks).',
'Jumia_Guide_5' => 'Neue Angebote werden weiterhin im Seller Center angelegt – Jumia verlangt kategoriespezifische Attribute und eine Bildprüfung, die nur das eigene Portal zuverlässig abwickelt.',
'Mc_Hero_Title' => 'Mailchimp-Zielgruppen-Synchronisierung',
'Mc_Hero_Desc' => 'Füllen Sie eine Mailchimp-Zielgruppe mit Ihren Kunden, damit Sie E-Mail-Kampagnen mit Ihrem echten Kundenstamm durchführen können.',
'Mc_Account_Audience' => 'Konto & Zielgruppe',
'Mc_Api_Key_Placeholder' => 'z. B. a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'Zielgruppe',
'Mc_N_Members' => '({n} Mitglieder)',
'Mc_Load_Audiences_To_Pick' => 'Laden Sie die Zielgruppen, um eine auszuwählen',
'Mc_Load_Audiences' => 'Zielgruppen laden',
'Mc_Double_Opt_In_Label' => 'Double-Opt-in – neue Mitglieder erhalten vor der Aufnahme eine Bestätigungs-E-Mail',
'Mc_Recommended_GDPR' => '(empfohlen gemäß DSGVO)',
'Mc_Auto_Sync_New' => 'Neue Kunden bei der Anlage automatisch synchronisieren',
'Mc_With_Email' => 'Mit E-Mail-Adresse',
'Mc_Push_Desc' => 'Fügt jeden Kunden mit E-Mail-Adresse der ausgewählten Zielgruppe hinzu bzw. aktualisiert ihn (inklusive Name und Telefonnummer). Bestehende Mitglieder behalten ihren Abonnementstatus – niemand, der sich abgemeldet hat, wird erneut angemeldet. Kunden ohne E-Mail-Adresse werden ausgelassen.',
'Mc_Double_Opt_In_Off' => 'Double-Opt-in ist deaktiviert',
'Mc_Double_Opt_In_Off_Desc' => 'Neue Mitglieder werden ohne Bestätigungs-E-Mail als angemeldet hinzugefügt. Tun Sie dies nur bei Kunden, die dem Erhalt von Werbung bereits zugestimmt haben.',
'Mc_Guide_1' => 'Öffnen Sie in Mailchimp {path} und erstellen Sie einen Schlüssel (er endet auf {suffix} – dieses Suffix ist Ihr Rechenzentrum).',
'Mc_Guide_2' => 'Fügen Sie den Schlüssel hier ein, speichern Sie, klicken Sie dann auf {load} und wählen Sie die zu füllende Zielgruppe.',
'Mc_Guide_3' => 'Lassen Sie {doi} aktiviert, sofern Ihre Kunden dem Erhalt von Werbe-E-Mails nicht bereits zugestimmt haben.',
'Mc_Double_Opt_In_Lower' => 'Double-Opt-in',
'Mc_Guide_4' => 'Führen Sie {push} für die Erstbefüllung aus; aktivieren Sie {autoSync}, damit neue Kunden automatisch hinzukommen.',
'Mc_Auto_Sync_Lower' => 'die automatische Synchronisierung',
'Mc_Consent_Matters' => 'Einwilligung ist wichtig',
'Mc_Consent_Desc' => 'E-Mails an Personen, die Werbung nie zugestimmt haben, können gegen DSGVO/CAN-SPAM verstoßen und zur Sperrung Ihres Mailchimp-Kontos führen. Beim Double-Opt-in übernimmt Mailchimp die Bestätigung – die sichere Standardeinstellung.',
'Mc_No_Audiences' => 'Für dieses Konto wurden keine Zielgruppen gefunden.',
'Presta_Hero_Desc' => 'Synchronisieren Sie Produkte, Bestände und Bestellungen über die Webservice-API mit Ihrem PrestaShop-Shop.',
'Presta_Webservice_Key' => 'Webservice-Schlüssel',
'Presta_Key_Placeholder' => 'Unter Advanced Parameters → Webservice',
'Presta_Key_Help' => 'Aktivieren Sie den Webservice in PrestaShop (Advanced Parameters → Webservice), erstellen Sie einen Schlüssel mit Berechtigungen für products, stock_availables, orders und customers und fügen Sie ihn hier ein. Wird nur schreibend gespeichert.',
'Presta_Shop_Language_ID' => 'Sprach-ID des Shops',
'Presta_Language_Help' => 'Sprach-ID für Produktnamen beim Übertragen (1 = erste Sprache des Shops).',
'Presta_Push_Desc' => 'Legt fehlende einfache Produkte in PrestaShop an (mit ihrem aktuellen Bestand). Bereits verknüpfte Produkte und Variantenprodukte werden übersprungen – bearbeiten Sie Produktdetails weiterhin in PrestaShop oder rufen Sie sie ab, um die lokale Kopie zu aktualisieren.',
'Presta_Pull_Desc' => 'Importiert PrestaShop-Produkte, ordnet vorhandene über die Referenz (SKU) zu und legt die übrigen an. Kombinationen werden als ihr übergeordnetes Produkt importiert.',
'Presta_Reset_Confirm' => 'Produktverknüpfungen zurücksetzen? Die Bestellhistorie behält ihre Verknüpfungen.',
'Presta_Stock_Desc' => 'Aktualisiert den Shop-Bestand (stock_availables) für jedes verknüpfte Produkt.',
'Presta_Orders_Desc' => 'Importiert Shop-Bestellungen als Verkäufe (Referenzen wie {ref}), die neuesten zuerst. Bereits importierte und stornierte Bestellungen werden übersprungen, regelmäßiges Abrufen ist also unbedenklich. PrestaShop bietet keine Webhooks – führen Sie dies nach geschäftigen Phasen aus.',
'Presta_Guide_1' => 'Öffnen Sie im Backoffice Ihres PrestaShop {path} und aktivieren Sie den Webservice.',
'Presta_Guide_2' => 'Fügen Sie einen neuen Schlüssel hinzu und gewähren Sie {vae} für {products} und {stock} sowie {view} für {orders} und {customers}.',
'Presta_Guide_3' => 'Fügen Sie Shop-URL und Schlüssel im Tab „Verbindung“ ein, speichern Sie und führen Sie {test} aus.',
'Presta_Guide_4' => 'Rufen Sie zuerst Produkte ab, wenn der Shop bereits einen Katalog hat (Zuordnung über Referenz/SKU); übertragen Sie Produkte, um fehlende einfache Produkte anzulegen.',
'Presta_Guide_5' => 'Übertragen Sie den Bestand bei jeder Mengenänderung und rufen Sie Bestellungen regelmäßig ab – PrestaShop bietet keine Webhooks, Bestellungen kommen also nur beim Abrufen an.',
'Presta_Identity_Title' => 'Die Produktidentität ist die Referenz (SKU)',
'Presta_Identity_Desc' => 'Der Produktcode in Stocky wird der Referenz in PrestaShop zugeordnet. Halten Sie die Referenzen auf beiden Seiten einheitlich; Kombinationen (Varianten) werden in Bestellungen über die Referenz zugeordnet, in dieser Version aber nicht übertragen.',
'Gs_Hero_Title' => 'Google-Sheets-Exporte',
