'Gs_Export_Desc' => 'Jeder Export schreibt seinen Tab komplett neu (Kopfzeile + alle Zeilen), sodass die Tabelle immer einen vollständigen, aktuellen Stand zeigt. Große Datenmengen werden in Stapeln gesendet – lassen Sie die Seite geöffnet, bis der Zähler stehen bleibt.',
