'Gs_Guide_1' => 'Erstellen Sie ein Projekt in der {console} und aktivieren Sie die {api} (APIs & Services → Library).',
'Gs_Guide_2' => 'Konfigurieren Sie den {consent} (External). Solange er im Status „Testing“ ist, fügen Sie Ihr Google-Konto als Testnutzer hinzu – beachten Sie, dass Aktualisierungstoken im Testmodus nach 7 Tagen ablaufen; Sie sollten die App für eine dauerhafte Verbindung daher {publish}.',
