'Gs_Snapshots_Title' => 'Momentaufnahmen, keine Live-Synchronisierung',
'Gs_Snapshots_Desc' => 'Exporte schreiben die Tabs „Sales“ / „Products“ / „Customers“ bei Bedarf neu. Für zeilenweise Live-Aktualisierungen bei jedem Verkauf verbinden Sie Zapier – damit lassen sich Zeilen anhängen, sobald Ereignisse eintreten.',
