'Xero_Disconnect_Confirm' => 'Verbindung zur Xero-Organisation trennen? Die Synchronisierung wird angehalten, bis Sie die Verbindung wiederherstellen.',
'Xero_Redirect_Uri_Title' => 'Weiterleitungs-URI für die Xero-App',
'Xero_Redirect_Help' => 'Erstellen Sie auf {link} eine „Web app“ und registrieren Sie diese Weiterleitungs-URI. Hinweis: Xero-Zugriffstoken werden automatisch erneuert, eine Verbindung, die länger als 60 Tage ungenutzt ist, muss jedoch neu verbunden werden.',
'Xero_Contacts_In_Xero' => 'Kontakte in Xero',
'Xero_Invoices_In_Xero' => 'Rechnungen in Xero',
'Xero_Payments_Recorded' => 'Erfasste Zahlungen',
'Xero_Push_Customers_Desc' => 'Legt für jeden Kunden einen Xero-Kontakt an oder aktualisiert ihn. Ein Kunde, dessen Name in Xero bereits existiert, wird mit diesem Kontakt verknüpft.',
'Xero_Push_Sales_As_Invoices' => 'Verkäufe als Rechnungen übertragen',
'Xero_Push_Invoices_Desc' => 'Legt pro Verkauf eine Rechnung mit Status AUTHORISED an (Rechnungsnummer = Referenz des Verkaufs), mit den Positionen des Verkaufs sowie Versand-, Rabatt- und Steuerzeilen, damit die Xero-Summe der Verkaufssumme entspricht. Bereits in Xero vorhandene Verkäufe werden übersprungen – Rechnungen werden nie bearbeitet. Fehlende Kontakte werden automatisch angelegt.',
'Xero_Push_Invoices' => 'Rechnungen übertragen',
'Xero_Reset_Contact_Confirm' => 'Kontaktverknüpfungen zurücksetzen? Bei der nächsten Übertragung werden sie neu verknüpft oder neu angelegt.',
