'Xero_Guide_2' => 'Registrieren Sie die im Tab „Verbindung“ angezeigte Weiterleitungs-URI.',
'Xero_Guide_3' => 'Kopieren Sie die {clientId} der App und generieren Sie ein {clientSecret}; fügen Sie beides hier ein und speichern Sie.',
'Xero_Guide_4' => 'Klicken Sie auf {connect}, melden Sie sich an und wählen Sie die zu verbindende Organisation.',
'Xero_Guide_5' => 'Prüfen Sie die Kontocodes: Das Erlöskonto erhält die Rechnungspositionen; geben Sie einen Bankkontocode an, wenn bezahlte Verkäufe auch Zahlungen erfassen sollen.',
'Xero_Guide_6' => 'Übertragen Sie zuerst Kunden, dann Rechnungen. Rechnungsnummern sind die Referenzen der Verkäufe, sodass Xero Duplikate ablehnt, auch wenn Verknüpfungen zurückgesetzt werden.',
'Xero_Tax_Inclusive_Title' => 'Beträge werden unverändert inklusive Steuer übertragen',
'Xero_Tax_Inclusive_Desc' => 'Rechnungen verwenden NoTax-Zeilen, die den Verkauf exakt abbilden (Artikel + Versand − Rabatt + Steuer), sodass die Summen in Xero immer den Summen in Stocky entsprechen. Ihr Steuerberater kann die Steuer- und Versandzeilen in Xero den richtigen Konten zuordnen.',
'Xero_Org_Connected' => 'Xero-Organisation verbunden.',
'Salla_Hero_Desc' => 'Synchronisieren Sie Produkte, Bestände und Bestellungen mit Ihrem Salla-Shop – Bestellungen kommen automatisch per Webhook an.',
