'Salla_Variants_Linked' => 'Verknüpfte Varianten',
'Salla_Push_Desc' => 'Legt einfache Produkte in Salla anhand der SKU an oder aktualisiert sie. Variantenprodukte werden in dieser Version übersprungen – rufen Sie sie stattdessen aus Salla ab oder ordnen Sie sie über die SKU zu.',
'Salla_Only_Unlinked' => 'Nur noch nicht verknüpfte Produkte',
'Salla_Pull_Desc' => 'Importiert Salla-Produkte (inklusive Varianten), ordnet vorhandene über die SKU zu und legt die übrigen an.',
'Salla_Reset_Confirm' => 'Produkt- & Variantenverknüpfungen zurücksetzen? Die Bestellhistorie behält ihre Verknüpfungen.',
'Salla_Stock_Desc' => 'Sendet die aktuellen Mengen für jedes verknüpfte Produkt (über die SKU) und jede verknüpfte Variante.',
'Salla_Orders_Desc' => 'Neue Salla-Bestellungen kommen normalerweise automatisch per Webhook an und werden zu Verkäufen. Verwenden Sie diesen Abruf, um Bestellungen nachzuholen, die vor der Einrichtung des Webhooks aufgegeben wurden – bereits importierte Bestellungen werden übersprungen.',
'Salla_Guide_1' => 'Erstellen Sie auf {link} eine (private) App und wählen Sie den Autorisierungsablauf {mode}.',
'Salla_Guide_2' => 'Kopieren Sie {clientId} und {clientSecret} der App in den Tab „Verbindung“ und speichern Sie.',
'Salla_Guide_3' => 'Hinterlegen Sie in den Einstellungen der App die im Tab „Verbindung“ angezeigte OAuth-Callback-URL.',
'Salla_Guide_4' => 'Auf der Webhooks-Seite der App: Wählen Sie die Sicherheitsstrategie {signature}, kopieren Sie deren Secret hier in das Feld „Webhook-Secret“, hinterlegen Sie die im Tab „Verbindung“ angezeigte Webhook-URL und abonnieren Sie mindestens {e1}, {e2}, {e3}, {e4}, {e5} und {e6}.',
'Salla_Guide_5' => 'Klicken Sie auf {connect} und genehmigen Sie die App in Ihrem Shop. (Apps im Easy Mode verbinden sich stattdessen automatisch über den Webhook {webhook}.)',
'Salla_Guide_6' => 'Rufen Sie Produkte ab oder übertragen Sie sie und übertragen Sie dann den Bestand. Neue Bestellungen kommen automatisch an und erscheinen unter „Verkäufe“ mit Referenzen wie {ref}.',
'Salla_Identity_Title' => 'Die Produktidentität ist die SKU',
'Salla_Identity_Desc' => 'Der Produktcode in Stocky wird der SKU in Salla zugeordnet. Halten Sie die SKUs auf beiden Seiten einheitlich; Variantenprodukte werden beim Abrufen und in Bestellungen zugeordnet, in dieser Version aber nicht übertragen.',
