'Fbr_Page_Title' => 'FBR Digital Invoicing (Pakistan)',
'Fbr_Token_Saved' => 'Ein Token ist gespeichert (••••{last4}). Leer lassen, um es beizubehalten.',
'Fbr_Token_Obtain' => 'Beziehen Sie das Token über das E-Invoicing-Portal von PRAL / IRIS.',
'Fbr_Token_Placeholder' => 'Token aus dem E-Invoicing-Portal von PRAL / IRIS einfügen',
'Fbr_Guide_What_Title' => 'Was ist FBR Digital Invoicing?',
'Fbr_Guide_What_Body' => 'Gemäß SRO 69(I)/2025 verpflichtet das Federal Board of Revenue (Pakistan) integrierte Unternehmen, Verkaufsrechnungen in Echtzeit elektronisch über die PRAL Digital Invoicing (DI) API zu melden. Jeder akzeptierte Verkauf erhält eine offizielle FBR-Rechnungsnummer, und Belege müssen diese Nummer zusammen mit einem QR-Code zur Verifizierung anzeigen.',
'Fbr_Guide_Steps_Title' => 'Schritte bis zum Livebetrieb',
'Fbr_Guide_Step_1' => 'Registrieren Sie sich im FBR-IRIS-E-Invoicing-Portal und beziehen Sie ein Sicherheitstoken für die Umgebung {sandbox}.',
'Fbr_Guide_Step_2' => 'Konfigurieren Sie Ihr Verkäuferprofil im Tab „Konfiguration“ (NTN/CNIC, Firmenname, Provinz, Adresse), fügen Sie das Token ein und aktivieren Sie die Integration mit der Umgebung {sandbox}.',
'Fbr_Guide_Step_3' => 'Führen Sie Testverkäufe durch, die die Ihnen vom FBR zugewiesenen Szenarien abdecken (wählen Sie das Szenario im Feld „Sandbox-Szenario“). Prüfen Sie im Tab „Dokumente“, ob sie als {valid} zurückkommen.',
'Fbr_Guide_Step_4' => 'Sobald der FBR Ihre Sandbox-Tests freigegeben hat, beziehen Sie das Token für die Umgebung {production} über das Portal, fügen es hier ein und stellen die Umgebung auf {production} um.',
'Fbr_Guide_Step_5' => 'Belege zeigen die FBR-Rechnungsnummer und den QR-Code automatisch an, sobald ein Verkauf akzeptiert wurde – an der Kasse sind keine zusätzlichen Schritte nötig.',
'Fbr_Sandbox_Lower' => 'Sandbox',
'Fbr_Production_Lower' => 'Produktion',
'Fbr_Guide_Note_1' => 'Legen Sie HS-Codes pro Produkt im Produktformular fest (Feld „HS-Code“). Der hier konfigurierte Standard-HS-Code wird nur für Produkte ohne eigenen Code verwendet.',
'Fbr_Guide_Note_2' => 'Nicht registrierte Laufkunden werden dem FBR als „Unregistered“ gemeldet.',
'Fbr_Guide_Note_3' => 'Bei registrierten Käufern muss die NTN im Feld „Steuernummer“ des Kunden eingetragen sein, damit sie als registriert gemeldet werden.',
'Fbr_Guide_Note_4' => 'Fehlgeschlagene oder ungültige Übermittlungen können nach Behebung der Ursache im Tab „Dokumente“ erneut gesendet werden; der Tab „Protokolle“ zeigt den rohen API-Austausch zur Fehlersuche.',
