'Woo_WordPress_Username' => 'WordPress-Benutzername',
'Woo_WordPress_App_Password' => 'WordPress-Anwendungspasswort',
'Woo_Automatic_Sync' => 'Automatische Synchronisierung',
'Woo_Auto_Sync_Intro' => 'Übertragen Sie Änderungen in Stocky sofort an WooCommerce, ohne diese Seite zu öffnen. Jede Übertragung läuft direkt nach dem Speichern der Aktion, sodass die Kasse nie auf WooCommerce warten muss. Die Ergebnisse erscheinen im Tab „Protokolle“.',
'Woo_Auto_Sync_Products_Help' => 'Ein in Stocky erstelltes, bearbeitetes oder dupliziertes Produkt wird an WooCommerce gesendet (Details, Preis, Varianten, Bilder, Bestand). Massenimporte werden nicht übertragen; verwenden Sie nach einem Import „Synchronisieren — POS → WooCommerce“ im Tab „Produkte“.',
'Woo_Auto_Sync_Stock_Help' => 'Jede Bestandsbewegung (POS-Verkauf, Verkauf, Retoure, Einkauf, Bestandskorrektur, Umlagerung) aktualisiert die Menge der betroffenen Produkte in WooCommerce. Nur bereits mit WooCommerce verknüpfte Produkte werden aktualisiert.',
'Woo_Sync_Tuning' => 'Feinabstimmung der Synchronisierung',
'Woo_Sync_Tuning_Intro' => 'Die Standardwerte passen für die meisten Shops. Ändern Sie diese nur, wenn die Synchronisierung auf Ihrem Hosting langsam ist oder in Zeitüberschreitungen läuft. Jeder Wert ist auf einen sicheren Bereich begrenzt; wenn Sie ein Feld leeren, wird der Standardwert wiederhergestellt.',
'Woo_Sync_Guide' => 'Anleitung zur WooCommerce-Synchronisierung',
'Woo_Guide_Getting_Keys' => 'API-Schlüssel erhalten',
'Woo_Guide_Keys_1' => 'Öffnen Sie in WooCommerce: WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Klicken Sie auf „Add key“, wählen Sie „Read/Write“ und kopieren Sie anschließend Consumer Key und Consumer Secret.',
'Woo_Guide_Keys_3' => 'Shop-URL: Ihre Website-URL ohne abschließenden Schrägstrich (z. B. {example}).',
'Woo_Guide_WP_Title' => 'WP-Benutzername und Anwendungspasswort (optional)',
'Woo_Guide_WP_Intro' => 'Diese Felder werden nur für Produktbilder verwendet. Die WooCommerce-API (Shop-URL + Consumer Key/Secret) übernimmt die Synchronisierung von Produkten, Bestand, Kategorien, Marken, Kunden und Bestellungen; die WordPress-REST-API übernimmt die Mediathek (Bilder suchen und hochladen).',
'Woo_Guide_WP_1' => 'Beim Synchronisieren von Produkten oder Bestand kann Stocky Produktbilder anhängen: Zuerst wird in der WordPress-Mediathek anhand des Dateinamens nach einem vorhandenen Bild gesucht; wird keines gefunden, wird das Bild über die WordPress-API hochgeladen.',
'Woo_Guide_WP_2' => 'Verwenden Sie einen WordPress-Benutzer, der Medien verwalten darf (z. B. Administrator). Erstellen Sie in WordPress ein Anwendungspasswort: Benutzer → Profil (oder Ihr Benutzer) → Anwendungspasswörter – fügen Sie ein neues hinzu und tragen Sie es hier ein.',
'Woo_Guide_WP_3' => 'Wenn Sie diese Felder leer lassen, funktioniert die Synchronisierung weiterhin für alle Daten (Produkte, Bestand, Kategorien, Marken, Kunden, Bestellungen); nur das Anhängen von Produktbildern (Suchen/Hochladen) wird übersprungen.',
'Woo_Guide_How_To_Enable' => 'So aktivieren Sie die Synchronisierung',
'Woo_Guide_Enable_1' => 'Geben Sie oben Shop-URL, Consumer Key und Consumer Secret ein und klicken Sie dann auf „Speichern“.',
'Woo_Guide_Enable_2' => 'Prüfen Sie die Zugangsdaten mit „Verbindung testen“.',
'Woo_Guide_Enable_3' => 'Starten Sie bei Bedarf eine manuelle Synchronisierung in einem beliebigen Tab.',
'Woo_Guide_Enable_4' => 'Schalten Sie oben die automatische Synchronisierung ein, um neue und bearbeitete Produkte sowie jede Bestandsänderung sofort an WooCommerce zu übertragen.',
'Woo_Guide_Manual_Sync' => 'Manuelle Synchronisierung (bei Bedarf)',
'Woo_Guide_Manual_1' => 'Die Synchronisierung funktioniert in beide Richtungen: Stocky → WooCommerce und WooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'Die manuelle Synchronisierung ist in allen WooCommerce-Tabs verfügbar (Produkte, Bestand usw.); nutzen Sie die Synchronisierungsaktionen im jeweiligen Tab, um sie bei Bedarf auszuführen.',
'Woo_Guide_Auto_1' => 'Produkte: Wenn aktiviert, wird ein Produkt, das Sie in Stocky erstellen, bearbeiten oder duplizieren, direkt nach dem Speichern an WooCommerce gesendet, gefolgt von seinem Bestand.',
'Woo_Guide_Auto_2' => 'Bestand: Wenn aktiviert, aktualisiert jede Bestandsänderung (POS-Verkauf, Verkauf, Retoure, Einkauf, Bestandskorrektur, Umlagerung) die Menge in WooCommerce. Nur bereits mit WooCommerce verknüpfte Produkte werden aktualisiert.',
'Woo_Guide_Auto_3' => 'Die automatische Synchronisierung überträgt Änderungen nur von Stocky zu WooCommerce. Daten aus WooCommerce (Bestellungen, Kunden, Produkte) werden immer über die Schaltflächen in den Tabs „Bestellungen“, „Kunden“ und „Produkte“ in Stocky übernommen.',
'Woo_Guide_Auto_4' => 'Massenimporte von Produkten werden nicht automatisch gesendet. Verwenden Sie nach einem Import „Synchronisieren — POS → WooCommerce“ im Tab „Produkte“.',
'Woo_Guide_Auto_5' => 'Jede automatische Übertragung wird im Tab „Protokolle“ festgehalten, sodass Sie prüfen können, was gesendet wurde, und Fehler erkennen.',
'Woo_Guide_First_Setup' => 'Ersteinrichtung',
'Woo_Guide_First_1' => 'Führen Sie diese Schritte einmalig in dieser Reihenfolge aus, damit Ihr bestehender Katalog verknüpft wird: „Synchronisieren — POS → WooCommerce“ im Tab „Kategorien“, dann im Tab „Marke“, dann im Tab „Produkte“ und zum Schluss „Bestand synchronisieren“ im Tab „Bestand“. Schalten Sie danach oben die automatische Synchronisierung ein, damit WooCommerce aktuell bleibt.',
'Woo_Guide_First_2' => 'Große Produkt- und Bestandssynchronisierungen laufen in kleinen Stapeln und zeigen ihren Fortschritt im Tab an. Lassen Sie die Seite geöffnet, bis die Synchronisierung abgeschlossen ist; Sie können sie jederzeit anhalten.',
'Woo_Guide_First_3' => 'Wenn eine Synchronisierung mehrere Minuten lang nicht vorankommt, prüfen Sie den Tab „Protokolle“ und wenden Sie sich dann an den Support.',
'Woo_Guide_Notes_1' => 'Das Ändern der Shop-URL oder der API-Schlüssel setzt die Zuordnungen zurück (Produkte, Kategorien, Marken, Kunden); die Einträge werden erneut mit dem (neuen) Shop synchronisiert.',
'Woo_Guide_Notes_2' => 'Halten Sie SKUs zwischen Stocky und WooCommerce einheitlich, um doppelte Produkte zu vermeiden und sicher neu verknüpfen zu können.',
