'Pg_Credentials_Kept' => 'Ihre Zugangsdaten bleiben erhalten – der Checkout des Online-Shops bietet {name} lediglich nicht mehr an, bis Sie es wieder einschalten.',
'Pg_Remove_Credentials_Confirm' => 'Gespeicherte Zugangsdaten für {name} entfernen? Der Checkout bietet {short} dann nicht mehr an.',
