'Pg_Sandbox_Test_Mode' => 'Sandbox (Testmodus)',
'Pg_Stripe_Shared_Notice' => 'Die Stripe-Schlüssel werden vom gesamten System gemeinsam genutzt.',
'Pg_Store_Feature_Not_In_Plan' => 'Zahlungs-Gateways für den Online-Shop und Offline-Zahlungsmethoden gehören zur Funktion „Online-Bestellungen“, die in Ihrem aktuellen Plan nicht enthalten ist.',
'Pg_Intro_Title' => 'Jedes Gateway hier wird im Checkout des ONLINE-SHOPS angeboten, sobald seine Zugangsdaten gespeichert sind und sein Schalter eingeschaltet ist.',
'Pg_Intro_Desc' => 'Jeder Tab hat einen eigenen Ein/Aus-Schalter, der sofort beim Umschalten gespeichert wird: Wird ein Gateway ausgeschaltet, bleiben seine Zugangsdaten erhalten – der Checkout bietet es lediglich nicht mehr an. Stripe-Schlüssel gelten global (Verwaltung und Online-Shop nutzen dieselbe Stripe-Integration). Unter „Offline-Zahlungen“ finden Sie Nachnahme und Mobile Money, die außerhalb des Systems bezahlt werden.',
