'Pg_Label_Razorpay_Key_Secret' => 'RAZORPAY KEY SECRET',
'Pg_Razorpay_Help' => 'Verwendet Razorpay Checkout im Online-Shop (Karten, UPI, Netbanking, Wallets). Ob Test- oder Livemodus, ergibt sich aus dem Schlüsselpaar (rzp_test_/rzp_live_) – es gibt keinen separaten Sandbox-Schalter. Der Checkout bietet Razorpay an, sobald beide Schlüssel gespeichert sind.',
