'Pg_Bkash_Sandbox_Help' => 'EIN verwendet tokenized.sandbox.bka.sh mit Ihren Sandbox-Zugangsdaten; schalten Sie auf AUS, um echte bKash-Konten über tokenized.pay.bka.sh zu belasten.',
'Pg_Bkash_Help' => 'Verwendet bKash Tokenized Checkout (Händler-Zugangsdaten aus dem bKash-Händlerportal). Abrechnung in BDT. Der Checkout bietet bKash an, sobald alle vier Zugangsdaten gespeichert sind.',
