'Pg_Label_Charge_Currency' => 'ABRECHNUNGSWÄHRUNG',
'Pg_Paymob_Currency_Help' => 'Muss mit der Währung Ihres Paymob-Kontos (EGP, SAR, AED, PKR oder OMR) und der Basiswährung Ihres Shops übereinstimmen.',
'Pg_Paymob_Help' => 'Verwendet den Paymob Unified Checkout (Karten, Wallets und lokale Zahlungsmethoden in Ägypten, Saudi-Arabien, den VAE, Pakistan und Oman). Alle fünf Zugangsdaten finden Sie unter Paymob Dashboard → Settings → Account Info + Payment Integrations.',
'Pg_Paymob_Webhook_Help' => 'Der Webhook wird pro Zahlung automatisch gesetzt – keine Einrichtung im Dashboard nötig. Callback-URL zur Absicherung (zur Information):',
