'Pg_Label_Account_Country_Live' => 'KONTOLAND (LIVE)',
'Pg_Myfatoorah_Country_Help' => 'ISO-Code des Landes Ihres MyFatoorah-Kontos – KWT, SAU, QAT, EGY, ARE, BHR, OMN oder JOR. Bestimmt den Live-API-Host; im Sandbox-Modus ignoriert.',
'Pg_Myfatoorah_Currency_Help' => 'Muss mit der Währung Ihres MyFatoorah-Kontos (KWD, SAR, AED, QAR, BHD, OMR, JOD, EGP…) und der Basiswährung Ihres Shops übereinstimmen.',
'Pg_Myfatoorah_Sandbox_Help' => 'EIN verwendet apitest.myfatoorah.com mit einem Demo-API-Token; schalten Sie auf AUS, um echte Kunden über die Live-API zu belasten.',
'Pg_Myfatoorah_Help' => 'Gehosteter Rechnungslink für KNET, mada, Karten, Apple Pay und STC Pay in den GCC-Staaten. Das API-Token finden Sie unter MyFatoorah Vendor Portal → Integration Settings → API Key.',
'Pg_Moyasar_Currency_Help' => 'Standardmäßig SAR – muss mit der Basiswährung Ihres Shops übereinstimmen.',
