'Pg_Xpay_Help' => 'Karten werden in ein XPay-Element eingegeben, das in die Checkout-Seite eingebettet ist (keine Weiterleitung). Jede Zahlung wird serverseitig erneut geprüft, bevor die Bestellung angelegt wird. Hinweis: Das SDK von XPay benötigt das API HMAC Secret im Browser, wie auch in den offiziellen Plugins von XPay.',
