'Pg_Paypal_Webhook_Url_Help' => 'Tragen Sie diese URL in Ihrem PayPal-Dashboard ein. Sie dient als Server-zu-Server-Absicherung, die eine Bestellung abschließt, wenn der Browser des Käufers nie zurückkehrt.',
'Pg_Paypal_Help' => 'Gehosteter PayPal-Checkout (Orders API v2). Der Käufer bestätigt bei PayPal, und die Zahlung wird bei seiner Rückkehr serverseitig eingezogen – eine abgebrochene Bestätigung markiert die Bestellung nie als bezahlt.',
'Pg_Paystack_Webhook_Url_Help' => 'Tragen Sie diese URL in Ihrem Paystack-Dashboard ein. Sie dient als Server-zu-Server-Absicherung, die eine Bestellung abschließt, wenn der Browser des Käufers nie zurückkehrt.',
'Pg_Paystack_Help' => 'Gehosteter Paystack-Checkout für Karten, Banküberweisung und Mobile Money in ganz Afrika. Ob Test- oder Livemodus, ergibt sich aus dem Schlüsselpaar, daher gibt es keinen Sandbox-Schalter.',
'Pg_Label_Secret_Hash' => 'SECRET HASH',
