'Pg_Flutterwave_Help' => 'Gehosteter Flutterwave v3 Standard Checkout. Ob Test- oder Livemodus, ergibt sich aus dem Schlüsselpaar (FLWSECK_TEST- vs. FLWSECK-), daher gibt es keinen Sandbox-Schalter.',
'Pg_Flutterwave_Hash_Help' => 'Hinterlegen Sie denselben Secret Hash in Ihrem Flutterwave-Dashboard unter Settings → Webhooks. Ohne ihn werden Webhook-Ereignisse abgelehnt, und nur die Browser-Rückleitung kann eine Bestellung abschließen.',
