'Shp_Scheduler_Hint' => 'Der Zeitplaner prüft alle 5 Minuten; das ist die feinste Auflösung, die die Intervalle unten nutzen können. Synchronisierungen können jederzeit manuell gestartet werden.',
'Shp_Instant_Push_Hint' => 'Ein Verkauf, eine Retoure oder eine Bestandskorrektur löst beim Speichern sofort eine Bestandsübertragung nur für die betroffenen Produkte aus, sodass der Shop innerhalb von Sekunden stimmt statt erst beim nächsten geplanten Lauf. Nichts weiter zu installieren – die Übertragung läuft, nachdem der Verkauf beantwortet wurde, sodass die Kasse nie auf Shopify wartet.',
'Shp_Switch_Inventory_First' => 'Schalten Sie zuerst „Inventar“ unter {tab} ein.',
'Shp_Leave_Off_Lag' => 'Bleibt dies ausgeschaltet, erreicht ein POS-Verkauf Shopify erst beim nächsten Schritt „Inventar senden“ – bis zu {n} Minuten später.',
'Shp_Default_Interval' => 'Standardintervall (Minuten)',
'Shp_Default_Interval_Hint' => 'Gilt für jeden Schritt, der kein eigenes Intervall festlegt.',
'Shp_What_Runs_Auto' => 'Was automatisch läuft',
'Shp_Plan_Hint' => 'Jeder Schritt ist eine Entität in eine Richtung. Bestellungen kommen immer nur {from} Shopify.',
'Shp_From' => 'von',
'Shp_Add_Step' => 'Schritt hinzufügen',
'Shp_Using_Default_Plan' => 'Standardplan wird verwendet',
'Shp_Default_Plan_Desc' => 'Bestellungen werden abgerufen und der Bestand wird gesendet, alle {n} Minuten. Fügen Sie einen Schritt hinzu, um selbst zu wählen – wenn Sie die Liste wieder leeren, gilt erneut dieser Standard.',
'Shp_N_Min' => '{n} Min.',
'Shp_Step_Entity_Off' => '{entity} ist im vorherigen Tab ausgeschaltet – dieser Schritt wird übersprungen.',
'Shp_Inactive_Lc' => 'inaktiv',
'Shp_No_Locations' => 'Dieser Shop meldet keine Standorte',
'Shp_Could_Not_Load_Locations' => 'Standorte konnten nicht geladen werden – prüfen Sie zuerst die Verbindung',
'Shp_Store_Updated' => 'Shop aktualisiert',
'Shp_Store_Connected' => 'Shop verbunden',
'Shp_Could_Not_Save_Store' => 'Dieser Shop konnte nicht gespeichert werden',
'Shp_G_Lead_Store' => 'Was dieser Shop braucht, um synchron zu bleiben. Alles hier bezieht sich speziell auf diesen Shop – die Webhook-URL und die IDs sind echt.',
'Shp_G_Lead_Store_Cmd' => 'Was dieser Shop braucht, um synchron zu bleiben. Alles hier bezieht sich speziell auf diesen Shop – die Webhook-URL und die IDs sind echt, sodass Sie die Befehle direkt auf dem Server verwenden können.',
'Shp_G_Lead_Generic' => 'Wie ein Shopify-Shop mit dem ERP synchron bleibt. Wählen Sie oben einen Shop, um seinen Status zu sehen, oder lesen Sie die Anleitung so, wie sie ist – die Webhook-URL ist für jeden verbundenen Shop dieselbe.',
'Shp_G_Lead_Generic_Cron' => 'Wie ein Shopify-Shop mit dem ERP synchron bleibt. Wählen Sie oben einen Shop, um seinen Status zu sehen, oder lesen Sie die Anleitung so, wie sie ist – die Webhook-URL und die Cron-Zeile sind für jeden verbundenen Shop dieselben.',
'Shp_G_Ways_Note' => 'Die meisten Shops nutzen beides: Das Erste hält den Shop minutengenau aktuell, das Zweite fängt auf, was dem Ersten entgangen ist – einen Webhook, der nie angekommen ist, eine Änderung direkt im Shopify-Admin, eine Nacht, in der die Website nicht erreichbar war.',
'Shp_G_Both_Need' => 'Beide Wege benötigen zuerst Folgendes',
'Shp_G_Credentials' => 'Shopify-Zugangsdaten',
'Shp_G_Cred_Intro' => 'Seit Januar 2026 legt Shopify keine benutzerdefinierten Apps mehr im Admin an, daher gibt es zwei Arten von Verbindungen:',
'Shp_G_Cred_Dev' => '{app} (jeder jetzt verbundene Shop) – {path}. Gewähren Sie die Admin-API-Scopes für das, was dieser Shop synchronisiert, installieren Sie die App im Shop und kopieren Sie dann {clientId} und {clientSecret} von der Settings-Seite der App nach {edit}. Das ERP tauscht sie selbst gegen ein Zugriffstoken und erneuert es, bevor es nach 24 Stunden abläuft. Das Client-Secret signiert auch Webhooks, weiter ist also nichts nötig. App und Shop müssen zur selben Shopify-Organisation gehören.',
'Shp_G_Dev_App' => 'Dev-Dashboard-App',
'Shp_G_Cred_Legacy' => '{app} (vor 2026 im Admin erstellt) – funktioniert unverändert weiter mit ihrem {token} ({prefix}) und ihrem {secret} als Webhook-Signatur-Secret. Dies ist nicht derselbe Wert wie das Token; eine Verwechslung der beiden ist der häufigste Grund, warum Webhooks abgelehnt werden.',
'Shp_G_Legacy_App' => 'Ältere benutzerdefinierte App',
'Shp_G_Api_Secret_Key' => 'API secret key',
'Shp_G_Stored' => 'gespeichert',
'Shp_G_Missing_Refused' => 'fehlt – Zustellungen werden abgelehnt',
'Shp_G_Targets' => '{path} Das ERP-Lager, dessen Bestand dieser Shop verkauft, und der Shopify-Standort, in den dieser Bestand geschrieben wird. Inventarsynchronisierung und Bestellimport laufen ohne diese Angaben nicht.',
'Shp_G_Currently' => 'Aktuell: Lager {warehouse}, Standort {location}',
'Shp_G_Not_Set_Lc' => 'nicht festgelegt',
'Shp_G_Ready' => 'bereit',
'Shp_G_Incomplete' => 'unvollständig',
'Shp_G_Manual_Syncs' => 'Manuell gestartete Synchronisierungen',
'Shp_G_Manual_Body' => 'Eine im {centre} gestartete Synchronisierung antwortet sofort und läuft im Hintergrund weiter, in kurzen Abschnitten, die jeweils dort fortsetzen, wo der vorherige aufgehört hat. Ein großer Katalog wird so nie durch eine Webanfrage mit Zeitüberschreitung mittendrin abgebrochen, und das Schließen der Seite stoppt die Synchronisierung nicht.',
'Shp_G_Worker_Managed' => 'Ihre Plattform betreibt den Worker dafür, es ist also nichts zu installieren.',
'Shp_G_Worker_Cron' => 'Der Worker dafür ist eine weitere Cron-Zeile:',
'Shp_G_Cron_Copied' => 'Cron-Zeile kopiert',
'Shp_G_Worker_Busy' => 'Ist der Worker ausgelastet, führt die geöffnete Seite des Sync-Centers den Lauf nach einigen Sekunden selbst fort, jeweils mit einer kurzen Anfrage – so wird eine Synchronisierung immer abgeschlossen, während Sie zusehen.',
'Shp_G_Pick_How' => 'Wählen Sie dann, wie der Shop synchron bleibt',
'Shp_G_Right_Away' => 'Sofort',
'Shp_G_Stock_Live' => 'Bestand live',
'Shp_G_Stock_Not_Live' => 'Bestand nicht live',
'Shp_G_Realtime_Lead' => 'Jede Änderung wird sofort, innerhalb von Sekunden, übertragen. Es gibt zwei Hälften mit getrennten Schaltern: {webhooks} holen die Ereignisse des Shops ins ERP, die {push} sendet den Bestand nach außen.',
'Shp_G_Webhooks_Lc' => 'Webhooks',
'Shp_G_Instant_Push_Lc' => 'sofortige Bestandsübertragung',
'Shp_G_Webhooks_Heading' => 'Webhooks – Shop → ERP',
'Shp_G_Webhooks_Body' => 'Bestellungen, Statusänderungen von Bestellungen sowie Änderungen an Produkten, Kunden und Bestand in Shopify. Öffnen Sie den Shop und klicken Sie im {tab} auf {button} – mehrfaches Klicken ist unbedenklich. Shopify sendet an:',
'Shp_G_Webhooks_Tab' => 'Tab „Webhooks“',
'Shp_G_Webhooks_Note' => 'Die Adresse muss aus dem Internet über HTTPS erreichbar sein – Shopify stellt nicht an {localhost} oder eine {test}-Domain zu. Jede Zustellung wird nur einmal erfasst, sodass Wiederholungen durch Shopify keine doppelte Bestellung erzeugen können, und eine fehlgeschlagene Zustellung kann erneut verarbeitet werden. Zustellungen werden abgelehnt, bis das Signatur-Secret aus Schritt 1 gespeichert ist.',
'Shp_G_Push_Heading' => 'Sofortige Bestandsübertragung – ERP → Shop',
'Shp_G_People_Miss' => 'Diese Einstellung wird am häufigsten übersehen',
'Shp_G_Push_P1' => 'Ein POS-Verkauf erreicht Shopify {not} von selbst. Ist die Einstellung ausgeschaltet, erfährt der Shop erst beim nächsten Schritt „Inventar senden“ davon – und in diesem Zeitfenster kann er eine Einheit verkaufen, die Sie bereits an der Kasse verkauft haben.',
'Shp_G_Not' => 'nicht',
'Shp_G_Push_P2' => 'Aktivieren Sie {setting} unter {path}. Das ist die gesamte Einrichtung – kein Worker, kein Cron. Jeder Verkauf, jede Retoure und jede Bestandskorrektur sendet dann direkt nach dem Speichern eine Übertragung nur für die betroffenen Produkte, und ein Verkauf mit zwanzig Positionen kostet eine Übertragung, nicht zwanzig. Die Kasse wartet nie darauf.',
'Shp_G_This_Store' => 'Dieser Shop:',
'Shp_G_Push_On' => 'ein – Bestand wird bei Änderung übertragen',
'Shp_G_Push_Off' => 'aus – Bestand nur nach Zeitplan',
'Shp_G_Push_Note' => 'Übertragen werden nur Produkte, die bereits eine Shopify-Zuordnung haben, und nur Bewegungen im Lager dieses Shops. Massenvorgänge – das Löschen eines Produkts, das Zurücksetzen eines Lagers – schreiben den Bestand, ohne ein Ereignis auszulösen; auch deshalb sollten Sie den geplanten Inventarschritt beibehalten.',
'Shp_G_Nothing_Else' => 'Nichts weiter zu installieren',
'Shp_G_Nothing_Else_Body' => 'Keine der beiden Hälften benötigt einen Queue-Worker oder einen Cron-Eintrag. Ein eingehender Webhook wird in der Anfrage verarbeitet, die Shopify stellt; eine ausgehende Bestandsübertragung läuft im selben Prozess, der den Verkauf verarbeitet hat, {after} die Antwort zurückgesendet wurde – die Kasse wartet also nie auf Shopify, und bei einem Shop, der nicht mehr antwortet, wird nach zehn Sekunden aufgegeben und die nächste geplante Inventarübertragung übernimmt.',
'Shp_G_After' => 'nachdem',
'Shp_G_Exception' => 'Eine Ausnahme: Eine Bestandsänderung durch eine Hintergrundaufgabe hat keine Antwort, nach der sie laufen könnte, daher wird sie stattdessen in der Queue {queue} eingereiht.',
'Shp_G_Queue_Managed' => 'Ihre Plattform betreibt bereits einen Worker für diese Queue, daher werden auch diese Übertragungen automatisch gesendet.',
'Shp_G_Queue_Cron' => 'Wenn auch diese zeitnah gesendet werden sollen, arbeiten Sie diese Queue ab:',
'Shp_G_On_Schedule' => 'Nach Zeitplan',
'Shp_G_On_Lc' => 'ein',
'Shp_G_Off_Lc' => 'aus',
'Shp_G_Scheduled_Lead' => 'Alles wird regelmäßig in beide Richtungen erneut geprüft. Langsamer als Echtzeit, aber so wird der Bestand bei Shops ohne sofortige Übertragung gesendet, ein verpasster Webhook aufgefangen – und nur so lässt sich ein ganzer Katalog übertragen.',
'Shp_G_Nothing_To_Install' => 'Nichts zu installieren',
'Shp_G_Managed_Body' => 'Der Zeitplaner wird für Sie betrieben: Alle fünf Minuten fragt Ihre Plattform jeden Shop, ob ein Schritt seines Plans fällig ist, und führt die fälligen aus. Es muss kein Cron-Eintrag hinzugefügt und kein Server betreut werden.',
'Shp_G_Managed_Note' => 'Fünf Minuten sind auch die feinste Auflösung, die ein Plan nutzen kann, da fünf Minuten das kürzeste Schrittintervall sind. Längere Intervalle werden genau eingehalten – ein auf 30 Minuten eingestellter Schritt wird sechsmal geprüft und läuft einmal.',
'Shp_G_Cron_Entry' => 'Der Cron-Eintrag',
'Shp_G_Cron_Body' => 'Ohne ihn läuft nichts Geplantes. Eine Zeile, nur für dieses Modul – fügen Sie sie neben allem anderen ein, das Sie bereits planen:',
'Shp_G_Cron_Note' => 'Alle fünf Minuten ist die feinste Auflösung, die ein Plan nutzen kann, da fünf Minuten das kürzeste Schrittintervall sind. Ein gröberer Eintrag wird einfach zur Untergrenze – mit {every15} läuft ein auf 5 Minuten eingestellter Schritt alle 15 Minuten. Verwenden Sie unter Windows die Aufgabenplanung: Programm {php}, Argumente {args}, Starten in {path}.',
'Shp_G_Switch_On' => 'Einschalten und Plan wählen',
'Shp_G_Plan_Body' => '{path} Der Schalter entscheidet, ob der Zeitplaner überhaupt tätig werden darf; der Plan entscheidet, was er tut. Ein {step} ist eine Entität in eine Richtung mit eigenem Intervall – {ex1}, {ex2}. Das Standardintervall gilt für jeden Schritt, dessen eigenes Feld leer bleibt.',
'Shp_G_Step_Lc' => 'Schritt',
'Shp_G_Ex1' => 'Bestellungen · Shopify → ERP alle 15 Min.',
'Shp_G_Ex2' => 'Inventar · ERP → Shopify alle 30 Min.',
'Shp_G_Plan_Note' => 'Lassen Sie den Plan leer, ruft der Shop Bestellungen ab und überträgt den Bestand im Standardintervall – das ist, was die meisten Shops wollen. Bestellungen werden nur abgerufen: Shopify ist der Ort, an dem ein Kunde bestellt.',
'Shp_G_Schedule_On' => 'Zeitplan ein',
'Shp_G_Schedule_Off' => 'Zeitplan aus – nur manuell',
'Shp_G_When_Runs' => 'Wann ein Schritt tatsächlich läuft',
'Shp_G_When_Body' => 'Ein Schritt ist fällig, wenn derselbe Schritt zuletzt vor mehr als seinem Intervall {started} wurde, gemessen am Laufverlauf. Eine manuell gestartete Synchronisierung verschiebt also die nächste automatische, und ein Schritt, der immer wieder fehlschlägt, wird in seinem Intervall erneut versucht statt bei jedem Takt. Die Übersicht des Shops zeigt für jeden Schritt den letzten Lauf, die nächste Fälligkeit und gegebenenfalls den Grund, warum er blockiert ist. Führen Sie die erste Katalogübertragung manuell im Sync-Center aus – zuerst als Testlauf –, bevor Sie sie in einen Zeitplan aufnehmen.',
'Shp_G_Started_Lc' => 'gestartet',
'Shp_G_Where_Setting' => 'Wo welche Einstellung zu finden ist',
'Shp_G_Where_Note' => 'Alle diese Einstellungen befinden sich bei einem bestehenden Shop: {path}, dann das Stiftsymbol (oder {edit} auf der Seite des Shops).',
'Shp_G_Product_Images' => 'Produktbilder',
'Shp_G_Img1' => 'Bilder werden bei einer {push} mit dem Produkt übertragen – zuerst das Hauptbild, dann die Galerie, dann eines pro Variante mit eigenem Bild, bis zu fünfzig.',
'Shp_G_Products_Push' => 'Produktübertragung',
'Shp_G_Img2' => 'Das Bild einer Variante wird mit dem Produkt hochgeladen und dann {assigned} – so bildet Shopify das ab: Eine Variante verweist auf eines der Bilder des Produkts. Verwendet eine Variante das Hauptbild, wird es nicht doppelt hochgeladen.',
'Shp_G_Assigned' => 'dieser Variante zugewiesen',
'Shp_G_Img3' => 'Ein als Datei gespeichertes Bild wird zu Shopify {uploaded}, nicht verlinkt; das funktioniert also auch, wenn diese Installation nicht aus dem Internet erreichbar ist. Ein als eingefügter Link hinzugefügtes Bild wird Shopify als diese URL übergeben, die öffentlich erreichbar sein muss.',
'Shp_G_Uploaded' => 'hochgeladen',
'Shp_G_Img4' => 'Bilder werden nur erneut gesendet, wenn sie sich tatsächlich ändern – eine Übertragung, die nur einen Preis ändert, lässt die Bilder des Shops unberührt, da beim Senden der gesamte Bildersatz ersetzt wird.',
'Shp_G_Img5' => 'Wenn Sie ein Bild im ERP entfernen, wird es in Shopify {not} gelöscht. Löschen Sie es auch dort, sonst zeigt der Shop es weiterhin an.',
'Shp_G_Commands' => 'Nützliche Befehle',
'Shp_G_Command_Copied' => 'Befehl kopiert',
'Shp_G_Foot' => 'Jede Synchronisierung schreibt in {logs}, und die Übersicht jedes Shops zeigt, wann jeder Schritt zuletzt gelaufen ist, wann er als Nächstes fällig ist und was ihn gegebenenfalls blockiert. Dort sollten Sie zuerst nachsehen, wenn eine Synchronisierung nicht das getan hat, was Sie erwartet haben.',
'Shp_G_Covers' => 'Umfasst',
'Shp_G_Speed' => 'Geschwindigkeit',
'Shp_G_Needs' => 'Benötigt',
'Shp_G_Switched_On_At' => 'Einzuschalten unter',
'Shp_G_Way_Covers_Rt' => 'Bestellungen und Änderungen in Shopify; Bestand, der das ERP verlässt (ein POS-Verkauf, eine Retoure, eine Bestandskorrektur)',
'Shp_G_Way_Covers_Sc' => 'Alles, in beide Richtungen – einschließlich Katalogübertragungen und allem, was der schnelle Weg verpasst hat',
'Shp_G_Seconds' => 'Sekunden',
'Shp_G_Way_Speed_Sc' => 'Das Intervall des Schritts (5 Minuten bis 7 Tage)',
'Shp_G_Way_Needs_Rt' => 'Eine öffentliche HTTPS-Adresse und das Signatur-Secret für eingehende Webhooks. Ausgehender Bestand benötigt gar nichts',
'Shp_G_Way_Needs_Sc' => 'Den Zeitplaner, alle fünf Minuten',
'Shp_G_Way_Switch_Sc' => '{path}, dazu der Plan',
'Shp_G_Scope_Orders' => '{a} ({b} für Bestellungen, die älter als 60 Tage sind)',
'Shp_G_Admin_Scopes' => 'Admin-API-Scopes',
'Shp_G_Setting' => 'Einstellung',
'Shp_G_Tab_In_Edit' => 'Tab in „Shop bearbeiten“',
'Shp_G_Set1' => 'Client-ID + Secret oder Zugriffstoken, Signatur-Secret, API-Version',
'Shp_G_What1' => 'Die Zugangsdaten aus der Shopify-App (Dev Dashboard oder ältere benutzerdefinierte App).',
'Shp_G_Set2' => 'ERP-Lager, Shopify-Standort',
'Shp_G_What2' => 'Welchen Bestand dieser Shop verkauft und wo Bestellungen abgelegt werden.',
'Shp_G_What3' => 'Einzelhandels-, Großhandels- oder Mindestpreis.',
'Shp_G_Set4' => 'Fehlende Produkte / Kunden anlegen',
'Shp_G_What4' => 'Ob ein Abruf ERP-Datensätze anlegen darf, die er nicht zuordnen kann.',
'Shp_G_Set5' => 'Welche Entitäten überhaupt synchronisiert werden',
'Shp_G_What5' => 'Aus bedeutet hier überall aus – manuell, geplant und per Webhook.',
'Shp_G_What6' => 'Der Schalter für den Zeitplaner.',
'Shp_G_What7' => 'Sofortige Bestandsübertragung, ausgelöst durch einen Verkauf oder eine Bestandskorrektur.',
'Shp_G_Set8' => 'Standardintervall und der Plan der Schritte',
'Shp_G_What8' => 'Was von selbst läuft, in welche Richtung und wie oft.',
'Shp_G_Cmd1' => 'Alle Shops: was laufen würde und wann. Ändert nichts.',
'Shp_G_Cmd2' => 'Den gesamten Plan eines Shops jetzt ausführen, unabhängig von der Uhrzeit.',
'Shp_G_Cmd3' => 'Erste Katalogübertragung: nur noch nicht verknüpfte Produkte.',
'Shp_G_Cmd4' => 'Bestellungen ab einem Datum nachträglich importieren.',
'Shp_G_Cmd5' => 'Alles durchgehen und berichten, ohne irgendwo etwas zu schreiben.',
'Shp_Guide_Subtitle' => 'Einen Shop verbinden, was von selbst läuft und wo welche Einstellung zu finden ist',
'Shp_Show_Store_State' => 'Status eines Shops anzeigen',
'Shp_Open_Store' => 'Shop öffnen',
'Shp_No_Shop_Connected_Yet' => 'Es ist noch kein Shop verbunden',
'Shp_Guide_No_Shop_Desc' => 'Alles Folgende gilt trotzdem – verbinden Sie einen Shop unter Shopify → Shops, kehren Sie dann hierher zurück und wählen Sie ihn oben aus, um seinen Status neben jedem Schritt zu sehen.',

