'Agt_Tax_Map_Hint' => 'Nicht aufgeführte Sätze werden als OUT (Outra) gesendet; 0 % ist immer ISE (Isento).',
'Agt_Series' => 'Serien',
'Agt_Series_Hint' => 'Die AGT genehmigt eine Nummernserie pro Dokumenttyp, Jahr und Niederlassung. Ohne aktive Serie für den jeweiligen Typ und das Jahr können keine Rechnungen ausgestellt werden.',
'Agt_Request_Series' => 'Serie bei der AGT anfordern',
'Agt_Add_Series' => 'Bestehende Serie hinzufügen',
'Agt_Contingency' => 'Notfallbetrieb',
'Normal' => 'Normal',
'Agt_Corrects' => 'Korrigiert',
'Agt_Late' => '> 24 h',
'Agt_Check' => 'Prüfen',
'Agt_Correct_Confirm' => 'Für dieses abgelehnte Dokument eine Korrektur mit neuer Nummer ausstellen?',
'Agt_Correct' => 'Korrigieren',
'Agt_Guide_What_Title' => 'Was diese Funktion macht',
'Agt_Guide_What_Body' => 'Jeder abgeschlossene Verkauf wird als elektronische AGT-Rechnung ausgestellt (FR bei Bezahlung bei Erstellung, sonst FT) und jede erhaltene Retoure als Gutschrift (NC). Jedes Dokument erhält die nächste Nummer seiner AGT-Serie, wird mit Ihrem AGT-Schlüssel signiert und an die AGT gesendet, die es wenige Minuten später validiert. Beleg und PDF-Rechnung enthalten die AGT-Nummer, den Sicherheitsauszug und einen QR-Code.',
'Agt_Guide_Steps_Title' => 'Einrichtung',
'Agt_Guide_Step_1' => 'Melden Sie sich im Portal do Contribuinte zur E-Rechnung an (adesão) und laden Sie Ihren privaten AGT-Schlüssel herunter.',
'Agt_Guide_Step_2' => 'Geben Sie auf der Registerkarte „Konfiguration“ Ihre NIF, Niederlassung und den Schlüssel ein, wählen Sie Homologação, speichern Sie und verwenden Sie „Verbindung testen“.',
'Agt_Guide_Step_3' => 'Fordern Sie auf der Registerkarte „Serien“ für das laufende Jahr je eine Serie pro verwendetem Dokumenttyp an (FR, FT, NC).',
'Agt_Guide_Step_4' => 'Ordnen Sie Ihre IVA-Sätze den AGT-Codes zu und legen Sie den Befreiungscode für 0-%-Positionen fest.',
'Agt_Guide_Step_5' => 'Aktivieren Sie das Modul unter Systemeinstellungen > Funktionen, führen Sie einen Testverkauf durch und prüfen Sie auf der Registerkarte „Dokumente“, dass er gültig wird.',
'Agt_Guide_Step_6' => 'Sobald die AGT Sie für den Produktivbetrieb freigibt, wechseln Sie zu Produção und fordern Sie Produktivserien an.',
'Agt_Guide_Note_1' => 'Ein übermittelter Verkauf oder eine übermittelte Retoure kann nicht mehr bearbeitet oder gelöscht werden. Korrigieren Sie ihn mit einer Verkaufsretoure (Gutschrift).',
'Agt_Guide_Note_2' => 'Von der AGT abgelehnte Dokumente werden mit einer neuen Nummer korrigiert, die auf das abgelehnte Dokument verweist; die alte Nummer wird nie wiederverwendet.',
'Agt_Guide_Note_3' => 'Offline-POS-Verkäufe werden bei der Synchronisierung übermittelt. Die AGT sanktioniert Dokumente, die mehr als 24 Stunden zu spät gesendet werden.',
'Agt_Guide_Note_4' => 'Eine Position kann nicht gleichzeitig eine Produktsteuer und die Auftragssteuer tragen; die AGT benötigt einen IVA-Satz pro Position. Der Versand wird als steuerbefreite Position gesendet.',
'Agt_Guide_Note_5' => 'AGT-Summen werden pro Position berechnet und können durch Rundung um einige Cent von der Stocky-Summe abweichen.',
