'Dgi_No_Documents' => 'Noch keine zertifizierten Rechnungen – die Zertifizierung beginnt, sobald die e-MCF-Verbindung aktiv ist.',
'Dgi_Guide_What_Title' => 'Was diese Funktion derzeit macht',
'Dgi_Guide_What_Body' => 'Bei aktiviertem Modul drucken Belege und PDF-Rechnungen die für die facture normalisée vorgeschriebenen Angaben NIF, RCCM und Id. Nat. des Verkäufers. Die vollständige Zertifizierung (DEF-Nummer, Zähler, Authentifizierungscode und QR-Code von der DGI) folgt, sobald die e-MCF-Entwickler-API angebunden ist.',
'Dgi_Guide_Steps_Title' => 'Zugang zum e-MCF erhalten',
'Dgi_Guide_Step_1' => 'Legen Sie mit Ihrer NIF ein Konto auf developper.dgirdc.cd an und beantragen Sie Zugang zur e-MCF-Testumgebung.',
'Dgi_Guide_Step_2' => 'Laden Sie die API-Dokumentation (Routen, DTOs, Steuergruppen) und die Testzugangsdaten herunter.',
