'Simple_List' => 'Einfache Liste',
'Variants_Options_Hint' => 'Definieren Sie Optionen wie Farbe und Größe und erzeugen Sie dann alle Kombinationen. Jede Kombination wird zu einer Variante mit eigenem Code, eigenen Preisen und eigenem Bestand.',
