'Variants_Guide' => 'Anleitung zu Varianten',
'VG_Intro' => 'Ein variables Produkt wird in mehreren Varianten verkauft. Erstellen Sie diese aus Optionen (empfohlen) oder als einfache Namensliste. Jede Variante hat ihren eigenen Code, eigene Preise, ein eigenes Bild und eigenen Bestand.',
'VG_Options_Title' => 'Optionsmodus (Farbe, Größe …)',
'VG_Opt_Step1' => 'Lassen Sie den Schalter in der Kartenkopfzeile auf „Optionen“.',
'VG_Opt_Step2' => 'Geben Sie einen Optionsnamen wie Farbe oder Größe ein oder wählen Sie einen der Vorschläge.',
'VG_Opt_Step3' => 'Geben Sie einen Wert ein (zum Beispiel Rot) und drücken Sie Enter. Wiederholen Sie dies für jeden Wert; auch ein Komma trennt Werte. Klicken Sie auf das x an einem Wert, um ihn zu entfernen.',
'VG_Opt_Step4' => 'Klicken Sie auf „Option hinzufügen“ für eine zweite oder dritte Option (maximal 3 Optionen).',
'VG_Opt_Step5' => 'Klicken Sie auf „Varianten erzeugen“. Pro Kombination wird eine Zeile angelegt und ihr Name automatisch gebildet, zum Beispiel „Rot / S“.',
'VG_Opt_Step6' => 'Geben Sie in jeder Zeile Kosten und Preis ein, oder geben Sie einen Wert unter „Auf alle anwenden“ ein und klicken Sie auf Kosten oder Preis, um ihn in alle Zeilen zu übernehmen.',
'VG_Opt_Step7' => 'Codes werden automatisch erzeugt. Geben Sie einen eigenen ein oder klicken Sie auf das Aktualisieren-Symbol, um einen anderen zu erzeugen.',
'VG_Opt_Step8' => 'Optional: Aktivieren Sie „Farbfelder“ bei einer Option und wählen Sie für jeden Wert eine Farbe; der Shop zeigt sie als farbigen Punkt an.',
'VG_Rows_Title' => 'Variantenzeilen',
'VG_Rows_Text' => 'Jede Zeile hat ein Bild, einen Code, einen Barcode, Kosten, Preis, Großhandelspreis und Mindestverkaufspreis. Beim Anlegen eines Produkts können Sie außerdem für jede Variante den Anfangsbestand pro Lager eingeben. Die Markierung „Unvollständig“ bedeutet, dass in der Zeile ein Wert für eine Option fehlt.',
'VG_List_Title' => 'Modus „Einfache Liste“',
'VG_List_Text' => 'Geben Sie einen Variantennamen ein und drücken Sie Enter (oder klicken Sie auf Hinzufügen), um eine Zeile anzuhängen, und tragen Sie dann Code und Preise ein. Dies ist das klassische Verhalten und bleibt für bestehende Produkte verfügbar.',
'VG_Edit_Title' => 'Spätere Bearbeitung',
'VG_Edit_1' => 'Fügen Sie einen Wert hinzu und klicken Sie auf „Varianten erzeugen“: Es werden nur die fehlenden Kombinationen ergänzt. Bestehende Zeilen behalten ihre Codes, Preise und ihren Verlauf.',
'VG_Edit_2' => 'Wird ein Wert oder eine Option entfernt, werden die Zeilen entfernt, die ihn verwenden. Bereits gespeicherte Zeilen werden nach einer Bestätigung beim Speichern des Produkts gelöscht.',
'VG_Edit_3' => 'Eine Variante mit vorhandenem Bestand kann nicht entfernt werden. Korrigieren oder lagern Sie ihren Bestand zuerst um.',
'VG_Edit_4' => 'Beim Wechsel zu „Einfache Liste“ bleiben die Zeilen und ihre Namen erhalten, die Optionsdefinitionen werden jedoch verworfen.',
'VG_Store_Title' => 'Im Online-Shop',
'VG_Store_Text' => 'Kunden wählen einen Wert pro Option, zum Beispiel erst Farbe, dann Größe. Nicht existierende Kombinationen sind deaktiviert, ausverkaufte sind durchgestrichen. Die gewählte Variante wird in den Warenkorb gelegt.',
