'No_Sales_Agent' => 'Kein Vertriebspartner',
'Pos_Sales_Agent_Hint' => 'Der ausgewählte Vertriebspartner erhält die Provision für diesen Verkauf. Ohne Vertriebspartner geht die Provision an den Vertriebspartner, der mit dem Verkäufer verknüpft ist.',
