'Auto_Sales_Agent' => 'Automatisch',
'Commission_Guide' => 'Provisionsleitfaden',
'Comm_G_Intro_Title' => 'Wie Provisionen funktionieren – in einem Satz',
'Comm_G_Intro' => 'Wenn ein abgeschlossener Verkauf gespeichert wird, erzeugen die Regeln, die zum Vertriebspartner des Verkaufs passen, ausstehende Provisionen. Sie genehmigen diese im Provisionsbericht und zahlen sie mit einem Provisionsbeleg aus. Ändert sich der Verkauf später (Zahlungen, Retouren, Bearbeitungen, Löschung), werden seine Provisionen automatisch neu berechnet.',
'Comm_G_Your_Setup' => 'Ihre Einrichtung',
'Comm_G_Your_Setup_Help' => 'Aktueller Stand dieses Arbeitsbereichs. Jeder Schritt wird grün, sobald er erledigt ist.',
'Comm_G_Optional' => 'Empfohlen',
'Comm_G_Step_Program' => 'Provisionsprogramm erstellen',
'Comm_G_Step_Program_Help' => 'Ein Programm fasst Ihre Regeln zusammen, zum Beispiel „Vertriebsteam 2026“ oder „Sommeraktion“. Es muss aktiv sein, und das heutige Datum muss zwischen „Gültig ab“ und „Gültig bis“ liegen.',
'Comm_G_Step_Program_Warn' => 'Sie haben Programme, aber keines ist heute aktiv. Prüfen Sie das Kontrollkästchen „Aktiv“ und die Daten „Gültig ab“ / „Gültig bis“.',
'Comm_G_Step_Agent' => 'Vertriebspartner hinzufügen',
'Comm_G_Step_Agent_Help' => 'Ein Vertriebspartner ist die Person, die Provision erhält. Das können Mitarbeiter oder externe Personen wie Vermittler oder Wiederverkäufer sein.',
'Comm_G_Step_Link' => 'Vertriebspartner mit Benutzerkonten verknüpfen',
'Comm_G_Step_Link_Help' => 'Wird ein Vertriebspartner mit einem Benutzer verknüpft, werden Verkäufe dieses Benutzers automatisch dem Vertriebspartner gutgeschrieben, ohne dass er bei jedem Verkauf ausgewählt werden muss.',
'Comm_G_Step_Link_Warn' => '{n} aktive(r) Vertriebspartner ist/sind nicht mit einem Benutzer verknüpft. Sie verdienen nur, wenn sie beim Verkauf ausgewählt werden.',
'Comm_G_Step_Rule' => 'Mindestens eine Regel hinzufügen',
'Comm_G_Step_Rule_Help' => 'Eine Regel legt fest, wie viel gezahlt wird, zum Beispiel 5 % der Verkaufssumme. Sie muss aktiv sein und zu einem Programm gehören, das heute aktiv ist.',
'Comm_G_Step_Rule_Warn' => 'Sie haben Regeln, aber keine ist in einem heute aktiven Programm aktiv.',
'Comm_G_Step_Sale' => 'Einen abgeschlossenen Verkauf tätigen',
'Comm_G_Step_Sale_Help' => 'Provisionen entstehen, wenn ein abgeschlossener Verkauf gespeichert wird (Verkauf erstellen, Verkauf bearbeiten oder POS). Verkäufe, die vor Ihren Regeln getätigt wurden, werden nicht berechnet.',
'Comm_G_Step_Sale_Done' => 'Bisher {n} Provision(en) berechnet.',
'Comm_G_Step_Approve' => 'Provisionen genehmigen',
'Comm_G_Step_Approve_Help' => 'Markieren Sie im Provisionsbericht die ausstehenden Zeilen, mit denen Sie einverstanden sind, und klicken Sie auf „Genehmigt“. Derzeit wartet nichts.',
