'Comm_G_Step_Pay' => 'Vertriebspartner auszahlen',
'Comm_G_Step_Pay_Help' => 'Wählen Sie unter „Provisionsbelege“ einen Vertriebspartner aus, markieren Sie seine genehmigten Provisionen und speichern Sie den Beleg. Sie werden damit als bezahlt markiert. Derzeit wartet nichts auf Auszahlung.',
'Comm_G_Step_Pay_Warn' => '{n} genehmigte Provision(en) warten auf Auszahlung.',
