'Comm_G_Calc_Base' => 'Basisbetrag ({source}): {base}',
'Comm_G_Calc_Zero_Base' => 'Der Basisbetrag ist 0, daher erzeugt diese Regel nichts. Mit „Bezahlter Betrag“ als Quelle bringt ein unbezahlter Verkauf nichts ein, bis eine Zahlung erfasst wird.',
'Comm_G_Calc_Below_Min' => 'Die Basis liegt unter der Mindestschwelle von {min}, daher erzeugt diese Regel für diesen Verkauf nichts.',
'Comm_G_Calc_Pct' => '{value} % von {base} = {amount}',
'Comm_G_Calc_Fixed' => 'Festbetrag: {amount} pro Verkauf, unabhängig von der Verkaufshöhe',
'Comm_G_Calc_Capped' => 'Höher als die Obergrenze, daher auf {cap} reduziert',
'Comm_G_Calc_Zero' => 'Das Ergebnis ist 0, daher wird keine Provision erzeugt.',
'Comm_G_The_Flow' => 'Der Ablauf, Schritt für Schritt',
'Comm_G_Flow_Program' => 'Programm',
'Comm_G_Flow_Program_Help' => 'Erstellen Sie ein Programm und legen Sie seinen Gültigkeitszeitraum fest.',
'Comm_G_Flow_Agent' => 'Vertriebspartner',
'Comm_G_Flow_Agent_Help' => 'Fügen Sie die Personen hinzu, die Provision erhalten, und verknüpfen Sie Mitarbeiter mit ihren Benutzerkonten.',
'Comm_G_Flow_Rule' => 'Regeln',
'Comm_G_Flow_Rule_Help' => 'Fügen Sie im Programm Regeln hinzu: prozentual oder fest, für alle Vertriebspartner oder einen bestimmten.',
'Comm_G_Flow_Sale' => 'Verkauf',
'Comm_G_Flow_Sale_Help' => 'Ein abgeschlossener Verkauf wird gespeichert. Jede passende Regel erzeugt eine ausstehende Provision.',
'Comm_G_Flow_Approve' => 'Genehmigen',
'Comm_G_Flow_Approve_Help' => 'Prüfen Sie die ausstehenden Provisionen im Provisionsbericht und genehmigen oder stornieren Sie sie.',
'Comm_G_Flow_Pay' => 'Auszahlen',
'Comm_G_Flow_Pay_Help' => 'Erfassen Sie einen Provisionsbeleg für den Vertriebspartner. Die enthaltenen Provisionen werden als bezahlt markiert.',
'Comm_G_How_It_Works' => 'So funktioniert es',
'Comm_G_T_Credit' => 'Welcher Vertriebspartner erhält die Provision?',
'Comm_G_Credit_Intro' => 'Jeder Verkauf wird höchstens einem Vertriebspartner gutgeschrieben. Das System prüft in dieser Reihenfolge:',
'Comm_G_Credit_Picked' => 'Der beim Verkauf gewählte Vertriebspartner: das Feld „Vertriebspartner“ unter „Verkauf erstellen“ und „Verkauf bearbeiten“ oder die Schaltfläche „Verkauft von“ im POS. Wurde dieser Vertriebspartner inzwischen deaktiviert, bringt der Verkauf nichts ein; es wird nicht auf die nächsten Optionen ausgewichen.',
'Comm_G_Credit_Seller' => 'Andernfalls der Vertriebspartner, der mit dem im POS gewählten Verkäufer verknüpft ist (wenn der POS-Schalter für Verkäufer aktiviert ist).',
'Comm_G_Credit_Cashier' => 'Andernfalls der Vertriebspartner, der mit dem Benutzer verknüpft ist, der den Verkauf gespeichert hat.',
'Comm_G_Credit_Nobody' => 'Findet keine dieser Optionen einen aktiven Vertriebspartner, bringt der Verkauf keine Provision ein.',
'Comm_G_Credit_Note' => 'Bleibt der Vertriebspartner im POS auf „Automatisch“, werden die Optionen 2 und 3 verwendet. Der neben „Automatisch“ angezeigte Name ist der Vertriebspartner, dem der Verkauf gutgeschrieben wird.',
'Comm_G_T_When' => 'Wann werden Provisionen berechnet und aktualisiert?',
'Comm_G_When_Intro' => 'Provisionen werden erstmals erzeugt, wenn ein Verkauf mit dem Status „Abgeschlossen“ an einer dieser Stellen gespeichert wird:',
'Comm_G_When_Create' => 'Verkauf erstellen: wenn der Verkauf als „Abgeschlossen“ gespeichert wird.',
'Comm_G_When_Edit' => 'Verkauf bearbeiten: Das Speichern eines abgeschlossenen Verkaufs berechnet ihn vollständig neu mit aktueller Summe, aktuellen Zahlungen und aktuellem Vertriebspartner, einschließlich zuvor stornierter Provisionen.',
'Comm_G_When_Pos' => 'POS: wenn ein Verkauf abgeschlossen wird, auch ein Entwurf, der später abgeschlossen wird.',
'Comm_G_When_Payment' => 'Hinzufügen einer Zahlung zu einem abgeschlossenen Verkauf – so erfassen Regeln mit „Bezahlter Betrag“ auch Zahlungen nach dem Verkauf.',
'Comm_G_When_Cod' => 'Kurier-Nachnahme: wenn das vom Kurier kassierte Bargeld als Zahlung auf den Verkauf erfasst wird.',
'Comm_G_When_Not_Intro' => 'Folgendes erzeugt KEINE Provisionen:',
'Comm_G_When_Not_Status' => 'Als „Ausstehend“ oder „Bestellt“ gespeicherte Verkäufe. Sie bringen erst etwas ein, wenn sie bearbeitet und als „Abgeschlossen“ gespeichert werden.',
'Comm_G_When_Not_Before' => 'Verkäufe, die vor dem Programm oder der Regel gespeichert wurden. Sie werden nicht im Hintergrund berechnet. Wird ein solcher Verkauf unter „Verkauf bearbeiten“ geöffnet und gespeichert, wird er mit den am Verkaufsdatum aktiven Regeln berechnet.',
'Comm_G_When_Not_Import' => 'Aus einer Datei importierte Verkäufe.',
'Comm_G_When_Not_Online' => 'Im Online-Shop aufgegebene Bestellungen.',
'Comm_G_T_Statuses' => 'Provisionsstatus',
'Comm_G_Meaning' => 'Bedeutung',
'Comm_G_S_Pending' => 'Gerade aus einem Verkauf berechnet. Noch von niemandem geprüft. Genehmigen oder stornieren Sie sie im Provisionsbericht.',
'Comm_G_S_Approved' => 'Geprüft und genehmigt. Sie steht dem Vertriebspartner zu und kann in einen Provisionsbeleg aufgenommen werden. Ändern sich Verkauf und Betrag, wird sie zur erneuten Prüfung wieder auf „Ausstehend“ gesetzt.',
'Comm_G_S_Paid' => 'In einem Provisionsbeleg enthalten. Endgültig: Bezahlte Provisionen werden nie geändert. Ändert sich der Verkauf danach, wird die Differenz als separate Korrektur hinzugefügt.',
'Comm_G_S_Cancelled' => 'Wird nicht ausgezahlt. Sie bleibt storniert, auch wenn später Zahlungen oder Retouren eingehen. Durch Speichern des Verkaufs unter „Verkauf bearbeiten“ oder durch Markieren im Bericht und Klicken auf „Neu berechnen“ wird sie erneut berechnet.',
'Comm_G_Field' => 'Feld',
'Comm_G_T_Programs' => 'Provisionsprogramme',
'Comm_G_Programs_Body' => 'Ein Programm ist ein Container für Regeln, meist eines pro Zeitraum oder Kampagne. Eine Regel wirkt nur, solange ihr Programm aktiv ist und das Verkaufsdatum innerhalb des Programmzeitraums liegt. Mehrere Programme können gleichzeitig aktiv sein, und alle werden angewendet.',
'Comm_G_F_Program_Name' => 'Ein beliebiger Name, an dem Sie das Programm erkennen, zum Beispiel „Q4 2026“ oder „Black Friday“.',
'Comm_G_F_Program_Active' => 'Deaktivieren Sie das Kontrollkästchen, um alle Regeln des Programms auf einmal zu pausieren. Bereits erzeugte Provisionen sind nicht betroffen.',
'Comm_G_F_Program_From' => 'Verkäufe mit einem Datum vor diesem Tag werden vom Programm ignoriert. Leer lassen für kein Startdatum.',
'Comm_G_F_Program_To' => 'Verkäufe mit einem Datum nach diesem Tag werden vom Programm ignoriert. Leer lassen für ein unbefristetes Programm.',
'Comm_G_T_Agents' => 'Vertriebspartner',
'Comm_G_Agents_Body' => 'Ein Vertriebspartner ist die Person, die Provision erhält. Ein Vertriebspartner muss kein Benutzer des Systems sein: Auch externe Vermittler oder Wiederverkäufer können Vertriebspartner sein und verdienen immer dann, wenn sie bei einem Verkauf ausgewählt werden.',
'Comm_G_F_Agent_Name' => 'Der Name, der bei Verkäufen, im Bericht und auf Belegen angezeigt wird.',
'Comm_G_F_Agent_Code' => 'Optionale Referenz wie eine Personalnummer. In der Liste der Vertriebspartner durchsuchbar.',
'Comm_G_F_Agent_User' => 'Verknüpft den Vertriebspartner mit einem Mitarbeiter-Benutzer. Verkäufe dieses Benutzers (oder Verkäufe, bei denen er im POS als Verkäufer gewählt wird) werden dann automatisch diesem Vertriebspartner gutgeschrieben.',
'Comm_G_F_Agent_Active' => 'Inaktive Vertriebspartner verdienen bei neuen Verkäufen nichts und verschwinden aus den Auswahllisten. Ihre bisherigen Provisionen bleiben erhalten.',
'Comm_G_T_Rules' => 'Provisionsregeln: alle Felder erklärt',
'Comm_G_Rules_Body' => 'Eine Regel bestimmt, wie viel für einen Verkauf gezahlt wird. Verwenden Sie das Feld „Regel testen“ oben, um eine Regel vor dem Speichern zu prüfen.',
'Comm_G_F_Rule_Program' => 'Das Programm, zu dem die Regel gehört. Die Regel wirkt nur, solange dieses Programm aktiv ist und im Gültigkeitszeitraum liegt.',
'Comm_G_F_Rule_Type' => '„Prozentsatz“ zahlt einen Anteil des Basisbetrags. „Fest“ zahlt bei jedem qualifizierenden Verkauf denselben Betrag, unabhängig von dessen Höhe.',
'Comm_G_F_Rule_Source' => 'Wovon der Prozentsatz berechnet wird. „Verkaufssumme“ ist der Gesamtbetrag des Verkaufs. „Bezahlter Betrag“ ist das, was der Kunde zum Zeitpunkt der Provisionsberechnung bezahlt hatte.',
'Comm_G_F_Rule_Value' => 'Der Prozentsatz (5 bedeutet 5 %) oder der Festbetrag, je nach Typ.',
'Comm_G_F_Rule_Min' => 'Optional. Verkäufe, deren Basisbetrag darunter liegt, bringen mit dieser Regel nichts ein. Ein Verkauf, der genau der Schwelle entspricht, bringt etwas ein.',
'Comm_G_F_Rule_Cap' => 'Optional. Der Höchstbetrag, den diese Regel für einen Verkauf zahlen kann. Gilt für prozentuale und feste Regeln.',
'Comm_G_F_Rule_Applies' => 'Alle Vertriebspartner: Jeder Vertriebspartner verdient mit dieser Regel. Bestimmter Vertriebspartner: nur der ausgewählte. Eine Regel „Bestimmter Vertriebspartner“ ohne ausgewählten Vertriebspartner zahlt nie an jemanden.',
'Comm_G_F_Rule_Priority' => 'In einem Programm mit der Einstellung „Nur die Regel mit der höchsten Priorität zahlt“ gewinnt die qualifizierende Regel mit der höchsten Zahl, die anderen werden übersprungen. Bei Gleichstand schlägt eine Regel „Bestimmter Vertriebspartner“ eine Regel „Alle Vertriebspartner“. In einem Programm mit der Einstellung „Jede passende Regel zahlt“ legt die Priorität nur die Reihenfolge fest.',
'Comm_G_F_Rule_Active' => 'Deaktivieren Sie das Kontrollkästchen, um nur diese eine Regel zu pausieren. Bereits von ihr erzeugte Provisionen sind nicht betroffen.',
'Comm_G_T_Stacking' => 'Mehrere Regeln für einen Verkauf',
'Comm_G_Stacking_Body' => 'Jedes Programm legt fest, wie seine Regeln kombiniert werden (die Einstellung „Wenn mehrere Regeln passen“ im Programm).

Nur die Regel mit der höchsten Priorität zahlt (Standard für neue Programme): Die Regeln werden von der höchsten Priorität abwärts geprüft, und die erste, die sich für den Verkauf qualifiziert, zahlt. Eine Regel qualifiziert sich, wenn der Verkauf ihre Mindestschwelle erreicht und das Ergebnis über 0 liegt. So lassen sich Staffeln leicht abbilden: „7 % bei Verkäufen ab 10,000“ mit Priorität 10 und „5 %“ mit Priorität 0. Um Sara einen Sondersatz zu geben, fügen Sie für sie eine Regel „Bestimmter Vertriebspartner“ mit einer höheren Priorität als die Regel „Alle Vertriebspartner“ hinzu.

Jede passende Regel zahlt: Alle passenden Regeln zahlen und die Beträge werden addiert. Eine Regel „Alle Vertriebspartner“ mit 3 % plus eine Regel „Bestimmter Vertriebspartner“ mit 2 % für Sara ergibt für Sara 5 %.

Programme sind voneinander unabhängig: Jedes aktive Programm zahlt für sich, sodass ein Verkauf gleichzeitig aus einem Basisprogramm und einem Kampagnenprogramm Provision einbringen kann.',
'Comm_G_T_Paying' => 'Vertriebspartner mit Provisionsbelegen auszahlen',
'Comm_G_Paying_Body' => 'Öffnen Sie „Provisionsbelege“ und klicken Sie auf „Hinzufügen“. Wählen Sie den Vertriebspartner: Seine genehmigten Provisionen werden aufgelistet. Markieren Sie diejenigen, die Sie auszahlen; der Betrag wird mit ihrer Summe ausgefüllt und kann angepasst werden. Die Referenz wird automatisch vergeben (CR-000001, CR-000002...), und Sie können Zahlungsmethode, Datum und eine Notiz hinzufügen.

Das Speichern des Belegs markiert die ausgewählten Provisionen als bezahlt und verknüpft sie mit dem Beleg. Nur genehmigte Provisionen können ausgezahlt werden; genehmigen Sie sie daher zuerst im Provisionsbericht.

Negative Korrekturen (zu viel an den Vertriebspartner gezahltes Geld) werden ebenfalls aufgelistet. Markieren Sie sie zusammen mit den nächsten Provisionen des Vertriebspartners, damit sie von dieser Zahlung abgezogen werden.

Ein Beleg dokumentiert nur die Auszahlung: Er erzeugt keine Ausgabe und bewegt kein Geld auf Ihren Konten. Wenn Sie Auszahlungen unter Ausgaben oder in der Buchhaltung erfassen, buchen Sie sie dort zusätzlich.',
'Comm_G_T_Snapshot' => 'Wenn sich ein Verkauf ändert',
'Comm_G_Snapshot_Body' => 'Provisionen folgen dem Verkauf. Sobald sich ein Verkauf mit Provisionen ändert, werden diese aus seinen aktuellen Werten neu berechnet: Verkaufssumme abzüglich erhaltener Retouren und bezahlter Betrag abzüglich Erstattungen.

Unbezahlte Provisionen (ausstehend oder genehmigt) werden einfach aktualisiert. Eine genehmigte Provision, deren Betrag sich ändert, wird wieder auf „Ausstehend“ gesetzt, damit sie erneut geprüft wird. Eine nicht mehr geschuldete Provision (Verkauf gelöscht, vollständig retourniert, Vertriebspartner geändert) wird entfernt.

Bezahlte Provisionen werden nie geändert. Die Differenz wird zu einer neuen ausstehenden Zeile mit der Kennzeichnung „Korrektur“: positiv, wenn mehr geschuldet wird (zum Beispiel wurde der Rest eines Verkaufs mit „Bezahlter Betrag“ bezahlt), negativ, wenn der Vertriebspartner zu viel erhalten hat (zum Beispiel nach einer Retoure). Genehmigen Sie sie und nehmen Sie sie in den nächsten Beleg des Vertriebspartners auf.

Jede Provision behält die Bedingungen der Regel (Typ, Satz, Schwelle, Obergrenze) zum Zeitpunkt ihrer ersten Entstehung. Wird eine Regel später geändert oder deaktiviert, werden ältere Verkäufe bei einer Neuberechnung nicht neu bepreist.',
'Comm_G_T_Permissions' => 'Wer was tun darf',
'Comm_G_Permission' => 'Berechtigung',
'Comm_G_Lets_You' => 'Was sie erlaubt',
'Comm_G_P_View' => 'Alle Provisionsseiten ansehen: Programme, Vertriebspartner, Regeln, Belege, den Bericht und diesen Leitfaden.',
'Comm_G_P_Add' => 'Programme, Vertriebspartner und Regeln anlegen und Provisionsbelege erfassen (Vertriebspartner auszahlen).',
'Comm_G_P_Edit' => 'Programme, Vertriebspartner und Regeln bearbeiten sowie Provisionen im Provisionsbericht genehmigen oder stornieren.',
'Comm_G_P_Delete' => 'Programme, Vertriebspartner und Regeln löschen.',
'Comm_G_T_Faq' => 'Fragen und Antworten',
'Comm_G_Q_Empty' => 'Ich habe alles eingerichtet, aber der Provisionsbericht ist leer.',
'Comm_G_A_Empty' => 'Prüfen Sie Folgendes: Der Verkauf wurde nach dem Anlegen der Regel gespeichert; der Verkauf ist abgeschlossen; der Verkauf hat einen Vertriebspartner (beim Verkauf ausgewählt oder der Benutzer, der ihn getätigt hat, ist mit einem Vertriebspartner verknüpft); das Programm ist aktiv und das Verkaufsdatum liegt in seinem Zeitraum; die Regel ist aktiv und gilt für diesen Vertriebspartner; und der Verkauf erreicht mindestens die Mindestschwelle der Regel. Prüfen Sie auch den Datumsfilter des Berichts: Er filtert nach dem Datum, an dem die Provision berechnet wurde.',
'Comm_G_Q_Twice' => 'Ein Vertriebspartner hat für einen Verkauf zwei Provisionen erhalten.',
'Comm_G_A_Twice' => 'Zwei Regeln haben gezahlt: Entweder ist das Programm auf „Jede passende Regel zahlt“ eingestellt, oder die Regeln liegen in zwei verschiedenen aktiven Programmen (jedes Programm zahlt für sich). Stellen Sie das Programm auf „Nur die Regel mit der höchsten Priorität zahlt“, wenn nur eine zahlen soll. Erneutes Speichern eines Verkaufs dupliziert nie eine Provision.',
'Comm_G_Q_Rate' => 'Ändern sich alte Provisionen, wenn ich den Satz einer Regel ändere?',
'Comm_G_A_Rate' => 'Nein. Jede Provision behält die Bedingungen der Regel, unter der sie entstanden ist, auch wenn ihr Verkauf später neu berechnet wird. Der neue Satz gilt für Provisionen, die ab jetzt entstehen.',
'Comm_G_Q_Return' => 'Der Kunde hat die Ware zurückgegeben. Was passiert mit der Provision?',
'Comm_G_A_Return' => 'Sie wird automatisch reduziert. Eine erhaltene Retoure senkt die Verkaufssumme und eine Erstattung senkt den bezahlten Betrag. Wurde die Provision noch nicht ausgezahlt, wird sie aktualisiert (oder bei einer vollständigen Retoure entfernt). Wurde sie bereits ausgezahlt, wird eine negative Korrektur hinzugefügt und vom nächsten Beleg des Vertriebspartners abgezogen.',
'Comm_G_Q_Wrong_Agent' => 'Ich habe den falschen Vertriebspartner gutgeschrieben. Wie korrigiere ich das?',
'Comm_G_A_Wrong_Agent' => 'Bearbeiten Sie den Verkauf, wählen Sie den richtigen Vertriebspartner und speichern Sie. Die Provisionen gehen auf den richtigen Vertriebspartner über. Wurde der erste Vertriebspartner bereits ausgezahlt, wird für ihn eine negative Korrektur hinzugefügt.',
'Comm_G_Q_Inactive' => 'Was passiert, wenn ich einen Vertriebspartner deaktiviere?',
'Comm_G_A_Inactive' => 'Er verdient bei neuen Verkäufen nichts mehr und wird in den Auswahllisten ausgeblendet. Seine bestehenden Provisionen bleiben erhalten, können weiterhin genehmigt und ausgezahlt werden und folgen weiterhin Änderungen an seinen Verkäufen. Ein Verkauf, der mit diesem Vertriebspartner gespeichert wurde, weicht nicht auf einen anderen Vertriebspartner aus.',
'Comm_G_Q_Partial' => 'Wie gehen Regeln mit „Bezahlter Betrag“ mit Teilzahlungen um?',
'Comm_G_A_Partial' => 'Ein unbezahlter Verkauf bringt nichts ein. Die Provision entsteht, sobald erstmals Geld eingeht (an der Kasse oder beim Hinzufügen einer Zahlung), und wächst mit weiteren Zahlungen. Wurde ein Teil bereits ausgezahlt, kommt der Rest als positive Korrektur.',
'Comm_G_Q_Undo' => 'Kann ich eine Auszahlung oder eine Stornierung rückgängig machen?',
'Comm_G_A_Undo' => 'Eine Auszahlung nicht: „Bezahlt“ ist endgültig, und Belege können weder bearbeitet noch gelöscht werden. Prüfen Sie daher die markierten Provisionen und den Betrag vor dem Speichern. Eine Stornierung schon: Markieren Sie die Zeile im Provisionsbericht und klicken Sie auf „Neu berechnen“, oder speichern Sie den Verkauf erneut unter „Verkauf bearbeiten“.',
'Comm_G_Q_Dates' => 'Welches Datum verwenden die Programmzeiträume?',
'Comm_G_A_Dates' => 'Das Datum des Verkaufs selbst, nicht den Tag, an dem er gespeichert wurde. Ein Verkauf mit Datum im letzten Monat verwendet nur Programme, die im letzten Monat gültig waren.',
'Comm_G_When_Changes' => 'Danach aktualisiert jede Änderung an einem Verkauf mit Provisionen diese automatisch: bearbeitete oder gelöschte Zahlungen, Retouren und Erstattungen, ein Status, der nicht mehr „Abgeschlossen“ ist, oder die Löschung des Verkaufs.',
'Comm_G_F_Program_Mode' => 'Was passiert, wenn mehrere Regeln dieses Programms auf denselben Verkauf passen. „Nur die Regel mit der höchsten Priorität zahlt“: Die Regeln werden von der höchsten Priorität abwärts geprüft, und die erste qualifizierende zahlt. „Jede passende Regel zahlt“: Alle zahlen und die Beträge werden addiert.',
'Comm_G_Q_Mode_Old' => 'Ich habe Prioritäten festgelegt, aber die Regeln werden trotzdem addiert.',
'Comm_G_A_Mode_Old' => 'Dieses Programm ist auf „Jede passende Regel zahlt“ eingestellt. Programme, die vor Einführung dieser Einstellung erstellt wurden, behalten dieses Verhalten, damit sich ihre Auszahlungen nicht ändern. Bearbeiten Sie das Programm und wählen Sie „Nur die Regel mit der höchsten Priorität zahlt“.',
'Comm_G_Q_Negative' => 'Warum gibt es eine negative Provision?',
'Comm_G_A_Negative' => 'Es handelt sich um eine Korrektur: Der Vertriebspartner hat mehr erhalten, als der Verkauf jetzt einbringt – wegen einer Retoure, einer Erstattung, einer niedrigeren Summe, eines geänderten Vertriebspartners oder eines gelöschten Verkaufs. Genehmigen Sie sie und markieren Sie sie im nächsten Beleg des Vertriebspartners, damit sie abgezogen wird.',
'Comm_Rule_Mode' => 'Wenn mehrere Regeln passen',
'Comm_Mode_Highest' => 'Nur die Regel mit der höchsten Priorität zahlt',
'Comm_Mode_All' => 'Jede passende Regel zahlt (Beträge werden addiert)',
'Comm_Mode_Highest_Short' => 'Höchste Priorität gewinnt',
'Comm_Mode_All_Short' => 'Regeln werden addiert',
'Comm_Mode_Highest_Help' => 'Die Regeln werden von der höchsten Priorität abwärts geprüft; die erste, die sich für den Verkauf qualifiziert, zahlt, die anderen werden übersprungen. Gut für Staffeln, zum Beispiel 7 % über 10,000 mit Priorität 10 und 5 % für alles andere mit Priorität 0.',
'Comm_Mode_All_Help' => 'Jede Regel, die auf den Vertriebspartner passt, zahlt für den Verkauf, sodass sich die Beträge addieren. Die Priorität legt nur die Reihenfolge fest.',
'Comm_Priority_Help_Highest' => 'Dieses Programm zahlt nur die qualifizierende Regel mit der höchsten Priorität. Geben Sie dieser Regel eine höhere Priorität als den Regeln, gegen die sie gewinnen soll. Bei Gleichstand schlägt eine Regel „Bestimmter Vertriebspartner“ eine Regel „Alle Vertriebspartner“.',
'Comm_Priority_Help_All' => 'Dieses Programm zahlt jede passende Regel, daher kommt diese Regel zu den anderen hinzu. Die Priorität legt nur die Reihenfolge fest.',
'Comm_Recalculate' => 'Neu berechnen',
'Comm_Recalculate_Help' => 'Berechnet die Verkäufe der markierten Zeilen anhand ihrer aktuellen Werte neu, einschließlich stornierter Provisionen.',
'Comm_Adjustment' => 'Korrektur',
'Comm_Adjustment_Help' => 'Eine Korrektur an einer bereits ausgezahlten Provision, weil sich der Verkauf danach geändert hat. Ein negativer Betrag wird vom nächsten Beleg des Vertriebspartners abgezogen.',
'Comm_Cancel_Confirm' => 'Ausgewählte Provisionen stornieren?',
'Comm_Cancel_Confirm_Help' => 'Sie werden nicht ausgezahlt und bleiben storniert, auch wenn später Zahlungen oder Retouren eingehen. Durch Speichern des Verkaufs unter „Verkauf bearbeiten“ oder Klicken auf „Neu berechnen“ werden sie erneut berechnet.',
'Fashion_Tiles_Hint' => 'Fügen Sie eigene Kacheln (Bild, Titel und Link) hinzu, um die automatischen Kategorie-Kacheln zu ersetzen.',

// Online Store: Car Dealership theme
'Car_Dealership_Theme' => 'Autohaus-Design',
'Cars_Theme_Hint' => 'Fahrzeuge sind normale Produkte: Fügen Sie wie gewohnt Preis, Fotos und Beschreibung hinzu und füllen Sie dann im Produktformular die Karte „Fahrzeugdetails“ aus (Marke, Modell, Baujahr, Kilometerstand …). Kunden senden Anfragen, Probefahrtwünsche und Inzahlungnahme-Bewertungen, die unter Shop › Fahrzeuganfragen eingehen.',
'CdSection_search' => 'Suchbereich',
'CdSection_body_types' => 'Nach Karosserieform stöbern',
'CdSection_featured' => 'Empfohlene Fahrzeuge',
'CdSection_latest' => 'Neu eingetroffen',
'CdSection_makes' => 'Nach Marke einkaufen',
'CdSection_finance' => 'Finanzierungsrechner',
'CdSection_trade_in' => 'Formular zur Inzahlungnahme-Bewertung',
'CdSection_trust' => 'Vertrauensleiste',
'CdSection_visit' => 'Besuchen Sie unseren Showroom',
'Cars_Featured_Count' => 'Empfohlene Fahrzeuge',
'Cars_Latest_Count' => 'Neueste Fahrzeuge',
'Cars_Makes_Count' => 'Angezeigte Marken',
'Cars_Texts' => 'Startseitentexte',
'Cars_Hero_Title' => 'Hero-Titel',
