'Rst_Guide_Step_Db_Help' => 'Einige Restaurant-Tabellen fehlen. Führen Sie das neueste Datenbank-Update (Mandanten-Migrationen) aus und laden Sie diese Seite neu.',
'Rst_Guide_Step_Settings' => 'Restaurant-Einstellungen',
'Rst_Guide_Step_Settings_Ok' => 'Bestellarten: {types}. Eine Standardfiliale ist festgelegt.',
'Rst_Guide_Step_Settings_Help' => 'Wählen Sie, welche Bestellarten Sie annehmen, die Filiale, deren Bestand für Restaurantverkäufe verwendet wird, sowie Servicegebühr, Trinkgeld und Rundung.',
'Rst_Guide_Step_Floor' => 'Gastbereiche und Tische',
'Rst_Guide_Step_Floor_Ok' => '{areas} Bereiche, {tables} Tische.',
'Rst_Guide_Step_Floor_Help' => 'Fügen Sie Ihre Bereiche (Innenraum, Terrasse …) und deren Tische mit der Anzahl der Plätze hinzu. „Mehrere hinzufügen“ erstellt T1–T20 in einem Schritt.',
'Rst_Guide_Step_Stations' => 'Küchenstationen',
'Rst_Guide_Step_Stations_Ok' => '{n} Stationen.',
'Rst_Guide_Step_Stations_Help' => 'Stationen (Grill, Fritteuse, Kalte Küche, Desserts, Getränke …) teilen das Küchendisplay auf, sodass jeder Koch nur seine Gerichte sieht.',
'Rst_Guide_Step_Dishes' => 'Gerichte und Zusätze',
'Rst_Guide_Step_Dishes_Ok' => '{n} Gerichte eingerichtet, {groups} Zusatzgruppen.',
'Rst_Guide_Step_Dishes_Help' => 'Gerichte sind Ihre normalen Produkte. Geben Sie ihnen unter Restaurant › Speisekarte eine Station, Zubereitungszeit, Ernährungshinweise und Zusatzgruppen (Größen, Extras).',
'Rst_Guide_Step_Payments' => 'Zahlungen',
'Rst_Guide_Step_Payments_Ok' => '{n} Zahlungsmethoden bereit, inklusive Bargeld, und ein Standardkunde für Laufkundschaft.',
'Rst_Guide_Step_Payments_Help' => 'Rechnungen benötigen mindestens eine aktive Zahlungsmethode, eine Barzahlungsmethode (Rückgeld wird bar gegeben) und einen Standardkunden in den Systemeinstellungen.',
'Rst_Guide_Step_Staff' => 'Mitarbeiterberechtigungen',
'Rst_Guide_Step_Staff_Help' => 'Rollen, die Bestellungen aufnehmen können: {waiters}, das Küchendisplay nutzen: {kitchen}, Zahlungen annehmen: {cashiers}. Geben Sie jeder Rolle nur, was diese Tätigkeit erfordert (siehe „Wer macht was“).',
'Rst_Guide_Step_First' => 'Ihre erste Rechnung',
'Rst_Guide_Step_First_Ok' => 'Bisher {n} Rechnungen abgerechnet.',
'Rst_Guide_Step_First_Help' => 'Platzieren Sie Gäste an einem Testtisch im Tischplan, fügen Sie ein Gericht hinzu, senden Sie es, markieren Sie es auf dem Küchendisplay als fertig und nehmen Sie die Zahlung an.',
'Rst_Guide_Step_Qr' => 'QR-Tischbestellung',
'Rst_Guide_Step_Qr_On' => 'Aktiv. {n} Tische haben einen QR-Code.',
'Rst_Guide_Step_Qr_Help' => 'Gäste scannen einen Code am Tisch, wählen Gerichte auf ihrem Smartphone und senden sie an die Bestellung des Tisches. Aktivieren Sie die Funktion in den Restaurant-Einstellungen und drucken Sie dann die Codes.',
'Rst_Guide_Step_Booking' => 'Online-Tischbuchung',
'Rst_Guide_Step_Booking_On' => 'Aktiv. Buchungen aus dem Online-Shop erscheinen zur Bestätigung unter Reservierungen.',
'Rst_Guide_Step_Booking_Help' => 'Lassen Sie Gäste einen Tisch über den Online-Shop buchen. Legen Sie Buchungszeiten, Intervall und größte Gruppe in den Restaurant-Einstellungen fest.',
'Rst_Guide_Step_Store' => 'Online-Shop und das Design „Restaurant“',
'Rst_Guide_Step_Store_On' => 'Das Design „Restaurant“ ist aktiv. Online-Bestellungen erreichen die Küche: {mode}.',
'Rst_Guide_Step_Store_Help' => 'Wählen Sie unter Online-Shop › Einstellungen das Design „Restaurant“: Die Startseite wird zu Ihrer Speisekarte, mit Zusätzen, Abholung / Lieferung und Tischbuchung.',
'Rst_Guide_How' => 'So funktioniert es',
'Rst_Guide_Service' => 'Ein Service, Schritt für Schritt',
'Rst_Guide_Service_1_T' => 'Platzieren',
'Rst_Guide_Service_1' => 'Wählen Sie im Tischplan einen freien Tisch, geben Sie die Anzahl der Gäste und die Servicekraft ein und klicken Sie dann auf „Gäste platzieren und Bestellung aufnehmen“. Eine Gruppe mit Buchung wird über ihre Buchung platziert.',
'Rst_Guide_Service_2_T' => 'Bestellen',
'Rst_Guide_Service_2' => 'Tippen Sie auf dem Bestellbildschirm auf Gerichte. Wählen Sie Zusätze, Platz und Gang; fügen Sie eine Notiz für die Küche hinzu. Halten Sie einen Gang zurück, um ihn später abzurufen.',
'Rst_Guide_Service_3_T' => 'Senden',
'Rst_Guide_Service_3' => '„Senden“ setzt die neuen Gerichte auf einen Küchenbon. Noch nicht gesendete Gerichte können weiterhin geändert oder entfernt werden; danach können sie nur noch mit Angabe eines Grundes storniert werden.',
'Rst_Guide_Service_4_T' => 'Kochen',
'Rst_Guide_Service_4' => 'Das Küchendisplay zeigt den Bon an jeder Station. Köche starten ihn, haken Gerichte ab, sobald sie fertig sind, und schließen ihn ab, wenn alles bereit ist.',
'Rst_Guide_Service_5_T' => 'Servieren',
'Rst_Guide_Service_5' => 'Fertige Gerichte erscheinen im Tischplan und auf dem Bestellbildschirm. Die Servicekraft bringt sie an den Tisch und tippt auf „Als serviert markieren“.',
'Rst_Guide_Service_6_T' => 'Abrechnen',
'Rst_Guide_Service_6' => '„Abrechnen“ druckt die Rechnung und nimmt die Zahlung an: gesamte Rechnung, gleichmäßig aufgeteilt oder nach Positionen. Jede Zahlung ist ein normaler POS-Verkauf.',
'Rst_Guide_Service_7_T' => 'Abräumen',
'Rst_Guide_Service_7' => 'Wenn alles bezahlt ist, wird die Bestellung geschlossen und der Tisch wechselt auf „Reinigung nötig“ (oder direkt auf „Frei“, je nach Restaurant-Einstellungen).',
'Rst_Guide_Roles' => 'Wer macht was',
'Rst_Guide_Roles_Help' => 'Restaurant-Berechtigungen werden pro Rolle unter Gruppenberechtigungen vergeben. Ein Benutzer kann die Berechtigungen mehrerer Rollen haben.',
'Rst_Guide_Job' => 'Tätigkeit',
'Rst_Guide_Give' => 'Diese Berechtigungen vergeben',
'Rst_Guide_Job_Waiter' => 'Servicekraft',
'Rst_Guide_Job_Cook' => 'Koch',
'Rst_Guide_Job_Cashier' => 'Kassierer',
'Rst_Guide_Job_Host' => 'Gastgeber / Empfang',
'Rst_Guide_Job_Supervisor' => 'Schichtleitung',
'Rst_Guide_Job_Manager' => 'Manager',
'Rst_Guide_Menu' => 'Speisekarte, Stationen und Zusätze',
'Rst_Guide_Menu_1' => 'Jedes Produkt, das Sie verkaufen, kann ein Gericht sein. Restaurant › Speisekarte (oder die Karte „Angaben zum Gericht“ im Produktformular) ergänzt die Restaurant-Informationen.',
'Rst_Guide_Menu_2' => 'Zusatzgruppen enthalten Auswahlmöglichkeiten mit Preis: „Größe“ (1 wählen) oder „Extras“ (bis zu 3). Die Regeln werden bei jeder Bestellung geprüft, auch online.',
'Rst_Guide_Menu_3' => 'Ein Zusatz kann eine Zutat verbrauchen: Verknüpfen Sie „Extra Käse“ mit Ihrem Produkt „Käse“, dann bucht jede Portion diesen Bestand ab.',
'Rst_Guide_Menu_4' => 'Markieren Sie ein Gericht mit einem Schalter als heute ausverkauft; am nächsten Tag ist es automatisch wieder verfügbar. Essenszeiten (Frühstück, Mittag-, Abendessen) begrenzen, wann ein Gericht angeboten wird.',
'Rst_Guide_Menu_5' => 'Ein Rezept ist ein Kombiprodukt: Bei aktiviertem virtuellem Kombi-Bestand bucht der Verkauf des Gerichts dessen Bestandteile vom Bestand ab.',
'Rst_Guide_Kitchen' => 'Küchendisplay',
'Rst_Guide_Kitchen_1' => 'Öffnen Sie Restaurant › Küche auf einem Bildschirm in der Küche. Wählen Sie die Station; Gerichte ohne Station erscheinen an jeder Station.',
'Rst_Guide_Kitchen_2' => 'Bons werden mit zunehmender Wartezeit gelb und dann rot (Restaurant-Einstellungen › verspätet nach N Minuten). Ein Signalton kündigt neue Bons an.',
'Rst_Guide_Kitchen_3' => 'Starten → Gerichte abhaken → Abschließen. „Fertig an dieser Station“ schließt bei einem geteilten Bon nur die Gerichte dieser Station ab.',
'Rst_Guide_Kitchen_4' => 'Servierte Bons bleiben 15 Minuten sichtbar, damit ein Fehler zurückgeholt werden kann. Bons können auf einem 80-mm-Drucker gedruckt werden.',
'Rst_Guide_Kitchen_5' => 'Bestellungen aus dem Online-Shop und über Tisch-QR-Codes sind auf ihrem Bon mit „Online“ bzw. „QR“ gekennzeichnet.',
'Rst_Guide_Bills' => 'Rechnungen und Zahlungen',
'Rst_Guide_Bills_1' => 'Jede Zahlung ist ein normaler POS-Verkauf: Bestand, Kasse, Buchhaltung, Treuepunkte und E-Rechnung funktionieren wie am POS.',
'Rst_Guide_Bills_2' => 'Die Servicegebühr ist ein Prozentsatz der Gerichte vor Steuern, für Bestellungen vor Ort (oder für jede Bestellung, je nach Einstellung). Trinkgeld ist ein voreingestellter Prozentsatz oder ein Betrag.',
'Rst_Guide_Bills_3' => 'Ein Rabatt erfordert die Berechtigung „Rabatte auf Rechnungen gewähren“ und ist auf den höchstzulässigen Rabatt in den Restaurant-Einstellungen begrenzt.',
'Rst_Guide_Bills_4' => 'Gerundet wird zugunsten des Gastes auf Ihre Stufe abwärts, und zwar bei der Zahlung, die die Rechnung begleicht.',
'Rst_Guide_Bills_5' => 'Gleichmäßig aufteilen: ein Verkauf, eine Zahlungszeile pro Person (Anteile auf den Cent genau). Nach Positionen aufteilen: Die Gerichte jedes Gastes werden ein eigener Verkauf; wählen Sie einen Platz, um dessen Gerichte auszuwählen.',
'Rst_Guide_Bills_6' => 'Hat sich die Rechnung geändert, nachdem sie angezeigt wurde (ein Gericht per QR-Code hinzugefügt, Trinkgeld geändert), wird die Zahlung abgelehnt, damit dem Gast nie etwas berechnet wird, das er nicht gesehen hat.',
'Rst_Guide_Bills_7' => 'Bezahlte Gerichte können nicht storniert werden. Wird der unbezahlte Rest einer Bestellung storniert, wird die Bestellung als bezahlt geschlossen und der Tisch kann abgeräumt werden.',
'Rst_Guide_Bookings' => 'Reservierungen und Warteliste',
'Rst_Guide_Bookings_1' => 'Buchungen halten einen Tisch für ihre Dauer frei (Standard in den Restaurant-Einstellungen). Zwei Buchungen können sich an einem Tisch nie überschneiden.',
'Rst_Guide_Bookings_2' => 'Der Tischplan zeigt die nächste Buchung jedes Tisches und warnt, wenn sie bald ansteht; „Gäste sind da — platzieren“ platziert die Gruppe.',
'Rst_Guide_Bookings_3' => 'Nach Ablauf der No-Show-Zeit kann eine verspätete Gruppe als No-Show markiert werden; ein Fehler lässt sich rückgängig machen.',
'Rst_Guide_Bookings_4' => 'Die Warteliste führt Gäste ohne Reservierung in der richtigen Reihenfolge mit ihrer genannten Wartezeit. Rufen Sie sie an oder schreiben Sie ihnen per WhatsApp, wenn ein Tisch frei ist, und platzieren Sie sie dann.',
'Rst_Guide_Bookings_5' => 'Online-Buchungen kommen als „Gebucht“ an (ein Zähler in der Seitenleiste zeigt sie an) und müssen von Ihnen bestätigt werden.',
'Rst_Guide_Online' => 'Online-Bestellungen, QR-Speisekarten und Online-Buchung',
'Rst_Guide_Online_1' => 'Mit dem Shop-Design „Restaurant“ ist die Startseite des Online-Shops Ihre Speisekarte, mit Zusätzen und Ernährungsfiltern; Kunden bezahlen wie gewohnt im Checkout.',
'Rst_Guide_Online_2' => '„Online-Bestellungen an die Küche“ legt fest, wann sie auf dem Küchendisplay erscheinen: beim Aufgeben (bezahlt oder ein angemeldeter Kunde, der bei Lieferung / Abholung bezahlt), bei Annahme oder nie.',
'Rst_Guide_Online_3' => 'Tisch-QR-Codes (Raumeinrichtung › Tisch-QR-Codes) öffnen die Speisekarte für diesen Tisch. „Neuer Link“ macht einen gedruckten Code ungültig.',
'Rst_Guide_Online_4' => 'QR-Bestellungen warten in der Bestellung des Tisches, bis eine Servicekraft sie sendet, es sei denn, „QR-Bestellungen direkt an die Küche senden“ ist aktiviert. Gäste bezahlen beim Personal.',
'Rst_Guide_Online_5' => 'Die Online-Buchung bietet nur Zeiten an, zu denen ein für die Gruppe passender Tisch für die gesamte Buchung frei ist, und begrenzt jede Telefonnummer auf 3 anstehende Buchungen.',
'Rst_Guide_Online_6' => 'All dies ist Teil des Online-Shops: Er muss aktiviert und in Ihrem Plan enthalten sein.',
'Rst_Guide_Reports' => 'Dashboard und Berichte',
'Rst_Guide_Reports_1' => 'Das Dashboard vergleicht heute mit dem gleichen Tag der Vorwoche: Umsatz, Rechnungen, Gäste, durchschnittliche Rechnung, Stornos und Rabatte sowie das aktuelle Geschehen.',
'Rst_Guide_Reports_2' => 'Der Umsatz umfasst Restaurantrechnungen sowie Online-Bestellungen, die die Küche erreicht haben. Gerichtumsätze und Margen verstehen sich vor Steuern, auf Basis der Kosten des jeweiligen Produkts.',
'Rst_Guide_Reports_3' => 'Berichte: Umsatz nach Tag und Zahlungsmethode, Gerichte, Stornos und stornierte Bestellungen (mit Gründen), Personal, Küchenzeiten und Reservierungen — jeweils als Excel exportierbar.',
'Rst_Guide_Reports_4' => 'Mitarbeiter, die auf bestimmte Filialen beschränkt sind, sehen nur ihre Filialen; Bestellungen ohne Filiale sind für alle sichtbar.',
'Rst_Guide_Faq' => 'Gut zu wissen',
'Rst_Guide_Faq_1_Q' => 'Eine Bestellung zum Mitnehmen wurde bezahlt, bevor ich auf „Senden“ gedrückt habe. Wird sie zubereitet?',
'Rst_Guide_Faq_1_A' => 'Ja. Beim Bezahlen werden alle noch nicht gesendeten Gerichte an die Küche gesendet.',
'Rst_Guide_Faq_2_Q' => 'Warum kann ich einen Tisch nicht freigeben?',
'Rst_Guide_Faq_2_A' => 'Seine Bestellung enthält noch unbezahlte Gerichte. Nehmen Sie die Zahlung an, stornieren Sie, was nicht gegessen wurde, oder stornieren Sie die Bestellung (nur wenn noch nichts bezahlt ist).',
'Rst_Guide_Faq_3_Q' => 'Zwei Tische wurden zusammengeschoben. Was passiert mit ihren Bestellungen?',
'Rst_Guide_Faq_3_A' => '„Tische zusammenstellen“ verschiebt die Gerichte (und etwaige Zahlungen) des zweiten Tisches in die Bestellung des Haupttisches; „Diesen Tisch trennen“ teilt die Tische wieder auf.',
'Rst_Guide_Faq_4_Q' => 'Können Kartenzahlungen hier über Stripe laufen?',
'Rst_Guide_Faq_4_A' => 'Nein. Stripe-Kartenzahlungen benötigen das Kartenformular des POS; für ein Kartenterminal fügen Sie eine Zahlungsmethode wie „Karte“ hinzu und verwenden diese auf der Rechnung.',
'Rst_Guide_Faq_5_Q' => 'Ein Gericht ist nur in einer Filiale nicht vorrätig.',
'Rst_Guide_Faq_5_A' => 'Der Bestand wird aus der Filiale der Bestellung entnommen (dem Bereich des Tisches, ansonsten der Standardfiliale in den Restaurant-Einstellungen). Verwenden Sie „Heute ausverkauft“, um Bestellungen schnell zu stoppen.',
'Rst_Guide_Faq_6_Q' => 'Brauche ich einen Drucker?',
'Rst_Guide_Faq_6_A' => 'Nein. Rechnungen, Belege und Küchenbons werden aus dem Browser auf jedem Drucker gedruckt; 80-mm-Bondrucker eignen sich am besten.',
'Rst_Guide_Faq_7_Q' => 'Woher kommen die Restaurant-Speisekarten im Online-Shop?',
'Rst_Guide_Faq_7_A' => 'Aus denselben Produkten, Kategorien und Zusätzen. Produkte, die im Online-Shop ausgeblendet sind, und Kategorien, die im Shop nicht angezeigt werden, erscheinen weder auf der Online- noch auf der QR-Speisekarte.',

