'Rental_Website_Not_Ready' => 'Installieren Sie das neueste Update, um Geschäftsarten und Website-Buchungen zu nutzen.',
'Rental_Business_Type' => 'Geschäftsart',
'Rental_Business_Type_Help' => 'Haken Sie an, was Sie vermieten. Artikelformular, Kategorien, Filter und Ihre Website zeigen dann nur diese Arten und deren Felder.',
'Rental_Business_Type_All' => 'Nichts angehakt: Alle Arten sind verfügbar.',
'Rental_Website_Booking' => 'Website-Buchung',
'Rental_Website_Theme_Off' => 'Ihr Online-Shop verwendet ein anderes Design. Wählen Sie in den Shop-Einstellungen das Design „Vermietung“, um Ihre Mietobjekte zu veröffentlichen.',
'Rental_Open_Store_Settings' => 'Shop-Einstellungen öffnen',
'Rental_Website_Booking_Help' => 'Besucher wählen auf Ihrer Website Termine und senden eine Buchungsanfrage. Sie erscheint unter Reservierungen als Vorreservierung: Bestätigen Sie sie, wandeln Sie sie in einen Vertrag um oder stornieren Sie sie.',
'Rental_Website_Hold' => 'Anfrage vorhalten für',
'Rental_Website_Hold_Help' => 'Die Artikel bleiben so lange blockiert, bis Sie antworten. Durch Bestätigen bleiben sie bis zum Ende der Miete blockiert.',
'Rental_Website_Notice' => 'Mindestvorlauf',
'Rental_Website_Notice_Help' => 'Wie früh eine Website-Buchung beginnen darf.',
'Rental_Website_Ahead' => 'Buchbar bis',
'Rental_Website_Ahead_Help' => 'Wie weit im Voraus Besucher buchen können.',
'Rental_Website_Login' => 'Anmeldung erforderlich',
'Rental_Website_Login_Help' => 'Nur Kunden mit einem Shop-Konto können Anfragen senden.',
'Rental_Pickup_Locations' => 'Abholorte',
'Rental_Pickup_Locations_Help' => 'Fahrzeuge: die Orte, die Kunden für Abholung und Rückgabe wählen können. Leer lassen, wenn alles in Ihrer Filiale abgeholt wird.',
'Rental_Pickup_Locations_Placeholder' => 'z. B. Flughafen; Büro Innenstadt',
'Rental_Booking_Form_Fields' => 'Felder des Buchungsformulars',
'Rental_Booking_Form_Fields_Help' => 'Was das Buchungsformular auf der Website abfragt, je nach Geschäftsart. Name, Telefon und E-Mail werden immer abgefragt.',
'Rental_Field_Location_Hint' => 'Wird nur angezeigt, wenn Abholorte festgelegt sind.',
