'Rental_Category_Photo' => 'Website-Foto',
'Rental_Category_Photo_Help' => 'Wird auf der Kategoriekachel Ihrer Website verwendet. JPG, PNG oder WebP, bis zu 5 MB.',
'Rental_Suggested_Added' => '{n} Kategorien hinzugefügt',
