'Rental_Website_Requests' => 'Website-Anfragen',
'Rental_Confirm_Booking' => 'Buchung bestätigen',
'Rental_Website_Request_Notice' => 'Buchungsanfrage von Ihrer Website – der Kunde wartet auf Ihre Antwort.',
'Rental_Website_Request_Help' => 'Bestätigen Sie sie (der Kunde erhält eine E-Mail und die Artikel bleiben bis zum Ende der Miete blockiert), wandeln Sie sie in einen Vertrag um oder stornieren Sie sie.',
'Rental_Website_Request' => 'Website-Anfrage',
