'Rental_Booking_Confirmed_Msg' => 'Buchung bestätigt – der Kunde wurde per E-Mail benachrichtigt',
'Rental_Bell_Website_Requests' => 'Zu beantwortende Buchungsanfragen von der Website',
'Rental_Theme' => 'Vermietung',
'Rental_Theme_Needs_Module' => 'erfordert Mietverwaltung',
'Rental_Theme_Unavailable' => 'Das Vermietungs-Theme listet Ihre Artikel aus der Mietverwaltung auf. Fügen Sie die Mietverwaltung zu Ihrem Plan hinzu (und installieren Sie das neueste Update), um es zu verwenden.',
'Rental_Theme_Hint' => 'Ihre Website listet die Artikel aus Vermietung › Artikel mit Live-Verfügbarkeit und Preisen auf. Besucher senden Buchungsanfragen, die unter Vermietung › Reservierungen eingehen.',
