'Rn_Hero_Photo_Hint' => 'Ein breites Foto hinter dem Suchfeld. Ohne Foto wird ein dunkler Farbverlauf verwendet.',
'Rn_Hero_Kicker_Example' => 'z. B. Kostenlose Stornierung bis 24 h vorher',
