'Bkm_Guide_Step_Online' => 'Online buchbar',
'Bkm_Guide_Step_Online_Ok' => '{n} Mitarbeiter können über die Website gebucht werden.',
'Bkm_Guide_Step_Online_Help' => 'Noch kann niemand online gebucht werden, daher können Kunden nur Anfragen senden. Aktivieren Sie bei einem Mitarbeiter „Online buchbar“.',
