'Bkm_Guide_Step_Mail' => 'E-Mail eingerichtet',
'Bkm_Guide_Step_Mail_Ok' => 'Bestätigungen und Erinnerungen können per E-Mail versendet werden.',
'Bkm_Guide_Step_Mail_Help' => 'Ohne Mailserver werden keine Buchungs-E-Mails versendet. Fügen Sie Ihren unter Einstellungen › E-Mail hinzu.',
