'Bkm_Guide_Step_First' => 'Ihre erste Buchung',
'Bkm_Guide_Step_First_Ok' => 'Bisher {n} Buchung(en), davon {web} über die Website.',
'Bkm_Guide_Step_First_Help' => 'Buchen Sie selbst über die Website, um zu sehen, was Kunden sehen, und bestätigen Sie die Buchung dann unter Anfragen.',
'Bkm_Guide_Step_Deposit' => 'Anzahlungen online annehmen',
