'Bkm_Guide_Step_Crm_Ok' => 'Website-Buchungen werden im CRM vermerkt.',
'Bkm_Guide_Step_Crm_Help' => 'Aktivieren Sie „Website-Buchungen ins CRM übernehmen“, um Kunden über Ihre Pipeline nachzuverfolgen.',
'Bkm_Guide_Step_Crm_Unavailable' => 'Erfordert das CRM in Ihrem Plan, aktiviert.',
'Bkm_Guide_Step_Portal' => 'Buchungen im Kundenportal',
'Bkm_Guide_Step_Portal_Ok' => 'Kunden mit Portalkonto sehen dort ihre Buchungen.',
'Bkm_Guide_Step_Portal_Help' => 'Aktivieren Sie das Kundenportal und dessen Bereich „Buchungen“, damit Kunden ihre Termine verfolgen können.',
'Bkm_Guide_How' => 'So funktioniert es',
'Bkm_Guide_Website' => 'Eine Buchung über die Website',
'Bkm_Guide_Website_1_T' => 'Leistung wählen',
'Bkm_Guide_Website_1' => 'der Kunde beginnt mit dem Formular auf Ihrer Startseite oder der Buchungsseite.',
'Bkm_Guide_Website_2_T' => 'Zeit wählen oder Anfrage senden',
'Bkm_Guide_Website_2' => 'freie Zeiten ergeben sich aus den Arbeitszeiten, freien Tagen und anderen Buchungen Ihrer Mitarbeiter; eine Anfrage nennt nur einen Wunschtag und eine Tageszeit.',
'Bkm_Guide_Website_3_T' => 'Die Kundendaten',
'Bkm_Guide_Website_3' => 'Name, Telefon, E-Mail und die Fragen Ihrer Geschäftsart.',
'Bkm_Guide_Website_4_T' => 'Anzahlung',
'Bkm_Guide_Website_4' => 'wenn Sie eine anfordern, wird sie sofort bezahlt, um die Zeit zu sichern.',
'Bkm_Guide_Website_5_T' => 'Wartet auf Sie',
'Bkm_Guide_Website_5' => 'die Buchung landet als ausstehend unter Anfragen, und die Zeit wird für den Kunden reserviert (außer bei aktivierter automatischer Bestätigung).',
'Bkm_Guide_Website_6_T' => 'Die Buchungsseite des Kunden',
'Bkm_Guide_Website_6' => 'der Kunde verfolgt sie über den Link in seiner E-Mail: Status, zum Kalender hinzufügen, stornieren, auf eine vorgeschlagene Zeit antworten.',
'Bkm_Guide_Requests' => 'Anfragen beantworten',
'Bkm_Guide_Requests_1' => 'Unter Anfragen sehen Sie alle Buchungen, die auf Sie warten – die älteste Reservierung zuerst –, mit einem Zähler im Menü.',
'Bkm_Guide_Requests_2' => '„Bestätigen“ wählt einen Mitarbeiter für Sie, wenn Sie das Feld leer lassen, und prüft, ob die Zeit noch frei ist.',
'Bkm_Guide_Requests_3' => 'Schlagen Sie eine andere Zeit vor, wenn die gewünschte nicht passt – der Kunde nimmt sie auf seiner Buchungsseite an.',
'Bkm_Guide_Requests_4' => 'Lehnen Sie mit Begründung ab; der Kunde sieht sie.',
'Bkm_Guide_Requests_5' => 'Eine abgelaufene Reservierung gibt die Zeit frei; die Buchung bleibt bestehen, bis Sie sie beantworten.',
'Bkm_Guide_Day' => 'Am Termintag',
'Bkm_Guide_Day_1' => 'Die Tagesansicht zeigt die Buchungen aller Mitarbeiter nebeneinander.',
'Bkm_Guide_Day_2' => 'Markieren Sie „Erschienen“, wenn der Kunde eintrifft.',
'Bkm_Guide_Day_3' => '„Abschließen & abrechnen“ erstellt den Verkauf über den POS, wobei die Anzahlung bereits berücksichtigt ist.',
'Bkm_Guide_Day_4' => '„Ohne Abrechnung abschließen“, wenn auf andere Weise bezahlt wurde.',
'Bkm_Guide_Day_5' => 'Markieren Sie „Nicht erschienen“, sobald die Startzeit vorbei ist.',
'Bkm_Guide_Day_6' => 'Das Dashboard zeigt den heutigen Terminplan, was noch ansteht und was noch nicht abgerechnet ist.',
'Bkm_Guide_Deposits' => 'Anzahlungen',
'Bkm_Guide_Deposits_1' => 'Legen Sie den Betrag unter Buchungseinstellungen › Anzahlung fest; eine Leistung kann einen eigenen haben.',
'Bkm_Guide_Deposits_2' => 'Kunden zahlen über die unter Onlineshop › Zahlungs-Gateway eingerichteten Zahlungsanbieter, in Ihrer Basiswährung.',
'Bkm_Guide_Deposits_3' => 'Die Zeit wird für die Zahlung reserviert; unbezahlte Buchungen können automatisch storniert werden.',
'Bkm_Guide_Deposits_4' => 'Eine erfolgreiche Zahlung, nach der der Kunde nicht zurückgekehrt ist, wird automatisch erkannt.',
'Bkm_Guide_Deposits_5' => 'Wenn Sie die Buchung abrechnen, ist die Anzahlung die erste Zahlung auf den Verkauf.',
'Bkm_Guide_Deposits_6' => 'Erstattungen erfolgen bei Ihrem Zahlungsanbieter; markieren Sie die Anzahlung danach in der Buchung als erstattet.',
'Bkm_Guide_Messages' => 'E-Mails, WhatsApp und Erinnerungen',
'Bkm_Guide_Messages_1' => 'Kunden erhalten eine E-Mail, wenn ihre Buchung eingegangen, bestätigt, abgelehnt, geändert oder storniert ist.',
'Bkm_Guide_Messages_2' => 'Sie erhalten eine bei jeder neuen Website-Buchung, jeder Stornierung durch Kunden und jeder bezahlten Anzahlung.',
'Bkm_Guide_Messages_3' => 'Vor jedem bestätigten Termin wird eine Erinnerung versendet (Buchungseinstellungen › Benachrichtigungen).',
'Bkm_Guide_Messages_4' => 'Aktivieren Sie „Auch per WhatsApp senden“, um dieselben Nachrichten auch dort zu versenden.',
'Bkm_Guide_Messages_5' => 'Jede Nachricht wird in der Buchung aufgeführt – mit dem Grund, falls sie nicht gesendet wurde.',
'Bkm_Guide_Customers' => 'Kunden, CRM und Portal',
'Bkm_Guide_Customers_1' => 'Eine Website-Buchung wird zu Ihren Kunden hinzugefügt; wer erneut mit derselben E-Mail-Adresse und Telefonnummer bucht, wird zugeordnet.',
'Bkm_Guide_Customers_2' => 'Mit dem CRM in Ihrem Plan können Buchungen beim Kunden oder seinem Lead vermerkt werden, und Anfragen können einen Deal anlegen.',
'Bkm_Guide_Customers_3' => 'Kunden mit einem Kundenportal-Konto sehen dort ihre Buchungen und können stornieren oder auf eine vorgeschlagene Zeit antworten.',
'Bkm_Guide_Customers_4' => 'Angemeldete Shop-Kunden finden ihre Buchungen unter Mein Konto.',
'Bkm_Guide_Roles' => 'Wer darf was',
'Bkm_Guide_Roles_Help' => 'Geben Sie jeder Rolle nur die Berechtigungen, die sie benötigt (Einstellungen › Gruppenberechtigungen).',
'Bkm_Guide_Job' => 'Aufgabe',
'Bkm_Guide_Give' => 'Zu vergeben',
'Bkm_Guide_Job_Front_Desk' => 'Empfang',
'Bkm_Guide_Job_Staff_Member' => 'Mitarbeiter',
'Bkm_Guide_Job_Manager' => 'Manager',
'Bkm_Guide_Job_Owner' => 'Inhaber oder Buchhalter',
'Bkm_Guide_Faq' => 'Fragen',
'Bkm_Guide_Faq_1_Q' => 'Warum wird eine Leistung nicht auf der Website angezeigt?',
'Bkm_Guide_Faq_1_A' => 'Sie benötigt Buchungsdetails (Leistungen), aktiviertes „Auf der Website anzeigen“, ein aktives Produkt und – für die Zeitwahl – einen online buchbaren Mitarbeiter, der sie erbringt.',
'Bkm_Guide_Faq_2_Q' => 'Warum gibt es keine freien Zeiten?',
'Bkm_Guide_Faq_2_A' => 'Prüfen Sie die Arbeitszeiten, freien Tage, Feiertage und den genehmigten Urlaub der Mitarbeiter, die Vorlaufzeit und wie viele Tage im Voraus Kunden buchen können.',
'Bkm_Guide_Faq_3_Q' => 'Können zwei Kunden dieselbe Zeit buchen?',
'Bkm_Guide_Faq_3_A' => 'Nein. Die Zeit wird bei der Buchung erneut geprüft, und eine reservierte oder bestätigte Buchung blockiert sie. Kurse teilen sich Plätze bis zu ihrem Limit.',
'Bkm_Guide_Faq_4_Q' => 'Was passiert, wenn eine Reservierung abläuft?',
'Bkm_Guide_Faq_4_A' => 'Die Zeit ist wieder für andere frei. Die Buchung bleibt unter Anfragen, bis Sie sie beantworten (oder wird storniert, wenn ihre Anzahlung nicht bezahlt wurde).',
'Bkm_Guide_Faq_5_Q' => 'Brauchen Kunden ein Konto?',
'Bkm_Guide_Faq_5_A' => 'Nein. Sie erhalten einen privaten Link zu ihrer Buchungsseite. In Shop- und Portalkonten werden ihre Buchungen ebenfalls angezeigt.',
'Bkm_Guide_Faq_6_Q' => 'Wohin fließt das Geld?',
'Bkm_Guide_Faq_6_A' => 'Anzahlungen gehen an Ihren Zahlungsanbieter; der Rest wird an der Kasse (POS) kassiert, wenn Sie die Buchung abrechnen. Berichte erfassen den Umsatz aus diesen Verkäufen.',
'Bkm_Guide_Faq_7_Q' => 'Warum hat ein Kunde keine E-Mail erhalten?',
'Bkm_Guide_Faq_7_A' => 'Öffnen Sie die Buchung: In der Nachrichtenliste steht für jede E-Mail, ob sie gesendet wurde, fehlgeschlagen ist oder übersprungen wurde – und warum.',
'Bkm_Staff_Removed' => 'entfernt',
'Bkm_Staff_Not_Bookable' => 'Nicht mehr buchbar',
'Bkm_Requests_Cut' => 'Die ältesten {n} werden angezeigt. Beantworten Sie einige, um die übrigen zu sehen, oder nutzen Sie die Suche.',

