'Mkg_Guide_Flow_4_T' => 'Jetzt senden oder planen',
'Mkg_Guide_Flow_4' => '„Jetzt senden“ startet sofort; „Planen“ sendet zum gewählten Datum und zur gewählten Uhrzeit.',
'Mkg_Guide_Flow_5_T' => 'Die Empfängerliste wird erstellt',
'Mkg_Guide_Flow_5' => 'sobald Sie senden, wird jeder passende Kunde als „Ausstehend“ hinzugefügt, sodass Sie sofort sehen, wer sie erhält.',
'Mkg_Guide_Flow_6_T' => 'Die Zustellung läuft im Hintergrund',
'Mkg_Guide_Flow_6' => 'Nachrichten werden in Stapeln versendet (Stapelgröße in den Marketing-Einstellungen), und die Zähler werden nach jedem Stapel aktualisiert.',
'Mkg_Guide_Flow_7_T' => 'Ergebnisse prüfen',
'Mkg_Guide_Flow_7' => 'die Kampagne öffnen, um jeden Empfänger mit Status und eventuellem Fehler zu sehen; „Berichte“ fasst alle Kanäle zusammen.',
'Mkg_Guide_Audience' => 'Wer sie erhält',
'Mkg_Guide_Audience_1' => '„Alle Kunden“ sendet an jeden Kunden, der nicht gelöscht wurde.',
'Mkg_Guide_Audience_2' => 'Ein Segment filtert Kunden nach Stadt, Datum des letzten Einkaufs, Anzahl der Einkäufe und Gesamtumsatz. Die Vorschau zeigt vor dem Speichern, wie viele passen.',
'Mkg_Guide_Audience_3' => 'Die Liste wird beim Klick auf „Senden“ festgelegt. Später hinzugefügte Kunden werden nicht berücksichtigt.',
'Mkg_Guide_Audience_4' => 'Kunden ohne E-Mail-Adresse (E-Mail) oder Telefonnummer (SMS, WhatsApp) bleiben als „Übersprungen“ auf der Liste.',
'Mkg_Guide_Audience_5' => 'Wird eine fehlgeschlagene Kampagne erneut gesendet, wird die Liste aus dem Segment neu erstellt und alle werden erneut versucht.',
'Mkg_Guide_Audience_Leads' => 'Mit aktiviertem CRM kann ein Segment statt Kunden CRM-Leads ansprechen (Tags, Quelle, Status, Score und mehr). Abgemeldete Leads werden übersprungen, und E-Mails an Leads enthalten immer einen Abmeldelink.',
'Mkg_Guide_Channels' => 'Kanäle',
'Mkg_Guide_Ch_email_1' => 'Wird über Ihren eigenen Mailserver gesendet (Einstellungen > E-Mail-Einstellungen). Der Mailer der Plattform wird nie verwendet.',
'Mkg_Guide_Ch_email_2' => 'Absendername und -adresse stammen aus den Marketing-Einstellungen, andernfalls vom Mailserver.',
'Mkg_Guide_Ch_email_3' => 'Fügen Sie einen Betreff und optional einen Anhang hinzu. Die Nachricht kann HTML enthalten.',
'Mkg_Guide_Ch_email_4' => 'Kunden ohne E-Mail-Adresse werden übersprungen.',
'Mkg_Guide_Ch_sms_1' => 'Funktioniert mit jedem HTTP-SMS-Gateway: Geben Sie API-URL, Schlüssel, Absender-ID, Methode und die erwarteten Feldnamen ein.',
'Mkg_Guide_Ch_sms_2' => 'Jeder Kunde mit Telefonnummer erhält eine SMS; die übrigen werden übersprungen.',
'Mkg_Guide_Ch_sms_3' => 'Ihr Gateway berechnet jede Nachricht, testen Sie daher zuerst an einem kleinen Segment.',
'Mkg_Guide_Ch_whatsapp_1' => 'Verbinden Sie ein WhatsApp-HTTP-Gateway oder die Meta WhatsApp Cloud API (graph.facebook.com).',
'Mkg_Guide_Ch_whatsapp_2' => 'Wenn ein Kunde Ihnen vor mehr als 24 Stunden zuletzt geschrieben hat, stellt WhatsApp nur von Meta genehmigte Vorlagen zu.',
'Mkg_Guide_Ch_whatsapp_3' => 'Wählen Sie bei der Cloud API in der Kampagne die genehmigte Vorlage und füllen Sie ihre Parameter aus.',
'Mkg_Guide_Ch_whatsapp_4' => 'Kunden ohne Telefonnummer werden übersprungen.',
