'Mkg_Guide_Schedule' => 'Zeitplanung',
'Mkg_Guide_Schedule_1' => 'Aktivieren Sie „Zeitplanung aktivieren“ in den Marketing-Einstellungen und wählen Sie dann in der Kampagne „Planen“ sowie Datum und Uhrzeit.',
'Mkg_Guide_Schedule_2' => 'Fällige Kampagnen werden jede Minute geprüft und automatisch gesendet.',
'Mkg_Guide_Schedule_3' => 'Eine Kampagne, die mehr als einen Tag überfällig ist, wird storniert statt verspätet gesendet. Bearbeiten Sie sie und wählen Sie einen neuen Zeitpunkt.',
'Mkg_Guide_Schedule_4' => 'Eine geplante Kampagne kann weiterhin bearbeitet oder mit „Jetzt senden“ sofort gesendet werden.',
