'Mkg_Guide_Perm_marketing_dashboard' => 'Das Marketing-Dashboard sehen: Summen und letzte Kampagnen.',
'Mkg_Guide_Perm_marketing_campaigns' => 'Kampagnen erstellen, bearbeiten, senden und löschen sowie ihre Empfänger sehen.',
