'Mkg_Guide_Faq' => 'Häufige Fragen',
'Mkg_Guide_Faq_1_Q' => 'Meine Kampagne bleibt bei „Wird gesendet“ und nichts wird versendet.',
'Mkg_Guide_Faq_1_A' => 'Der Hintergrundversand hat sie nicht übernommen. Nach 30 Minuten ohne Fortschritt erscheint die Schaltfläche „Jetzt senden“ wieder: Klicken Sie darauf, um fortzufahren. Wenn das wiederholt auftritt, bitten Sie Ihren Plattformadministrator zu prüfen, ob die Hintergrundjobs (der Queue-Worker) laufen.',
'Mkg_Guide_Faq_2_Q' => 'Empfänger zeigen „Übersprungen: E-Mail-Kanal deaktiviert“.',
'Mkg_Guide_Faq_2_A' => 'Aktivieren Sie „E-Mail aktivieren“ in den Marketing-Einstellungen und senden Sie die Kampagne dann erneut.',
'Mkg_Guide_Faq_3_Q' => 'Empfänger zeigen „Kein Mailserver konfiguriert“.',
'Mkg_Guide_Faq_3_A' => 'E-Mail-Kampagnen laufen nur über Ihren eigenen Mailserver. Fügen Sie ihn unter Einstellungen > E-Mail-Einstellungen hinzu.',
'Mkg_Guide_Faq_4_Q' => 'Weniger Personen haben die Nachricht erhalten, als in meinem Segment sind.',
'Mkg_Guide_Faq_4_A' => 'Kunden ohne E-Mail-Adresse (E-Mail) oder Telefonnummer (SMS, WhatsApp) werden übersprungen. Öffnen Sie die Kampagne, um zu sehen, wer übersprungen wurde und warum.',
'Mkg_Guide_Faq_5_Q' => 'Bedeutet „Gesendet“, dass der Kunde sie erhalten hat?',
'Mkg_Guide_Faq_5_A' => '„Gesendet“ bedeutet, dass Ihr Mailserver bzw. Gateway die Nachricht angenommen hat. Zustellung in den Posteingang, Öffnungen und Spamfilterung werden nicht erfasst.',
'Mkg_Guide_Faq_6_Q' => 'Kann ich eine Kampagne nach dem Senden bearbeiten?',
'Mkg_Guide_Faq_6_A' => 'Nein. Kampagnen, die gerade gesendet werden oder gesendet wurden, sind gesperrt; erstellen Sie stattdessen eine neue Kampagne.',
'Mkg_Guide_Faq_7_Q' => 'Meine WhatsApp-Nachrichten kommen nicht an.',
'Mkg_Guide_Faq_7_A' => 'Wenn ein Kunde Ihnen vor mehr als 24 Stunden zuletzt geschrieben hat, stellt WhatsApp nur von Meta genehmigte Vorlagen zu. Verwenden Sie die WhatsApp Cloud API und wählen Sie in der Kampagne eine genehmigte Vorlage.',
'Mkg_Guide_Faq_8_Q' => 'Wenn ich eine Kampagne erneut sende, erhalten Kunden sie dann doppelt?',
'Mkg_Guide_Faq_8_A' => 'Das Fortsetzen einer hängenden Kampagne sendet nur an noch ausstehende Empfänger, sodass niemand, der bereits erreicht wurde, erneut eine Nachricht erhält. Das erneute Senden einer fehlgeschlagenen Kampagne beginnt mit einer neuen Liste von vorn.',

