'Pd_Installments' => 'Raten',
'Pd_Single_Payment' => 'Einmalzahlung',
'Pd_Guide_How_Title' => 'So funktioniert es',
'Pd_Guide_How_Intro' => 'Ein POS-Gerät ist ein Kartenterminal oder eine Fiskalkasse neben der Kasse. Stocky sendet ihm den Betrag, wartet, bis der Kunde bezahlt, und erfasst die Zahlung erst, wenn das Gerät sie genehmigt hat.',
'Pd_Guide_Step_1' => 'Fügen Sie das Gerät hier hinzu: Modell, Lager und die Zahlungsmethode, unter der seine Kartenzahlungen erfasst werden (zum Beispiel „Kreditkarte“).',
'Pd_Guide_Step_2' => 'Wählen Sie, wie Stocky es erreicht: über eine lokale Bridge auf dem Kassen-PC oder über die Cloud-API Ihres Anbieters. Geben Sie die IDs und Schlüssel Ihrer Bank bzw. Ihres Anbieters ein.',
'Pd_Guide_Step_3' => 'Klicken Sie auf „Verbindung testen“. Bridge-Geräte müssen von dem Kassen-PC aus getestet werden, auf dem die Bridge läuft.',
'Pd_Guide_Step_4' => 'Wählen Sie am POS diese Zahlungsmethode, klicken Sie auf „Am Gerät belasten“ und lassen Sie den Kunden bezahlen. Der Verkauf kann abgeschlossen werden, sobald das Gerät genehmigt.',
'Pd_Guide_Step_5' => 'Prüfen Sie unter „Transaktionen“ Kartenzahlungen ohne Verkauf (zum Beispiel bei einem abgebrochenen Bezahlvorgang) und stornieren oder erstatten Sie sie.',
'Pd_Guide_Bridge_Text' => 'Für Geräte, die über ein Hersteller-SDK auf dem Kassen-PC gesteuert werden (Kopplung per USB, seriell oder LAN). Der Browser kann das SDK nicht direkt nutzen, daher kapselt es ein kleines Bridge-Programm, das auf diesem Computer lauscht.',
'Pd_Guide_Bridge_Point_1' => 'Der POS sendet jede Anfrage aus dem Browser des Kassierers an die Bridge-URL; der Server von Stocky muss Ihr Ladennetzwerk nie erreichen.',
'Pd_Guide_Bridge_Point_2' => 'Anfragen und Antworten werden mit dem gemeinsamen Secret signiert, sodass eine Genehmigung nicht im Browser gefälscht werden kann.',
'Pd_Guide_Bridge_Point_3' => 'Installieren und starten Sie die Bridge auf jedem Computer, der Kartenzahlungen über dieses Gerät annimmt.',
'Pd_Guide_Cloud_Text' => 'Für Anbieter, die das Gerät über das Internet erreichen. Der Server von Stocky ruft die API auf, daher muss auf dem Kassen-PC nichts installiert werden.',
'Pd_Guide_Cloud_Point_1' => 'Die API-URL muss https:// auf einer öffentlichen Adresse sein.',
'Pd_Guide_Cloud_Point_2' => 'Während der Kunde bezahlt, fragt Stocky alle 2 Sekunden den Status ab, daher sollte der Status-Endpunkt die Zahlung anhand ihrer Referenz kennen; antwortet die API, bevor die Kartenzahlung abgeschlossen ist („pending“), entscheidet die Statusabfrage.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'Die IDE280 ist eine Fiskalkasse der neuen Generation (YN ÖKC) mit Kartenleser. Sie wird normalerweise über das ECR- / GMP3-SDK von Ingenico oder über den Integrationsdienst Ihrer Bank angebunden.',
'Pd_Guide_Ide280_Point_1' => 'Koppeln Sie das Gerät wie in der Ingenico- / Bank-Dokumentation beschrieben mit dem Kassen-PC und richten Sie dann die Bridge (oder die API-Einstellungen) darauf aus.',
'Pd_Guide_Ide280_Point_2' => 'Beträge werden sowohl als Dezimalzahl als auch in Kuruş (amount_minor) gesendet, mit der Währung TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'Bei „Vollständiger Fiskalbeleg“ trägt jeder Artikel die Gerätewarengruppe seines MwSt.-Satzes – stimmen Sie die MwSt.-Warengruppen auf die Programmierung des Geräts ab.',
'Pd_Guide_Protocol_Title' => 'Bridge- / API-Schnittstelle',
'Pd_Guide_Protocol_Intro' => 'Stocky kommuniziert per JSON mit der Bridge bzw. API. Die folgenden Pfade sind die Standardwerte und können pro Gerät unter „Erweitert“ geändert werden.',
'Pd_Guide_Operation' => 'Vorgang',
'Pd_Guide_Default_Endpoint' => 'Standard-Endpunkt',
'Pd_Guide_When' => 'Wann',
'Pd_Guide_When_Ping' => 'Schaltfläche „Verbindung testen“.',
'Pd_Guide_When_Sale' => 'Der Kassierer klickt auf „Am Gerät belasten“. Kann antworten, wenn die Kartenzahlung abgeschlossen ist, oder sofort mit dem Status „pending“.',
'Pd_Guide_When_Status' => 'Alle 2 Sekunden, solange die Zahlung aussteht.',
'Pd_Guide_When_Cancel' => 'Der Kassierer bricht ab, während auf die Karte gewartet wird.',
'Pd_Guide_When_Void' => 'Stornieren einer Zahlung (am selben Tag, gesamter Betrag).',
'Pd_Guide_When_Refund' => 'Teilweise oder vollständige Erstattung einer Zahlung.',
'Pd_Guide_Request_Title' => 'Anfrage',
'Pd_Guide_Request_Text' => 'Der Body, den Stocky für einen Verkauf sendet. Erstattung und Storno enthalten die ursprüngliche Zahlung als „original“.',
'Pd_Guide_Response_Title' => 'Antwort',
'Pd_Guide_Response_Text' => 'Feldnamen werden flexibel gelesen (auch unter „data“); „status“ oder der response_code „00“ entscheidet über das Ergebnis. Kartennummern werden maskiert gespeichert.',
'Pd_Guide_Signing_Title' => 'Signierung (Bridge)',
'Pd_Guide_Signing_Text' => 'Die Bridge sollte die Signatur von Stocky prüfen und muss ihren exakten Antwort-Body signieren sowie „reference“ und „operation“ zurückgeben – unsignierte Antworten oder Antworten zu einem anderen Vorgang werden abgelehnt.',
'Pd_Guide_Browser_Title' => 'Browserzugriff (Bridge)',
'Pd_Guide_Browser_Text' => 'Die POS-Seite ruft die Bridge aus dem Browser auf, daher muss die Bridge mit diesen CORS-Headern antworten (einschließlich des OPTIONS-Preflights).',
'Pd_Guide_Safety_Title' => 'Gut zu wissen',
'Pd_Guide_Safety_1' => 'Ein Verkauf wird nur mit einer genehmigten Gerätezahlung über denselben Betrag gespeichert; eine Gerätezahlung kann nie zwei Verkäufe bezahlen.',
'Pd_Guide_Safety_2' => 'Wird das Zahlungsfenster geschlossen, nachdem eine Karte belastet wurde, wird diese Belastung zuerst storniert.',
'Pd_Guide_Safety_3' => 'Antwortet das Gerät nicht rechtzeitig, wird die Zahlung als „Keine Antwort“ angezeigt: Prüfen Sie das Gerät und stornieren Sie die Belastung unter „Transaktionen“, falls die Karte belastet wurde.',
'Pd_Guide_Safety_4' => 'Erstattungen und Stornos hier bewegen nur Geld auf der Karte; sie ändern den Verkauf nicht. Erfassen Sie zurückgegebene Ware unter „Verkaufsretouren“.',
'Perm_Pos_Terminals_Manage' => 'POS-Geräte: verwalten, erstatten & stornieren',
'Perm_Pos_Terminals_Transactions' => 'POS-Geräte: Transaktionen anzeigen',
'Pd_Check_Again' => 'Erneut prüfen',
'Pd_Lost_Track' => 'Die Verbindung brach ab, bevor das Gerät antwortete. Prüfen Sie das Gerät und klicken Sie dann auf „Erneut prüfen“ – belasten Sie nicht erneut, bevor Sie Gewissheit haben.',
'Pd_Close_Anyway' => 'Die Kartenzahlung konnte nicht storniert werden. Trotzdem schließen? Sie bleibt unter POS-Geräte › Transaktionen als „Belastet ohne Verkauf“, damit sie dort storniert oder erstattet werden kann.',
'Pd_Devices_Loading' => 'Die Kartengeräte werden geladen – versuchen Sie es gleich noch einmal.',
'Pd_Devices_Unavailable' => 'Die Kartengeräte konnten nicht geladen werden, daher kann diese Zahlungsmethode gerade nicht verwendet werden. Wählen Sie eine andere Methode oder öffnen Sie das Zahlungsfenster erneut.',
