'Api_Keys' => 'Schlüssel',
'Api_Not_Ready' => 'Die API ist noch nicht eingerichtet: Führen Sie zuerst das Datenbank-Update aus.',
'Api_Keys_Help' => 'Mit Schlüsseln kann ein anderes System (ein ERP, ein Onlineshop, Ihr eigener Katalog) Stocky direkt lesen und aktualisieren. Ein Schlüssel handelt in Ihrem Namen: Er kann alles, was Ihre Rolle kann, in Ihren Lagern. Ein Nur-Lese-Schlüssel kann nur lesen. Widerrufen Sie einen Schlüssel sofort, wenn er möglicherweise offengelegt wurde.',
