'Api_Ep_Upsert_Notes' => 'Ein unbekannter Code legt ein Standardprodukt an (Name, Kategorie, Einheit, Kosten und Preis erforderlich). Ein bekannter Code aktualisiert nur die gesendeten Felder. Ein Variantencode aktualisiert die Preise dieser Variante. barcodes ersetzt die Liste der zusätzlichen Barcodes.',
'Api_Ep_Stock' => 'Bestände',
'Api_Ep_Adjust' => 'Bestandskorrektur buchen',
