'Cd_Err_unknown' => 'Verifizierung fehlgeschlagen. Bitte prüfen Sie die DNS-Einstellungen.',
'Cd_Found_Records' => 'Gefundene Einträge',
'Cd_Guide_Title' => 'So funktioniert es',
'Cd_Guide_1' => 'Fügen Sie eine Domain hinzu, die Ihnen gehört, z. B. shop.example.com.',
'Cd_Guide_2' => 'Melden Sie sich bei Ihrem Domain-Anbieter an (GoDaddy, Namecheap, Cloudflare ...) und legen Sie den angezeigten DNS-Eintrag an.',
'Cd_Guide_3' => 'Kommen Sie zurück und klicken Sie auf „DNS prüfen“. Nach der Verifizierung sind Ihr Arbeitsbereich, Ihr Onlineshop und Ihr Kundenportal unter dieser Domain erreichbar.',
'Cd_Guide_4' => 'Ihre Plattform-Subdomain funktioniert neben der eigenen Domain weiterhin.',
'Cd_Cloudflare_Note' => 'Cloudflare-Nutzer: Stellen Sie den Eintrag bis zum Abschluss der Verifizierung auf DNS only (graue Wolke).',
'Perm_custom_domains' => 'Eigene Domain (Einstellungen > Eigene Domain)',
'List_Too_Big_All' => 'Diese Liste hat mehr als {count} Zeilen, daher ist die Option „Alle“ deaktiviert. Es werden 100 Zeilen pro Seite angezeigt. Grenzen Sie die Liste über Suche oder Filter ein.',
'List_Too_Big_Export' => 'Diese Liste hat mehr als {count} Zeilen – zu viele für einen einzigen Export. Grenzen Sie die Liste über Suche oder Filter ein.',
'PartiallyPaid' => 'Teilweise bezahlt',
'Ord_Guide_PayAuto_Tip' => 'Wird automatisch aktualisiert, wenn Zahlungen beim Verkauf erfasst werden. Klicken Sie hier, um zu sehen, wie Sie eine Zahlung erfassen.',
'Ord_Guide_PayAuto_Intro' => 'Diese Spalte zeigt, wie viel der Bestellung bezahlt ist. Sie richtet sich zunächst nach der Zahlungsart, die der Kunde an der Kasse gewählt hat, und wird dann automatisch aktualisiert, sobald Zahlungen beim Verkauf erfasst werden, der beim Bestätigen der Bestellung entsteht. Auf dieser Seite kann sie nicht bearbeitet werden.',
'Ord_Guide_PayAuto_Paid' => 'Der volle Betrag ist eingegangen. Hat der Kunde online über einen Zahlungsanbieter bezahlt, wird der Verkauf beim Bestätigen der Bestellung als „Bezahlt“ angelegt und die Zahlung automatisch erfasst. Andernfalls wechselt der Status auf „Bezahlt“, sobald die Zahlungen beim Verkauf den Gesamtbetrag decken.',
'Ord_Guide_PayAuto_Partial' => 'Beim Verkauf wurde eine Zahlung erfasst, ein Teil des Gesamtbetrags ist aber noch offen.',
'Ord_Guide_PayAuto_Pending' => 'Es ist noch keine Zahlung eingegangen: Nachnahme, Banküberweisung oder eine andere Zahlungsart mit späterer Zahlung. Beim Bestätigen der Bestellung wird der Verkauf als „Unbezahlt“ angelegt, und Sie erfassen das Geld selbst, sobald Sie es erhalten haben. Siehe die Schritte unten.',
'Ord_Guide_PayAuto_Note' => 'Der hier angezeigte Zahlungsstatus folgt dem Verkauf: Er wechselt automatisch auf „Teilweise bezahlt“ oder „Bezahlt“, wenn Sie eine Zahlung speichern, und wieder zurück, wenn Sie eine löschen. Der Verkauf ist der Buchhaltungsbeleg und speist Ihre Zahlungs- und Gewinnberichte. Über „Zahlungen anzeigen“ beim Verkauf können Sie Ihre Eingaben prüfen oder bearbeiten.',
'Ord_LinkedSale' => 'Verknüpfter Verkauf',
'Ord_LinkedSale_Missing' => 'Mit dieser Bestellung ist kein Verkauf verknüpft. Der Verkauf wurde möglicherweise gelöscht, oder die Bestellung wurde bestätigt, bevor Bestellungen mit Verkäufen verknüpft wurden.',
'Sale_FromOnlineOrder' => 'Dieser Verkauf stammt aus der Online-Bestellung',
'Mod_Opencart_Desc' => 'OpenCart-Shop-Synchronisierung: Produkte, Bestand und Bestellungen.',
'Int_Desc_Opencart' => 'Synchronisieren Sie Produkte, Varianten, Bestand und Bestellungen mit Ihrem OpenCart-Shop.',
'Perm_opencart_settings' => 'OpenCart-Integration',
'Oc_Hero_Desc' => 'Synchronisieren Sie Produkte, Varianten, Bestand und Bestellungen mit Ihrem OpenCart-Shop über den {company} Connector.',
'Oc_Connector' => '{company} Connector',
'Oc_Download_Connector' => 'Für OpenCart 4 herunterladen',
'Oc_Connector_Help' => 'OpenCart bietet keine API für Produkte oder Bestand, daher wird zuerst diese kleine Erweiterung in Ihrem Shop installiert.',
'Oc_Secret' => 'Connector-Secret',
'Oc_Secret_Placeholder' => 'Aus dem Modul {company} Connector',
'Oc_Secret_Help' => 'Öffnen Sie das Modul {company} Connector in OpenCart und kopieren Sie das Secret hierher. Es wird verschlüsselt gespeichert und nie wieder angezeigt.',
'Oc_Store' => 'OpenCart-Shop',
'Oc_Versions' => 'Connector {connector} auf OpenCart {opencart}',
'Oc_Automation' => 'Automatisierung',
'Oc_Auto_Orders' => 'Bestellungen automatisch importieren',
'Oc_Auto_Orders_Help' => 'Neue Bestellungen und Statusänderungen kommen sofort an; alle paar Minuten wird zusätzlich nach Verpasstem gesucht.',
'Oc_Auto_Stock' => 'Bestand automatisch übertragen',
'Oc_Auto_Stock_Help' => 'Jede Bestandsbewegung aktualisiert den Shop, und einmal pro Stunde wird der gesamte Bestand geprüft.',
'Oc_Auto_Products' => 'Produktänderungen automatisch übertragen',
'Oc_Auto_Products_Help' => 'Ein hier angelegtes oder bearbeitetes Produkt aktualisiert den Shop: Name, Preis, Status und Bestand.',
'Oc_Order_Statuses' => 'Bestellstatus',
'Oc_Order_Statuses_Help' => 'Was jeder OpenCart-Status hier bedeutet. Die Werte wurden aus Ihrem Shop übernommen und müssen nur geändert werden, wenn Sie eigene Status verwenden.',
'Oc_Commit_Statuses' => 'Abgeschlossener Verkauf',
'Oc_Commit_Statuses_Help' => 'Der Verkauf ist abgeschlossen und der Bestand wird abgebucht. Halten Sie dies identisch mit den Status, die in OpenCart Bestand abziehen.',
'Oc_Paid_Statuses' => 'Bezahlt',
'Oc_Paid_Statuses_Help' => 'Für den noch offenen Betrag wird eine Zahlung erfasst.',
'Oc_Cancel_Statuses' => 'Storniert',
'Oc_Cancel_Statuses_Help' => 'Der Verkauf wird rückgängig gemacht: Der Bestand wird zurückgebucht und seine Zahlungen werden entfernt.',
'Oc_Variants_Linked' => 'Verknüpfte Varianten',
'Oc_Push_Desc' => 'Legt fehlende Produkte und Varianten in OpenCart an und aktualisiert Name, Preis, Status und Bestand der verknüpften. Beschreibungen, Bilder und Kategorien werden nur gesetzt, wenn ein Produkt neu ist oder keine hat, sodass in OpenCart verfasste Texte erhalten bleiben.',
'Oc_Pull_Desc' => 'Importiert OpenCart-Produkte, ordnet bestehende über Model oder SKU zu und legt die übrigen an. Verknüpfte Produkte übernehmen Name und Preis aus OpenCart.',
'Oc_Pull_Stock' => 'OpenCart-Mengen als Anfangsbestand für neue Produkte verwenden',
'Oc_Reset_Confirm' => 'Produktverknüpfungen zurücksetzen? Die Bestellhistorie behält ihre Verknüpfungen.',
'Oc_Stock_Desc' => 'Setzt die Shop-Menge jedes verknüpften Produkts und jeder Variante auf den hier geführten Bestand.',
'Oc_Orders_Desc' => 'Importiert Shop-Bestellungen als Verkäufe (Referenzen wie {ref}). Bei bereits importierten Bestellungen werden nur Status und Zahlung aktualisiert, ein erneuter Abruf ist also unbedenklich.',
'Oc_Orders_Since' => 'Bestellungen seit',
'Oc_Guide_1' => 'Laden Sie auf dem Tab „Verbindung“ den {company} Connector herunter.',
'Oc_Guide_2' => 'Laden Sie die Datei in Ihrem OpenCart-Admin unter {installer} hoch und klicken Sie auf Install; installieren Sie dann das Modul unter {modules}.',
'Oc_Guide_3' => 'Öffnen Sie das Modul {name} und kopieren Sie die Shop-URL und das Secret.',
'Oc_Guide_4' => 'Fügen Sie beides auf dem Tab „Verbindung“ ein, speichern Sie und führen Sie {test} aus. Dabei erfährt der Shop auch, wohin neue Bestellungen gesendet werden sollen.',
'Oc_Guide_5' => 'Richten Sie die Produkte ein: Rufen Sie sie ab, wenn der Shop bereits einen Katalog hat, oder übertragen Sie sie, wenn {company} ihn hat. Tun Sie dies, bevor Sie sich auf den automatischen Bestandsabgleich verlassen, denn {company} wird zur Quelle der Bestandszahlen.',
'Oc_Guide_6' => 'Rufen Sie einmalig die letzten Bestellungen ab, wenn Sie eine Historie wünschen. Danach kommen Bestellungen von selbst an.',
'Oc_Identity_Title' => 'Produkte werden über Model und SKU zugeordnet',
'Oc_Identity_Desc' => 'Der Produktcode hier wird mit Model und SKU in OpenCart abgeglichen. Halten Sie diese auf beiden Seiten identisch. Der Bestand hier ist maßgeblich: Der Shop wird nach jeder Bestellung daraus aktualisiert.',
'Oc_Options_Title' => 'Optionen ohne Varianten',
'Oc_Options_Desc' => 'OpenCart-Varianten haben einen eigenen Bestand und werden den Varianten hier zugeordnet. Ein Produkt, das nur Optionen und keine angelegten Varianten hat, wird als ein Produkt importiert, und sein Bestand wird nicht nach Optionen aufgeteilt.',
'Oc_Cancel_Title' => 'Stornierte Bestellungen',
'Oc_Cancel_Desc' => 'Wird eine Bestellung in OpenCart storniert, wird der zugehörige Verkauf hier rückgängig gemacht. Wurde der Verkauf bereits geliefert oder gibt es eine Rückgabe, wird nichts rückgängig gemacht: Der Verkauf wird in seinen Notizen und in den Protokollen zur Prüfung markiert.',
'Oc_Download_Connector_3' => 'Für OpenCart 3 herunterladen',
'Oc_Opencart3_Title' => 'OpenCart-3-Shops',
'Oc_Opencart3_Desc' => 'OpenCart 3 hat keine eigenen Varianten, nur Optionen. Ein Produkt mit einer Option (etwa Größe) wird mit Bestand je Optionswert synchronisiert, der den Varianten hier zugeordnet wird. Bei einem Produkt mit mehreren Optionen werden die Optionen ohne Bestand je Kombination angelegt: Sein Bestand wird für das Produkt als Ganzes geführt, und seine Verkaufspositionen werden auf das Produkt gebucht.',
'Oc_G_Title' => 'OpenCart-Leitfaden',
'Oc_G_Open_Settings' => 'OpenCart-Einstellungen öffnen',
'Oc_G_Your_Setup' => 'Ihre Einrichtung',
'Oc_G_Your_Setup_Help' => 'Der aktuelle Stand dieses Arbeitsbereichs. Die Schritte werden laufend aktualisiert.',
'Oc_G_Step_Install' => 'Den {company} Connector in Ihrem Shop installieren',
'Oc_G_Step_Install_Help' => 'Eine kleine Erweiterung, die {company} Zugriff auf Produkte, Bestand und Bestellungen gibt. OpenCart selbst bietet dafür keine API.',
'Oc_G_Step_Connect' => 'Shop verbinden',
'Oc_G_Step_Connect_Help' => 'Fügen Sie die Shop-URL und das Secret von der Modulseite auf dem Tab „Verbindung“ ein, speichern Sie und führen Sie dann „Verbindung testen“ aus.',
'Oc_G_Step_Connect_Done' => 'Verbunden: Connector {connector} auf OpenCart {opencart}.',
'Oc_G_Step_Enable' => 'Synchronisierung einschalten',
'Oc_G_Step_Enable_Help' => 'Solange die Integration deaktiviert ist, wird nichts übertragen; Webhooks des Shops werden bestätigt und ignoriert.',
'Oc_G_Step_Products' => 'Produkte verknüpfen',
'Oc_G_Step_Products_Help' => 'Rufen Sie den Katalog des Shops ab oder übertragen Sie Ihren, damit jedes Produkt auf beiden Seiten verknüpft ist, bevor der Bestandsabgleich beginnt.',
'Oc_G_Step_Products_Done' => '{n} Produkte und {v} Varianten verknüpft.',
'Oc_G_Step_Orders' => 'Bestellungen empfangen',
'Oc_G_Step_Orders_Help' => 'Nach dem Verbinden kommen neue Bestellungen von selbst an. Geben Sie eine Testbestellung im Shop auf, um zu sehen, wie sie unter Verkäufe erscheint.',
'Oc_G_Step_Orders_No_Webhook' => 'Es wurden Bestellungen importiert, aber noch keine kam über die Benachrichtigung des Shops an. Kann der Shop diese Adresse nicht erreichen, kommen Bestellungen trotzdem über die Prüfung alle paar Minuten an.',
'Oc_G_Step_Orders_Done' => 'Der Shop sendet Bestellbenachrichtigungen.',
'Oc_G_Install_Title' => 'Connector installieren',
'Oc_G_Install_Intro' => 'Wählen Sie Ihre OpenCart-Version. Der Connector wird über den OpenCart-eigenen Erweiterungs-Installer installiert; es werden keine Dateien von Hand bearbeitet.',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'Laden Sie den Connector für OpenCart 4 herunter.',
'Oc_G_I4_2' => 'Öffnen Sie in Ihrem OpenCart-Admin {path}, laden Sie die Datei hoch und klicken Sie daneben auf Install.',
'Oc_G_I4_3' => 'Öffnen Sie {path}, suchen Sie {name} und klicken Sie auf Install, dann auf Edit.',
'Oc_G_I3_1' => 'Laden Sie den Connector für OpenCart 3 herunter.',
'Oc_G_I3_2' => 'Öffnen Sie in Ihrem OpenCart-Admin {path}, laden Sie die Datei hoch und warten Sie, bis alle Schritte abgeschlossen sind.',
'Oc_G_I3_3' => 'Öffnen Sie {path}, suchen Sie {name} und klicken Sie auf Install, dann auf Edit.',
'Oc_G_I_4' => 'Die Modulseite zeigt die Shop-URL und ein Secret. Kopieren Sie beides.',
'Oc_G_I_5' => 'Fügen Sie beides hier auf dem Tab „Verbindung“ ein, speichern Sie und führen Sie {test} aus. Dabei erfährt der Shop auch, wohin Bestellbenachrichtigungen gesendet werden sollen.',
'Oc_G_Requirements' => 'Was der Shop benötigt',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 oder 4.0 und höher, PHP mit cURL (bei jedem Hoster Standard) und eine aus dem Internet erreichbare Shop-Adresse. Liegt der Shop in einem privaten Netzwerk, kommen Bestellungen trotzdem über die Prüfung alle paar Minuten an, sofern dieser Arbeitsbereich den Shop erreichen kann.',
'Oc_G_First_Title' => 'Die erste Synchronisierung',
'Oc_G_First_Shop_Has' => 'Der Shop hat bereits den Katalog',
'Oc_G_First_Shop_Has_Text' => 'Rufen Sie die Produkte auf dem Tab „Produkte“ ab. Produkte werden über Model oder SKU Ihren Produktcodes zugeordnet und bei Bedarf angelegt; aktivieren Sie die Bestandsoption, um die Shop-Mengen als Anfangsbestand zu übernehmen.',
'Oc_G_First_Company_Has' => '{company} hat den Katalog',
'Oc_G_First_Company_Has_Text' => 'Übertragen Sie die Produkte. Fehlende Produkte werden mit ihrem Bestand im Shop angelegt; vorhandene werden über Model oder SKU verknüpft und aktualisiert.',
'Oc_G_First_Both' => 'Beide Seiten haben Produkte',
'Oc_G_First_Both_Text' => 'Rufen Sie zuerst ab, damit vorhandene Shop-Produkte verknüpft statt doppelt angelegt werden, und übertragen Sie dann, um anzulegen, was dem Shop fehlt. Halten Sie Produktcodes und Model auf beiden Seiten identisch.',
'Oc_G_Stock_Master' => '{company} führt den Bestand',
'Oc_G_Stock_Master_Desc' => 'Nach der ersten Synchronisierung wird die Menge im Shop immer von {company} geschrieben. Eine in OpenCart geänderte Menge hat keine dauerhafte Wirkung: Die nächste Bewegung oder die stündliche Prüfung überschreibt sie.',
'Oc_G_How_Title' => 'So funktioniert es',
'Oc_G_T_Products' => 'Produkte',
'Oc_G_Products_1' => 'Ein Produkt wird über seinen Code hier mit Model und SKU im Shop abgeglichen. Die Verknüpfung wird gespeichert, sodass ein späteres Umbenennen des Produkts sie nicht aufhebt.',
'Oc_G_Products_2' => 'Wenn {company} ein Produkt überträgt, setzt es Model, SKU, Name, Preis, Status und Bestand. Beschreibung, Bild und Kategorie werden nur geschrieben, wenn das Produkt im Shop neu ist oder keine hat, sodass in OpenCart verfasste Texte erhalten bleiben.',
'Oc_G_Products_3' => 'Ein Produkt, das im Onlineshop ausgeblendet oder hier nicht zum Verkauf bestimmt ist, wird im Shop nicht angelegt; ein bereits verknüpftes wird dort stattdessen deaktiviert.',
'Oc_G_T_Variants' => 'Varianten und Optionen',
'Oc_G_Variants_4' => 'OpenCart 4 hat echte Varianten (ein Produkt mit Auswahl nach Farbe und Größe), jede mit eigenem Bestand. Sie werden in beide Richtungen Ihren Varianten zugeordnet, jede über ihr eigenes Model.',
'Oc_G_Variants_3' => 'OpenCart 3 hat keine Varianten, nur Optionen, und Bestand je Optionswert. Ein Produkt mit einer Option (etwa Größe) wird mit Bestand je Wert synchronisiert, der Ihren Varianten zugeordnet wird. Bei einem Produkt mit mehreren Optionen werden die Optionen ohne Bestand je Kombination angelegt: Sein Bestand bleibt beim Produkt als Ganzes, und seine Verkaufspositionen werden auf das Produkt gebucht.',
'Oc_G_Variants_Multi' => 'Ein Shop-Produkt, das nur Optionen und keine angelegten Varianten hat, wird als ein Produkt importiert; dies wird in den Protokollen vermerkt.',
'Oc_G_T_Stock' => 'Bestand',
'Oc_G_Stock_1' => 'Bei eingeschaltetem Bestandsabgleich aktualisiert jede Bewegung hier (Verkauf, Rückgabe, Einkauf, Bestandskorrektur, Umlagerung) den Shop innerhalb von Sekunden, nachdem die Seite geantwortet hat – der Kassierer wartet also nie auf den Shop.',
'Oc_G_Stock_2' => 'Einmal pro Stunde wird jedes verknüpfte Produkt geprüft und korrigiert; so werden auch Massenänderungen erfasst, die die Live-Übertragung nicht sieht. Der Tab „Bestand“ überträgt alles auf Abruf.',
'Oc_G_Stock_3' => 'Dienstleistungen, als „immer auf Lager“ markierte Produkte und Kombis mit unbegrenzten Komponenten werden im Shop als immer verfügbar angezeigt. Wählen Sie auf dem Tab „Verbindung“ ein Lager, um nur dieses Lager zu zählen; andernfalls werden alle Lager zusammengerechnet.',
'Oc_G_T_Orders' => 'Bestellungen und Status',
'Oc_G_Orders_1' => 'Eine neue oder geänderte Bestellung meldet der Shop sofort, und sie wird über die signierte Verbindung zurückgelesen – dem Inhalt der Benachrichtigung selbst wird also nicht vertraut. Alle paar Minuten ruft eine Prüfung ab, was eine Benachrichtigung verpasst hat. Jede Bestellung wird zu einem Verkauf mit der Referenz OC-<order number>; der Kunde wird per E-Mail zugeordnet oder neu angelegt.',
'Oc_G_Col_List' => 'Statusliste',
'Oc_G_Col_Meaning' => 'Was sie hier bewirkt',
'Oc_G_Col_Default' => 'Aus Ihrem Shop übernommen',
'Oc_G_Default_Commit' => 'Die Status, die in OpenCart Bestand abziehen (standardmäßig Pending, Processing, Shipped, Complete)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'Die Listen werden bei der ersten Verbindung aus Ihrem Shop befüllt und können auf dem Tab „Verbindung“ geändert werden. Halten Sie die erste Liste identisch mit den Status, die in OpenCart Bestand abziehen, damit beide Seiten den Bestand im selben Schritt bewegen.',
'Oc_G_Orders_3' => 'Eine Bestellung mit einem Artikel, der keinem Produkt entspricht, wird zurückgehalten, und das Produkt wird aus dem Shop importiert, falls es dort existiert. Zurückgehaltene Bestellungen werden bei jeder geplanten Prüfung erneut versucht; nach zwölf Versuchen werden sie protokolliert und bleiben für einen manuellen Abruf liegen.',
'Oc_G_T_Cancel' => 'Stornierungen und Erstattungen',
'Oc_G_Cancel_1' => 'Erreicht eine Bestellung im Shop einen Stornostatus, wird ihr Verkauf hier rückgängig gemacht: Der Bestand wird zurückgebucht, die Zahlungen werden entfernt und der Verkauf wird gelöscht – genau wie beim Löschen auf der Seite „Verkäufe“.',
'Oc_G_Cancel_2' => 'Ein bereits gelieferter Verkauf, einer mit Rückgabe oder einer, der von einer Steuerbehörde akzeptiert wurde, wird vom Shop nie rückgängig gemacht. Er wird in seinen Notizen und in den Protokollen zur Prüfung markiert.',
'Oc_G_Cancel_3' => 'Wird die Bestellung im Shop später wiederhergestellt, kommt sie erneut als neuer Verkauf an.',
'Oc_G_T_Automation' => 'Automatisierungsschalter',
'Oc_G_Auto_1' => 'Bestellungen automatisch importieren: Bestellbenachrichtigungen und die geplante Prüfung. Ausgeschaltet kommen Bestellungen nur an, wenn Sie sie auf dem Tab „Bestellungen“ abrufen.',
'Oc_G_Auto_2' => 'Bestand automatisch übertragen: Live-Bestandsaktualisierungen und die stündliche Prüfung. Ausgeschaltet ändert sich der Shop nur, wenn Sie den Bestand manuell übertragen.',
'Oc_G_Auto_3' => 'Produktänderungen automatisch übertragen: Ein hier angelegtes oder bearbeitetes Produkt aktualisiert den Shop sofort. Ausgeschaltet nutzen Sie den Tab „Produkte“.',
'Oc_G_T_Faq' => 'Fragen',
'Oc_G_Q_Secret' => '„Verbindung testen“ meldet, dass das Secret nicht übereinstimmt',
'Oc_G_A_Secret' => 'Öffnen Sie das Modul {company} Connector in OpenCart und kopieren Sie das Secret erneut; ein neu installiertes Modul erhält ein neues. Fügen Sie es auf dem Tab „Verbindung“ ein und speichern Sie vor dem Test.',
'Oc_G_Q_Clock' => '„Verbindung testen“ meldet, dass die Uhr des Shops zu stark abweicht',
'Oc_G_A_Clock' => 'Signierte Anfragen enthalten die Uhrzeit und werden abgelehnt, wenn die beiden Uhren um mehr als fünf Minuten abweichen. Stellen Sie Datum und Uhrzeit auf dem Server des Shops ein.',
'Oc_G_Q_Redirect' => '„Verbindung testen“ meldet, dass der Shop auf eine andere Adresse umleitet',
'Oc_G_A_Redirect' => 'Ihr Shop antwortet unter einer anderen Adresse, meist mit https statt http oder mit www. Verwenden Sie die in der Meldung angezeigte Adresse als Shop-URL.',
'Oc_G_Q_Not_Answering' => '„Verbindung testen“ meldet, dass der Connector nicht geantwortet hat',
'Oc_G_A_Not_Answering' => 'Die Adresse ist kein OpenCart-Shop, oder das Modul ist nicht installiert oder deaktiviert. Prüfen Sie die Shop-URL und dann, ob der {company} Connector unter Extensions → Modules als installiert und aktiviert angezeigt wird.',
'Oc_G_Q_No_Orders' => 'Bestellungen werden im Shop aufgegeben, erscheinen aber erst nach Minuten',
'Oc_G_A_No_Orders' => 'Der Shop kann diesen Arbeitsbereich nicht erreichen, daher kommen Bestellungen nur über die geplante Prüfung an. Sehen Sie sich die {company}-Adresse auf der Modulseite an: Sie muss vom Server des Shops aus erreichbar sein. „Verbindung testen“ registriert sie erneut.',
'Oc_G_Q_Stock_Wrong' => 'Eine Menge im Shop ist falsch',
'Oc_G_A_Stock_Wrong' => 'Übertragen Sie den Bestand auf dem Tab „Bestand“; dabei wird jedes verknüpfte Produkt mit den Zahlen von hier überschrieben. Weicht er immer wieder ab, prüfen Sie, ob der Bestandsabgleich eingeschaltet ist und niemand Mengen in OpenCart bearbeitet.',
'Oc_G_Q_Out_Of_Stock' => 'Ein Produkt wird im Shop als nicht vorrätig angezeigt, obwohl hier Bestand vorhanden ist',
'Oc_G_A_Out_Of_Stock' => 'Unter OpenCart 3 führt ein Produkt mit mehreren Optionen seinen Bestand für das Produkt als Ganzes; prüfen Sie die Menge des Produkts im Shop statt die seiner Optionen. Übertragen Sie bei jedem Produkt einmal den Bestand und sehen Sie in den Protokollen für dieses Produkt nach.',
'Oc_G_Q_Held' => 'Die Protokolle melden eine zurückgehaltene Bestellung',
'Oc_G_A_Held' => 'Einer ihrer Artikel entspricht keinem Produkt hier und konnte nicht aus dem Shop importiert werden, meist weil das Produkt dort gelöscht wurde. Legen Sie das Produkt an oder verknüpfen Sie es und rufen Sie dann die Bestellungen auf dem Tab „Bestellungen“ ab.',
'Oc_G_Q_Deleted_Sale' => 'Ich habe einen importierten Verkauf gelöscht, und er ist wieder da',
'Oc_G_A_Deleted_Sale' => 'Solange die Bestellung im Shop aktiv ist, importiert die nächste Benachrichtigung oder Prüfung sie erneut. Stornieren Sie stattdessen die Bestellung im Shop; dadurch wird der Verkauf hier rückgängig gemacht.',
'Oc_G_Q_Uninstall' => 'Wie trenne ich die Verbindung zum Shop?',
'Oc_G_A_Uninstall' => 'Schalten Sie die Synchronisierung auf dem Tab „Verbindung“ aus; solange sie aus ist, wird nichts übertragen. Um die Integration aus dem Shop zu entfernen, deinstallieren Sie den {company} Connector unter Extensions → Modules.',
'Oc_Full_Guide' => 'Vollständigen Leitfaden öffnen',
'Comm_Receipt_Account_Hint' => 'Das Kassen- oder Bankkonto, von dem diese Auszahlung abgeht. Sein Saldo sinkt um den Betrag, und in der Buchhaltung wird Provisionsaufwand (Sales Commission Expense) dagegen gebucht.',
'Comm_G_Q_Ledger' => 'Was bewirkt eine Provisionsauszahlung in der Buchhaltung?',
'Comm_G_A_Ledger' => 'Wenn Sie einen Beleg erstellen und ein Konto wählen, sinkt dessen Saldo um den Belegbetrag, und bei aktivierten automatischen Buchungen wird gebucht: Soll Provisionsaufwand (Sales Commission Expense, 5200-COMM), Haben das gewählte Kassen- oder Bankkonto. Ohne gewähltes Konto geht die Habenbuchung auf das Standard-Kassenkonto (Cash), und kein Saldo ändert sich.',
