'Oc_Code_Source' => 'Quelle des Produktcodes',
'Oc_Code_Source_Help' => 'Welches OpenCart-Feld hier als Produktcode dient. Model ist in OpenCart ein Pflichtfeld, daher tragen manche Shops dort eine Kategorie oder Produktart ein und führen die eigentliche Artikelnummer in SKU, ISBN, UPC, EAN, JAN oder MPN; wählen Sie für einen solchen Shop dieses Feld. Ist das gewählte Feld leer, werden Model und dann SKU verwendet. Gilt für abgerufene Produkte, die Zuordnung und Übertragungen.',
