'Store_Warehouses_Help' => 'Online angezeigter und abgebuchter Bestand stammt aus diesen Lagern. Solange „Produkte nach Lager einschränken“ unter Funktionen aktiv ist, listet der Shop außerdem nur Produkte, die zu diesen Lagern gehören (oder dort Bestand haben).',
'Oc_Code_Source_Needs_Update' => 'Der im Shop installierte Connector (Version {version}) übermittelt nur Model und SKU. Laden Sie den Connector erneut herunter und laden Sie ihn im Shop über den alten hoch, damit dieses Feld gelesen wird.',
'Oc_L_Title' => 'OpenCart-Protokolle',
'Oc_L_Intro' => 'Jeder Produktabruf, jede Übertragung, Bestandsaktualisierung, Bestellung und jeder Shop-Aufruf wird hier erfasst. Filtern Sie nach Fehlern, um zu sehen, was fehlgeschlagen ist, öffnen Sie eine Zeile, um zu lesen, was sie bedeutet und was zu tun ist, und exportieren Sie die Liste, wenn Sie sie an den Support senden möchten.',
