'Oc_L_H_Secret' => 'Das hier gespeicherte Secret stimmt nicht mit dem des Connector-Moduls in OpenCart überein, daher lehnt der Shop jeden Aufruf ab.',
'Oc_L_F_Secret' => 'Öffnen Sie in OpenCart Extensions → Modules → den Connector, kopieren Sie das dort angezeigte Secret, fügen Sie es auf dem Tab „Verbindung“ ein und speichern Sie. Bei einer Neuinstallation des Moduls wird ein neues Secret erzeugt.',
'Oc_L_H_Clock' => 'Die Uhr des OpenCart-Servers weicht zu stark von unserer ab, daher erscheinen signierte Anfragen als abgelaufen.',
'Oc_L_F_Clock' => 'Bitten Sie Ihren Hosting-Anbieter, die Serverzeit einzustellen (NTP). Schon wenige Minuten Abweichung blockieren die Verbindung.',
'Oc_L_H_Disabled' => 'Das Connector-Modul ist in OpenCart installiert, aber ausgeschaltet.',
'Oc_L_F_Disabled' => 'Öffnen Sie in OpenCart Extensions → Modules → den Connector und setzen Sie Status auf Enabled.',
'Oc_L_H_Unreachable' => 'Der Shop hat unter der gespeicherten Adresse nicht geantwortet, oder das Connector-Modul ist dort nicht installiert.',
'Oc_L_F_Unreachable' => 'Öffnen Sie die Shop-URL im Browser, um zu prüfen, ob der Shop online ist, vergewissern Sie sich, dass das Connector-Modul installiert und aktiviert ist, und prüfen Sie, dass keine Firewall und kein Wartungsmodus unseren Server blockiert.',
'Oc_L_H_Redirect' => 'Der Shop leitet Besucher auf eine andere Adresse um (zum Beispiel von http auf https oder auf www).',
'Oc_L_F_Redirect' => 'Speichern Sie die in der Meldung genannte Adresse auf dem Tab „Verbindung“ als Shop-URL.',
'Oc_L_H_Not_Configured' => 'Shop-URL oder Secret fehlen, daher kann noch nichts gesendet werden.',
'Oc_L_F_Not_Configured' => 'Tragen Sie auf dem Tab „Verbindung“ Shop-URL und Secret ein, speichern Sie und führen Sie „Verbindung testen“ aus.',
'Oc_L_H_Model_Taken' => 'Ein an den Shop übertragenes Produkt hat einen Code, den ein anderes Shop-Produkt oder eine seiner Varianten bereits als Model verwendet.',
'Oc_L_F_Model_Taken' => 'Ändern Sie den Code bei einem der beiden Produkte, oder rufen Sie zuerst die Produkte ab, damit das vorhandene Shop-Produkt verknüpft statt erneut angelegt wird.',
'Oc_L_H_Model_Missing' => 'Ein an den Shop übertragenes Produkt hat keinen Code oder keinen Namen. OpenCart benötigt beides.',
'Oc_L_F_Model_Missing' => 'Geben Sie dem Produkt hier einen Code und einen Namen und übertragen Sie es erneut.',
'Oc_L_H_Held' => 'Eine Bestellung ist eingegangen, aber einige ihrer Artikel entsprechen keinem Produkt hier. Sie wartet daher, und es wurde kein Verkauf angelegt.',
'Oc_L_F_Held' => 'Legen Sie die fehlenden Produkte an oder rufen Sie sie ab (die Artikel sind unten aufgeführt) und rufen Sie dann die Bestellungen erneut ab. Zurückgehaltene Bestellungen werden einige Male automatisch erneut versucht.',
'Oc_L_H_Given_Up' => 'Eine Bestellung konnte nach mehreren Versuchen nicht importiert werden und wird nicht mehr erneut versucht.',
'Oc_L_F_Given_Up' => 'Stellen Sie sicher, dass ihre Produkte hier vorhanden sind, und rufen Sie die Bestellungen dann manuell auf dem Tab „Bestellungen“ ab, mit einem Datum vor der Bestellung.',
'Oc_L_H_Review' => 'Eine Bestellung wurde in OpenCart storniert, nachdem der Verkauf hier geliefert oder zurückgegeben wurde, daher wurde der Bestand nicht automatisch zurückgebucht.',
'Oc_L_F_Review' => 'Öffnen Sie den Verkauf und entscheiden Sie, ob Sie die Artikel zurücknehmen oder ihn unverändert lassen.',
'Oc_L_H_Reversed' => 'Eine Bestellung wurde in OpenCart storniert, und der zugehörige Verkauf hier wurde rückgängig gemacht; sein Bestand wurde zurückgebucht.',
'Oc_L_H_Backlog' => 'Der geplante Bestellabruf hat mehr Bestellungen gefunden, als er in einem Durchlauf verarbeitet, und setzt beim nächsten Mal fort.',
'Oc_L_F_Backlog' => 'Rufen Sie die Bestellungen manuell auf dem Tab „Bestellungen“ ab, um den Rückstand abzuarbeiten.',
'Oc_L_H_Paused' => 'Automatische Übertragungen wurden vorübergehend pausiert, weil der Shop nicht mehr geantwortet hat. Zwischenzeitliche Änderungen werden gesendet, sobald er wieder antwortet.',
'Oc_L_F_Paused' => 'Prüfen Sie, ob der Shop online ist. Sonst ist nichts zu tun; die Warteschlange läuft von selbst weiter.',
'Oc_L_H_Busy' => 'Zwei automatische Übertragungen haben sich überschnitten, und eine wurde zurückgestellt. Es ging nichts verloren.',
'Oc_L_H_Codes_Suffixed' => 'Einige abgerufene Produkte tragen einen Code, den hier bereits ein anderes Shop-Produkt hatte – meist weil das gewählte Codefeld leer ist oder einen Kategorienamen enthält. Sie wurden mit angehängter OpenCart-ID angelegt, damit keine zwei Produkte zusammengeführt werden.',
'Oc_L_F_Codes_Suffixed' => 'Füllen Sie in OpenCart das Codefeld (Model, SKU, ISBN …) für die unten aufgeführten Produkte aus oder wählen Sie auf dem Tab „Verbindung“ eine andere Quelle des Produktcodes; setzen Sie dann die Produktverknüpfungen zurück und rufen Sie erneut ab.',
'Oc_L_H_Options' => 'Einige Shop-Produkte haben Optionen (Größe, Farbe …) ohne Variantenbestand, daher wird der Bestand für das Produkt als Ganzes geführt.',
'Oc_L_F_Options' => 'Es ist nichts zu tun. Um den Bestand je Option zu führen, wandeln Sie diese Optionen in OpenCart 4 in Varianten um oder verwenden Sie in OpenCart 3 eine Option pro Produkt.',
'Oc_L_H_Pull_Ok' => 'Diese Produktseite wurde aus dem Shop gelesen. „Angelegt“ bedeutet ein neues Produkt hier; „aktualisiert“ bedeutet, dass es bereits existierte und verknüpft wurde.',
'Oc_L_H_Pull_Failed' => 'Einige Produkte dieser Seite konnten hier nicht gespeichert werden; jedes ist unten mit dem Grund aufgeführt.',
'Oc_L_F_Pull_Failed' => 'Korrigieren Sie die aufgeführten Produkte in OpenCart (meist fehlt ein Name oder Code) und rufen Sie erneut ab. Nur die fehlgeschlagenen sind betroffen.',
'Oc_L_H_Push_Warnings' => 'Die Produkte wurden an den Shop gesendet, aber der Shop hat bei einigen Probleme gemeldet, etwa ein Bild, das er nicht herunterladen konnte.',
'Oc_L_F_Push_Warnings' => 'Lesen Sie die Liste unten. Bilder müssen vom Shop-Server aus erreichbar sein; alles andere wurde wie gesendet gespeichert.',
'Oc_L_H_Missing_Remote' => 'Der Bestand wurde übertragen, aber einige verknüpfte Produkte existieren im Shop nicht mehr.',
'Oc_L_F_Missing_Remote' => 'Übertragen Sie die Produkte, um sie im Shop neu anzulegen, oder setzen Sie die Produktverknüpfungen zurück, falls sie absichtlich gelöscht wurden.',
'Oc_L_H_Generic' => 'Ein Synchronisierungsschritt ist fehlgeschlagen. Die Meldung oben ist die Begründung des Shops oder des Servers.',
'Oc_L_F_Generic' => 'Führen Sie auf dem Tab „Verbindung“ „Verbindung testen“ aus. Ist der Test erfolgreich, wiederholen Sie den Schritt; schlägt er fehl, folgen Sie dem angezeigten Hinweis.',
'Oc_L_H_Code_Fallback' => 'Einige Produkte dieser Seite kamen ohne Wert in dem Feld an, das als Quelle des Produktcodes gewählt ist, daher wurde ihr Model (oft ein Kategoriename) als Code verwendet.',
'Oc_L_F_Code_Fallback' => 'Prüfen Sie unten „Produkte mit dem jeweiligen Feld“. Zeigt das gewählte Feld 0, obwohl der Shop diese Werte hat, führt der Shop sie unter einem anderen Kennungsnamen; öffnen Sie ein aufgeführtes Produkt in OpenCart (Tab Data, Product Codes) und senden Sie uns, was dort angezeigt wird. Andernfalls füllen Sie das Feld in OpenCart für die aufgeführten Produkte aus und rufen erneut ab.',
'Oc_L_H_Old_Connector' => 'Im Shop läuft noch ein Connector älter als 1.1.0, der nur Model und SKU übermittelt; das gewählte Codefeld kommt daher nie an, und das Model wurde verwendet.',
'Oc_L_F_Old_Connector' => 'Laden Sie den Connector erneut herunter, deinstallieren und löschen Sie den alten in OpenCart (Extensions → Installer), installieren Sie den neuen, fügen Sie sein neues Secret auf dem Tab „Verbindung“ ein und führen Sie „Verbindung testen“ aus. Vor dem Abruf muss die Seite Connector 1.1.0 anzeigen.',
'Oc_L_D_Code_Source' => 'Quelle des Produktcodes',
