'LicK_Rotate_Confirm' => 'Software, die noch den alten öffentlichen Schlüssel enthält, lehnt jede mit dem neuen Schlüssel signierte Antwort ab, bis Sie ihr den neuen öffentlichen Schlüssel ausliefern. Fortfahren?',
