'LicK_G_Status' => 'Liest die Lizenz, ohne etwas zu ändern. Erteilt nie eine Nutzungsfreigabe (valid ist immer false).',
'LicK_G_Request' => 'Anfrage',
'LicK_G_Request_Help' => 'Senden Sie einen JSON-Body mit license_key. product (der Produktcode) ist optional und stellt sicher, dass der Schlüssel zu Ihrem Produkt gehört. Senden Sie domain oder device_id (+ optional device_name) – erforderlich für gebundene Lizenzen und für Lizenzen mit Aktivierungslimit. Senden Sie bei jedem Aufruf eine zufällige nonce und prüfen Sie, ob sie im token zurückkommt.',
'LicK_G_Response' => 'Antwort',
'LicK_G_Response_Help' => 'valid ist nur bei einer activate-/validate-Antwort true, die die Nutzung auf dieser Domain oder diesem Gerät erlaubt. status gibt den Lizenzstatus an. Eine abgelehnte Antwort enthält zusätzlich error und message. Das token wiederholt action, key_fingerprint (SHA-256 Ihres Schlüssels, in Großbuchstaben und ohne Leerzeichen am Rand), identifier, nonce und host – prüfen Sie diese.',
