'LicK_GErr_unavailable' => 'Die Lizenzierungs-API ist ausgeschaltet oder derzeit nicht verfügbar.',
'LicK_G_Verify' => 'Signatur prüfen',
'LicK_G_Verify_Help' => 'token ist die Antwort als Base64-JSON, und signature ist eine Ed25519-Signatur des token-Strings. Prüfen Sie sie mit dem obigen öffentlichen Schlüssel und lesen Sie die Lizenz NUR aus dem dekodierten token (nicht aus den Klartextfeldern). Akzeptieren Sie sie nur, wenn action activate oder validate ist, valid true ist und key_fingerprint, identifier und nonce mit Ihren gesendeten Werten übereinstimmen. Behandeln Sie jede andere Antwort oder eine ohne Signatur als ungültig.',
